INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X01','sci',3,'u4',ARRAY['SC3-1-u4-C1']::text[],'동물과 식물은 먼 숲속이나 동물원에만 살고 우리 주변에는 없다고 여긴다','주변 곳곳에 살아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X02','sci',3,'u4',ARRAY['SC3-1-u4-C2']::text[],'생물은 태어날 때 모습 그대로 평생 똑같이 생겼다고 여긴다','자라며 변해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X03','sci',3,'u4',ARRAY['SC3-1-u4-C3','SC3-1-u4-C4']::text[],'어릴 때 모습과 다 자란 모습, 또는 시작하는 모습의 짝을 뒤바꾼다','올챙이 → 개구리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X04','sci',3,'u4',ARRAY['SC3-1-u4-C5']::text[],'한살이는 동물에게만 있거나, 태어나면 끝나 자손을 남기는 데까지 이어지지 않는다고 여긴다','자손을 남겨 이어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X05','sci',3,'u4',ARRAY['SC3-1-u4-C6','SC3-1-u4-C14']::text[],'생물을 함부로 만지거나 가두어도 되고, 한 번만 보아도 한살이를 다 안다고 여긴다','꾸준히 · 조심히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X06','sci',3,'u4',ARRAY['SC3-1-u4-C7']::text[],'배추흰나비 한살이 순서를 뒤바꾼다','알 → 애벌레 → 번데기 → 어른벌레') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X07','sci',3,'u4',ARRAY['SC3-1-u4-C8','SC3-1-u4-C9','SC3-1-u4-C11']::text[],'알·애벌레·어른벌레와 그 특징의 짝을 뒤바꾼다','단계마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X08','sci',3,'u4',ARRAY['SC3-1-u4-C10']::text[],'번데기가 움직이며 먹이를 먹거나, 움직이지 않으니 죽은 것이라고 여긴다','가만히 있어도 살아 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X09','sci',3,'u4',ARRAY['SC3-1-u4-C12']::text[],'곤충의 몸(머리·가슴·배)과 다리 수(세 쌍)를 잘못 알아 거미도 곤충이라고 여긴다','다리 세 쌍') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X10','sci',3,'u4',ARRAY['SC3-1-u4-C13']::text[],'애벌레가 허물을 벗는 까닭을 색 바꾸기·잠자기·날기로 잘못 안다','더 크게 자라려고') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X11','sci',3,'u4',ARRAY['SC3-1-u4-C11']::text[],'어른벌레가 되면 한살이가 끝나 다시 알을 낳지 않는다고 여긴다','다시 알을 낳아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X12','sci',3,'u4',ARRAY['SC3-1-u4-C16','SC3-1-u4-C20']::text[],'모든 동물은 알을 낳는다고 여긴다','새끼를 낳는 동물도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X13','sci',3,'u4',ARRAY['SC3-1-u4-C15','SC3-1-u4-C16']::text[],'알을 낳는 동물과 새끼를 낳는 동물을 뒤바꾼다','닭 = 알 · 개 = 새끼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X14','sci',3,'u4',ARRAY['SC3-1-u4-C17','SC3-1-u4-C18']::text[],'닭이나 개의 한살이 순서를 뒤바꾼다','어린 모습부터') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X15','sci',3,'u4',ARRAY['SC3-1-u4-C18','SC3-1-u4-C19']::text[],'새끼를 낳는 동물의 새끼가 알껍데기를 깨고 나오거나 어미젖 말고 다른 것을 먹는다고 여긴다','어미젖을 먹어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X16','sci',3,'u4',ARRAY['SC3-1-u4-C20']::text[],'동물마다 한살이가 똑같다고 여긴다','태어나는 방법이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X17','sci',3,'u4',ARRAY['SC3-1-u4-C21']::text[],'동물의 한살이는 조사하지 않고 상상만으로 알 수 있다고 여긴다','자료로 조사해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X18','sci',3,'u4',ARRAY['SC3-1-u4-C22']::text[],'씨는 물이 없어도 싹이 튼다고 여긴다','물이 필요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X19','sci',3,'u4',ARRAY['SC3-1-u4-C23']::text[],'물만 있으면 아주 추운 곳에서도 싹이 튼다고 여긴다','알맞은 온도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X20','sci',3,'u4',ARRAY['SC3-1-u4-C24']::text[],'씨가 싹 트려면 빛이 꼭 있어야 한다고 여긴다','어두워도 싹이 텄어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X21','sci',3,'u4',ARRAY['SC3-1-u4-C25']::text[],'다르게 할 조건을 두 가지 이상 정하거나 그런 두 컵을 견준다','딱 하나만') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X22','sci',3,'u4',ARRAY['SC3-1-u4-C26']::text[],'같게 할 조건을 다르게 하거나 다르게 할 조건과 뒤바꾼다','나머지는 모두 같게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X23','sci',3,'u4',ARRAY['SC3-1-u4-C27']::text[],'실험 결과에서 바꾸지 않은 조건이나 엉뚱한 것(소리·색·돌) 때문이라고 결론 낸다','다르게 한 그 조건') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X24','sci',3,'u4',ARRAY['SC3-1-u4-C28']::text[],'식물은 물이 없어도 잘 자란다고 여긴다','물이 필요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X25','sci',3,'u4',ARRAY['SC3-1-u4-C29']::text[],'식물은 어두운 곳에서도, 또는 어두울수록 잘 자란다고 여긴다','햇빛이 필요해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X26','sci',3,'u4',ARRAY['SC3-1-u4-C30']::text[],'물이나 햇빛 가운데 하나만 있어도 잘 자란다고 여긴다','둘 다 있어야') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X27','sci',3,'u4',ARRAY['SC3-1-u4-C32']::text[],'싹 트는 조건과 자라는 조건이 같다고 여기거나 서로 뒤바꾼다','싹 = 온도 · 자람 = 햇빛') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X28','sci',3,'u4',ARRAY['SC3-1-u4-C33']::text[],'식물마다 한살이 흐름이 전혀 다르거나 씨 없이 시작한다고 여긴다','씨 → 싹 → 자람 → 꽃 → 열매') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X29','sci',3,'u4',ARRAY['SC3-1-u4-C34','SC3-1-u4-C35']::text[],'한해살이 식물과 여러해살이 식물을 뒤바꾼다','사는 기간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X30','sci',3,'u4',ARRAY['SC3-1-u4-C36']::text[],'풀은 모두 한해살이, 나무만 여러해살이라고 여긴다','민들레는 여러해살이 풀') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X31','sci',3,'u4',ARRAY['SC3-1-u4-C37','SC3-1-u4-C47']::text[],'기준을 바꾸어도 무리가 같거나 한 생물은 늘 같은 무리에 든다고 여긴다','기준이 바뀌면 무리도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X32','sci',3,'u4',ARRAY['SC3-1-u4-C38']::text[],'돌·자동차 같은 물건에도 한살이가 있다고 여긴다','생물만 한살이가 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X33','sci',3,'u4',ARRAY['SC3-1-u4-C39']::text[],'동물과 식물의 한살이 시작(알·새끼 / 씨)을 뒤바꾼다','식물은 씨로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X34','sci',3,'u4',ARRAY['SC3-1-u4-C40','SC3-1-u4-C41']::text[],'소개 자료는 꾸미기나 좋아하는 색깔이 가장 중요하다고 여긴다','순서·이름·특징') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X35','sci',3,'u4',ARRAY['SC3-1-u4-C42']::text[],'생물과 맞지 않는 한살이 순서를 고른다','그 생물의 한살이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X36','sci',3,'u4',ARRAY['SC3-1-u4-C43']::text[],'곤충 가운데 알이 아니라 새끼로 태어나는 것도 있다고 여긴다','곤충은 모두 알에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X37','sci',3,'u4',ARRAY['SC3-1-u4-C44','SC3-1-u4-C45']::text[],'모든 곤충은 번데기를 거친다고 여긴다','번데기가 없는 곤충도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X38','sci',3,'u4',ARRAY['SC3-1-u4-C44','SC3-1-u4-C45']::text[],'번데기 단계가 있는 곤충과 없는 곤충을 뒤바꾼다','잠자리·메뚜기·매미 = 없음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X39','sci',3,'u4',ARRAY['SC3-1-u4-C46']::text[],'잠자리 애벌레가 하늘을 날거나 땅 위·나무 속에서 산다고 여긴다','애벌레는 물속') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X40','sci',3,'u4',ARRAY['SC3-1-u4-C41','SC3-1-u4-C42']::text[],'단계 이름만 들어가면 한살이 순서는 뒤바뀌어도 괜찮다고 여긴다','순서가 핵심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SC3-1-u4-X41','sci',3,'u4',ARRAY['SC3-1-u4-C1']::text[],'동물과 식물을 뒤바꾸어 나눈다','스스로 움직이나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#1','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C1',1,'mc','auto','우리 주변에서 볼 수 있는 생물에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X01']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C1","difficulty":1,"kind":"mc","stem":"우리 주변에서 볼 수 있는 생물에 대해 알맞은 것은 무엇인가요?","options":[{"t":"집, 학교, 길가 곳곳에 여러 가지 동물과 식물이 살아요","correct":true},{"t":"동물과 식물은 먼 숲속에만 살아요","mis":"SC3-1-u4-X01"},{"t":"우리 주변에는 식물만 살아요","mis":"SC3-1-u4-X01"},{"t":"동물원과 식물원에만 생물이 있어요","mis":"SC3-1-u4-X01"}],"explanation":["집과 학교를 둘러봐요.","길가에도 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#2','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C5',1,'sa','auto','생물이 나고 자라 다시 자손을 남기는 과정을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-1-u4-C5","difficulty":1,"kind":"sa","stem":"생물이 나고 자라 다시 자손을 남기는 과정을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["한살이"],"explanation":["나고 자라요.","세 글자예요.","「한살이」예요."],"mis":"SC3-1-u4-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#3','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C2',1,'ox','auto','동물과 식물은 자라면서 모습이 조금씩 달라져요.',ARRAY['SC3-1-u4-X02']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C2","difficulty":1,"kind":"ox","stem":"동물과 식물은 자라면서 모습이 조금씩 달라져요.","answer":"O","reason_options":[{"t":"올챙이가 자라 다리가 생긴 개구리가 되듯 생물은 자라면서 모습이 변하기 때문에","correct":true},{"t":"생물은 태어날 때 모습 그대로 평생 똑같이 생겼기 때문에","mis":"SC3-1-u4-X02"}],"mis":"SC3-1-u4-X02","explanation":["올챙이를 떠올려요.","모습이 변해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#4','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C3',1,'mc','auto','생물 수수께끼 카드 ㉰는 어떤 생물인가요?',ARRAY['SC3-1-u4-X03']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C3","difficulty":1,"kind":"mc","stem":"생물 수수께끼 카드 ㉰는 어떤 생물인가요?","options":[{"t":"개구리","correct":true},{"t":"닭","mis":"SC3-1-u4-X03"},{"t":"강낭콩","mis":"SC3-1-u4-X03"},{"t":"배추흰나비","mis":"SC3-1-u4-X03"}],"explanation":["물속 알이에요.","올챙이가 나와요.","개구리예요."],"asset":{"type":"passage","lines":["㉮ 알에서 깨어나 자라 어른이 되고, 다시 알을 낳아요.","㉯ 잎에 낳은 알에서 애벌레가 나와 번데기를 거쳐 날개 달린 나비가 돼요.","㉰ 물속 알에서 올챙이가 나와 다리가 생기며 자라요.","㉱ 씨를 심으면 싹이 트고 자라 꽃이 피고, 다시 씨를 맺어요."],"title":"생물 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#5','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C4',2,'match','auto','어릴 때 모습과 다 자란 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u4-C4","difficulty":2,"kind":"match","stem":"어릴 때 모습과 다 자란 모습을 알맞게 이으세요.","pairs":[{"l":"올챙이","r":"개구리"},{"l":"애벌레","r":"나비"},{"l":"병아리","r":"닭"}],"mis":"SC3-1-u4-X03","explanation":["어릴 때를 떠올려요.","자라면 무엇이 될까요?","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#6','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C3',2,'mc','auto','생물 수수께끼 카드 ㉱의 생물은 무엇에서 한살이를 시작하나요?',ARRAY['SC3-1-u4-X03']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C3","difficulty":2,"kind":"mc","stem":"생물 수수께끼 카드 ㉱의 생물은 무엇에서 한살이를 시작하나요?","options":[{"t":"씨","correct":true},{"t":"알","mis":"SC3-1-u4-X03"},{"t":"올챙이","mis":"SC3-1-u4-X03"},{"t":"병아리","mis":"SC3-1-u4-X03"}],"explanation":["㉱를 읽어요.","심는 것이에요.","씨예요."],"asset":{"type":"passage","lines":["㉮ 알에서 깨어나 자라 어른이 되고, 다시 알을 낳아요.","㉯ 잎에 낳은 알에서 애벌레가 나와 번데기를 거쳐 날개 달린 나비가 돼요.","㉰ 물속 알에서 올챙이가 나와 다리가 생기며 자라요.","㉱ 씨를 심으면 싹이 트고 자라 꽃이 피고, 다시 씨를 맺어요."],"title":"생물 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#7','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C5',2,'ox','auto','한살이는 동물에게만 있고 식물에게는 없어요.',ARRAY['SC3-1-u4-X04']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C5","difficulty":2,"kind":"ox","stem":"한살이는 동물에게만 있고 식물에게는 없어요.","answer":"X","reason_options":[{"t":"강낭콩도 씨에서 싹이 트고 자라 꽃이 피고 다시 씨를 맺으니 식물에게도 한살이가 있기 때문에","correct":true},{"t":"식물은 자라지도 변하지도 않기 때문에","mis":"SC3-1-u4-X04"}],"mis":"SC3-1-u4-X04","explanation":["강낭콩을 떠올려요.","다시 씨를 맺어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#8','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C1',2,'mc','auto','다음 가운데 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X41']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 동물끼리 모은 것은 무엇인가요?","options":[{"t":"닭, 개, 개구리","correct":true},{"t":"닭, 강낭콩, 봉숭아","mis":"SC3-1-u4-X41"},{"t":"강낭콩, 봉숭아, 자두나무","mis":"SC3-1-u4-X41"},{"t":"개, 자두나무, 강낭콩","mis":"SC3-1-u4-X41"}],"explanation":["스스로 움직여요.","세 동물이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#9','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C6',2,'mc','auto','생물의 한살이를 알아보려면 어떻게 하는 것이 가장 좋을까요?',ARRAY['SC3-1-u4-X05']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C6","difficulty":2,"kind":"mc","stem":"생물의 한살이를 알아보려면 어떻게 하는 것이 가장 좋을까요?","options":[{"t":"꾸준히 관찰하며 자라는 모습을 살펴봐요","correct":true},{"t":"한 번만 힐끗 보고 지나가요","mis":"SC3-1-u4-X05"},{"t":"생물을 마구 만지며 놀아요","mis":"SC3-1-u4-X05"},{"t":"아무것도 보지 않고 넘어가요","mis":"SC3-1-u4-X05"}],"explanation":["생물은 천천히 변해요.","여러 번 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_basic#10','sci',3,1,'u4','L01','g3_1_sci_u4_L01_basic','lesson_basic','SC3-1-u4-C5',3,'mc','auto','생물 수수께끼 카드 ㉮~㉱에 모두 들어 있는 한살이의 모습은 무엇인가요?',ARRAY['SC3-1-u4-X02','SC3-1-u4-X04','SC3-1-u4-X03']::text[],false,'{"seq":10,"concept":"SC3-1-u4-C5","difficulty":3,"kind":"mc","stem":"생물 수수께끼 카드 ㉮~㉱에 모두 들어 있는 한살이의 모습은 무엇인가요?","options":[{"t":"어린 모습으로 시작해 자라서, 다시 자손을 남겨요","correct":true},{"t":"태어난 모습 그대로 자라지 않아요","mis":"SC3-1-u4-X02"},{"t":"한 번 태어나면 자손을 남기지 않아요","mis":"SC3-1-u4-X04"},{"t":"모두 알에서만 시작해요","mis":"SC3-1-u4-X03"}],"explanation":["네 카드를 견줘요.","끝에 다시 남겨요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉮ 알에서 깨어나 자라 어른이 되고, 다시 알을 낳아요.","㉯ 잎에 낳은 알에서 애벌레가 나와 번데기를 거쳐 날개 달린 나비가 돼요.","㉰ 물속 알에서 올챙이가 나와 다리가 생기며 자라요.","㉱ 씨를 심으면 싹이 트고 자라 꽃이 피고, 다시 씨를 맺어요."],"title":"생물 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#1','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C5',2,'blank','auto','「생물이 나고 자라 다시 (      ) 남기는 과정을 한살이라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u4-X04']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C5","difficulty":2,"kind":"blank","stem":"「생물이 나고 자라 다시 (      ) 남기는 과정을 한살이라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"자손을","correct":true},{"t":"이름을","mis":"SC3-1-u4-X04"},{"t":"발자국을","mis":"SC3-1-u4-X04"},{"t":"집을","mis":"SC3-1-u4-X04"}],"explanation":["다음 생물이에요.","새끼나 씨예요.","「자손을」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#2','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C4',2,'mc','auto','병아리가 다 자라면 무엇이 되나요?',ARRAY['SC3-1-u4-X03']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C4","difficulty":2,"kind":"mc","stem":"병아리가 다 자라면 무엇이 되나요?","options":[{"t":"닭","correct":true},{"t":"개구리","mis":"SC3-1-u4-X03"},{"t":"나비","mis":"SC3-1-u4-X03"},{"t":"강낭콩","mis":"SC3-1-u4-X03"}],"explanation":["알에서 깨어났어요.","꼬끼오!","닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#3','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C3',3,'error','auto','친구들이 생물 수수께끼 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u4-X03']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C3","difficulty":3,"kind":"error","stem":"친구들이 생물 수수께끼 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉯는 물속 알에서 올챙이가 나오는 개구리야.」","correct":true,"mis_target":"SC3-1-u4-X03"},{"t":"친구 가 — 「㉮는 알에서 깨어나는 닭이야.」","mis":"SC3-1-u4-X03"},{"t":"친구 다 — 「㉱는 씨에서 싹이 트는 강낭콩이야.」","mis":"SC3-1-u4-X03"}],"explanation":["㉯를 다시 읽어요.","번데기가 있어요.","친구 나예요."],"asset":{"type":"passage","lines":["㉮ 알에서 깨어나 자라 어른이 되고, 다시 알을 낳아요.","㉯ 잎에 낳은 알에서 애벌레가 나와 번데기를 거쳐 날개 달린 나비가 돼요.","㉰ 물속 알에서 올챙이가 나와 다리가 생기며 자라요.","㉱ 씨를 심으면 싹이 트고 자라 꽃이 피고, 다시 씨를 맺어요."],"title":"생물 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#4','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C2',3,'mc','auto','올챙이와 개구리를 바르게 견준 것은 무엇인가요?',ARRAY['SC3-1-u4-X02','SC3-1-u4-X03']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C2","difficulty":3,"kind":"mc","stem":"올챙이와 개구리를 바르게 견준 것은 무엇인가요?","options":[{"t":"올챙이는 물속에서 헤엄치고, 자라서 다리가 생긴 개구리가 돼요","correct":true},{"t":"올챙이와 개구리는 생김새가 똑같아요","mis":"SC3-1-u4-X02"},{"t":"올챙이는 자라서 나비가 돼요","mis":"SC3-1-u4-X03"},{"t":"개구리는 씨에서 싹이 터서 자라요","mis":"SC3-1-u4-X03"}],"explanation":["다리를 떠올려요.","자라며 생겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#5','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C1',3,'ox','auto','학교 화단에서도 식물을, 집에서도 동물을 관찰할 수 있어요.',ARRAY['SC3-1-u4-X01']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C1","difficulty":3,"kind":"ox","stem":"학교 화단에서도 식물을, 집에서도 동물을 관찰할 수 있어요.","answer":"O","reason_options":[{"t":"동물과 식물은 우리 주변 곳곳에 살기 때문에","correct":true},{"t":"생물은 먼 숲속에만 살기 때문에","mis":"SC3-1-u4-X01"}],"mis":"SC3-1-u4-X01","explanation":["화단을 떠올려요.","집 고양이도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#6','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C6',3,'mc','auto','길에서 알을 깨고 갓 나온 작은 생물을 보았어요. 가장 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u4-X05']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C6","difficulty":3,"kind":"mc","stem":"길에서 알을 깨고 갓 나온 작은 생물을 보았어요. 가장 알맞은 행동은 무엇인가요?","options":[{"t":"함부로 만지지 않고 자라는 모습을 조심히 살펴봐요","correct":true},{"t":"손으로 꽉 잡아 집에 가져가요","mis":"SC3-1-u4-X05"},{"t":"신기해서 막대기로 쿡쿡 찔러 봐요","mis":"SC3-1-u4-X05"},{"t":"보지 않고 그냥 밟고 지나가요","mis":"SC3-1-u4-X05"}],"explanation":["생물도 살아 있어요.","조심히 봐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#7','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C1',3,'mc','auto','생물 수수께끼 카드의 네 생물을 동물과 식물로 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-1-u4-X41']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C1","difficulty":3,"kind":"mc","stem":"생물 수수께끼 카드의 네 생물을 동물과 식물로 바르게 나눈 것은 무엇인가요?","options":[{"t":"동물 — ㉮, ㉯, ㉰ / 식물 — ㉱","correct":true},{"t":"동물 — ㉮, ㉱ / 식물 — ㉯, ㉰","mis":"SC3-1-u4-X41"},{"t":"동물 — ㉮ / 식물 — ㉯, ㉰, ㉱","mis":"SC3-1-u4-X41"},{"t":"넷 다 동물이에요","mis":"SC3-1-u4-X41"}],"explanation":["씨를 맺는 것은?","㉱ 하나예요.","첫 번째예요."],"asset":{"type":"passage","lines":["㉮ 알에서 깨어나 자라 어른이 되고, 다시 알을 낳아요.","㉯ 잎에 낳은 알에서 애벌레가 나와 번데기를 거쳐 날개 달린 나비가 돼요.","㉰ 물속 알에서 올챙이가 나와 다리가 생기며 자라요.","㉱ 씨를 심으면 싹이 트고 자라 꽃이 피고, 다시 씨를 맺어요."],"title":"생물 수수께끼 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#8','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C2',4,'mc','auto','친구가 「병아리는 처음부터 다 자란 닭과 똑같이 생겼어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X02','SC3-1-u4-X03']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C2","difficulty":4,"kind":"mc","stem":"친구가 「병아리는 처음부터 다 자란 닭과 똑같이 생겼어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「병아리는 작은 모습으로 깨어나 자라면서 점점 다 자란 닭의 모습이 돼.」","correct":true},{"t":"「맞아, 생물은 평생 똑같이 생겼어.」","mis":"SC3-1-u4-X02"},{"t":"「병아리는 자라서 개구리가 돼.」","mis":"SC3-1-u4-X03"},{"t":"「병아리는 씨에서 싹이 터서 생겨.」","mis":"SC3-1-u4-X03"}],"explanation":["병아리를 떠올려요.","자라며 변해요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#9','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C5',4,'mc','auto','친구가 「한살이는 생물이 태어나는 순간만을 말해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X04','SC3-1-u4-X05']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C5","difficulty":4,"kind":"mc","stem":"친구가 「한살이는 생물이 태어나는 순간만을 말해.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「한살이는 나고 자라 다시 자손을 남기기까지의 과정이야. 그래서 다시 이어져.」","correct":true},{"t":"「맞아, 태어나면 한살이가 끝나.」","mis":"SC3-1-u4-X04"},{"t":"「한살이는 동물에게만 있어.」","mis":"SC3-1-u4-X04"},{"t":"「한살이는 꾸준히 보지 않아도 다 알 수 있어.」","mis":"SC3-1-u4-X05"}],"explanation":["한살이의 뜻을 떠올려요.","자손까지예요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L01_challenge#10','sci',3,1,'u4','L01','g3_1_sci_u4_L01_challenge','lesson_challenge','SC3-1-u4-C4',4,'essay','teacher','내가 본 동물이나 식물 하나를 골라 어릴 때 모습과 다 자란 모습을 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C4","difficulty":4,"kind":"essay","stem":"내가 본 동물이나 식물 하나를 골라 어릴 때 모습과 다 자란 모습을 견주어 쓰세요.","answer_guide":{"answer":"예: 개구리는 어릴 때 물속에서 헤엄치는 올챙이였는데, 자라면서 다리가 생겨 개구리가 되었다.","scoring_points":["생물 하나를 골랐는가","어릴 때 모습을 썼는가","다 자란 모습과 달라진 점을 썼는가"]},"explanation":["본 생물을 떠올려요.","어릴 때는 어땠나요?","달라진 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_basic#1','sci',3,1,'u4','L02','g3_1_sci_u4_L02_basic','lesson_basic','SC3-1-u4-C7',1,'mc','auto','배추흰나비의 한살이 순서로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X06']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C7","difficulty":1,"kind":"mc","stem":"배추흰나비의 한살이 순서로 알맞은 것은 무엇인가요?","options":[{"t":"알 → 애벌레 → 번데기 → 어른벌레","correct":true},{"t":"알 → 번데기 → 애벌레 → 어른벌레","mis":"SC3-1-u4-X06"},{"t":"애벌레 → 알 → 어른벌레 → 번데기","mis":"SC3-1-u4-X06"},{"t":"알 → 어른벌레 → 애벌레 → 번데기","mis":"SC3-1-u4-X06"}],"explanation":["알에서 시작해요.","번데기는 어른벌레 앞이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_basic#2','sci',3,1,'u4','L02','g3_1_sci_u4_L02_basic','lesson_basic','SC3-1-u4-C12',1,'sa','auto','몸이 머리, 가슴, 배로 나뉘고 다리가 세 쌍인 동물을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SC3-1-u4-C12","difficulty":1,"kind":"sa","stem":"몸이 머리, 가슴, 배로 나뉘고 다리가 세 쌍인 동물을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["곤충"],"explanation":["배추흰나비도 이 무리예요.","두 글자예요.","「곤충」이에요."],"mis":"SC3-1-u4-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_basic#3','sci',3,1,'u4','L02','g3_1_sci_u4_L02_basic','lesson_basic','SC3-1-u4-C10',1,'ox','auto','배추흰나비 번데기는 한곳에 붙어 움직이지 않아요.',ARRAY['SC3-1-u4-X08']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C10","difficulty":1,"kind":"ox","stem":"배추흰나비 번데기는 한곳에 붙어 움직이지 않아요.","answer":"O","reason_options":[{"t":"번데기 단계에서는 움직이지도 먹지도 않기 때문에","correct":true},{"t":"번데기는 잎을 찾아 바쁘게 기어다니기 때문에","mis":"SC3-1-u4-X08"}],"mis":"SC3-1-u4-X08","explanation":["번데기를 떠올려요.","가만히 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_basic#4','sci',3,1,'u4','L02','g3_1_sci_u4_L02_basic','lesson_basic','SC3-1-u4-C9',1,'mc','auto','배추흰나비 한살이에서 잎을 갉아 먹으며 자라는 단계는 무엇인가요?',ARRAY['SC3-1-u4-X07','SC3-1-u4-X08']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C9","difficulty":1,"kind":"mc","stem":"배추흰나비 한살이에서 잎을 갉아 먹으며 자라는 단계는 무엇인가요?","options":[{"t":"애벌레","correct":true},{"t":"알","mis":"SC3-1-u4-X07"},{"t":"번데기","mis":"SC3-1-u4-X08"},{"t":"어른벌레","mis":"SC3-1-u4-X07"}],"explanation":["잎을 먹어요.","초록색이 돼요.","애벌레예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_basic#5','sci',3,1,'u4','L02','g3_1_sci_u4_L02_basic','lesson_basic','SC3-1-u4-C11',2,'match','auto','배추흰나비 관찰 기록장을 보고 단계와 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u4-C11","difficulty":2,"kind":"match","stem":"배추흰나비 관찰 기록장을 보고 단계와 특징을 알맞게 이으세요.","pairs":[{"l":"알","r":"배춧잎 뒷면에 붙은 노란색"},{"l":"번데기","r":"먹지 않고 움직이지 않음"},{"l":"어른벌레","r":"날개 두 쌍과 다리 세 쌍"}],"mis":"SC3-1-u4-X07","explanation":["기록장을 한 줄씩 읽어요.","특징을 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["알 — 배춧잎 뒷면에 붙어 있음 · 노란색 · 줄무늬가 있음 · 아주 작음","애벌레 — 알껍데기와 잎을 갉아 먹음 · 초록색 · 허물을 벗으며 자람","번데기 — 한곳에 붙어 움직이지 않음 · 먹지 않음 · 주변과 색이 비슷함","어른벌레 — 날개 두 쌍 · 다리 세 쌍 · 꽃의 꿀을 빨아 먹음 · 알을 낳음"],"title":"배추흰나비 관찰 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
