INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_basic#10','sci',3,1,'u4','L02','g3_1_sci_u4_L02_basic','lesson_basic','SC3-1-u4-C14',3,'mc','auto','배추흰나비를 기르며 관찰할 때 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X05']::text[],false,'{"seq":10,"concept":"SC3-1-u4-C14","difficulty":3,"kind":"mc","stem":"배추흰나비를 기르며 관찰할 때 가장 알맞은 것은 무엇인가요?","options":[{"t":"애벌레를 함부로 만지지 않고, 관찰이 끝난 어른벌레는 자연으로 돌려보내요","correct":true},{"t":"애벌레를 손으로 자주 꾹꾹 눌러 봐요","mis":"SC3-1-u4-X05"},{"t":"관찰이 끝나면 사육 상자에 계속 가두어 둬요","mis":"SC3-1-u4-X05"},{"t":"번데기를 떼어 내어 흔들어 봐요","mis":"SC3-1-u4-X05"}],"explanation":["나비도 생명이에요.","조심히 다뤄요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
