INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#2','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C12',2,'mc','auto','곤충의 특징을 바르게 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X09']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C12","difficulty":2,"kind":"mc","stem":"곤충의 특징을 바르게 모은 것은 무엇인가요?","options":[{"t":"몸이 머리, 가슴, 배로 나뉘고 다리가 세 쌍이에요","correct":true},{"t":"몸이 두 부분이고 다리가 여덟 개예요","mis":"SC3-1-u4-X09"},{"t":"다리가 없고 날개만 있어요","mis":"SC3-1-u4-X09"},{"t":"몸이 하나로 되어 있고 다리가 네 개예요","mis":"SC3-1-u4-X09"}],"explanation":["몸이 세 부분이에요.","다리는 세 쌍이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#3','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C10',3,'error','auto','친구들이 배추흰나비 관찰 기록장을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u4-X08','SC3-1-u4-X07']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C10","difficulty":3,"kind":"error","stem":"친구들이 배추흰나비 관찰 기록장을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「번데기는 잎을 많이 먹어서 통통해.」","correct":true,"mis_target":"SC3-1-u4-X08"},{"t":"친구 가 — 「알은 배춧잎 뒷면에 붙어 있어.」","mis":"SC3-1-u4-X07"},{"t":"친구 나 — 「애벌레는 허물을 벗으며 자라.」","mis":"SC3-1-u4-X07"}],"explanation":["번데기 줄을 읽어요.","먹지 않아요.","친구 다예요."],"asset":{"type":"passage","lines":["알 — 배춧잎 뒷면에 붙어 있음 · 노란색 · 줄무늬가 있음 · 아주 작음","애벌레 — 알껍데기와 잎을 갉아 먹음 · 초록색 · 허물을 벗으며 자람","번데기 — 한곳에 붙어 움직이지 않음 · 먹지 않음 · 주변과 색이 비슷함","어른벌레 — 날개 두 쌍 · 다리 세 쌍 · 꽃의 꿀을 빨아 먹음 · 알을 낳음"],"title":"배추흰나비 관찰 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#4','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C10',3,'mc','auto','배추흰나비 관찰 기록장의 번데기처럼 주변과 색이 비슷하면 어떤 점이 좋을까요?',ARRAY['SC3-1-u4-X08','SC3-1-u4-X07','SC3-1-u4-X10']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C10","difficulty":3,"kind":"mc","stem":"배추흰나비 관찰 기록장의 번데기처럼 주변과 색이 비슷하면 어떤 점이 좋을까요?","options":[{"t":"눈에 잘 띄지 않아요","correct":true},{"t":"먹이를 더 많이 먹을 수 있어요","mis":"SC3-1-u4-X08"},{"t":"바로 날아갈 수 있어요","mis":"SC3-1-u4-X07"},{"t":"허물을 벗지 않아도 돼요","mis":"SC3-1-u4-X10"}],"explanation":["주변과 색이 같아요.","찾기 어려워요.","첫 번째예요."],"asset":{"type":"passage","lines":["알 — 배춧잎 뒷면에 붙어 있음 · 노란색 · 줄무늬가 있음 · 아주 작음","애벌레 — 알껍데기와 잎을 갉아 먹음 · 초록색 · 허물을 벗으며 자람","번데기 — 한곳에 붙어 움직이지 않음 · 먹지 않음 · 주변과 색이 비슷함","어른벌레 — 날개 두 쌍 · 다리 세 쌍 · 꽃의 꿀을 빨아 먹음 · 알을 낳음"],"title":"배추흰나비 관찰 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#5','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C7',3,'mc','auto','배추흰나비 어른벌레가 알을 낳은 뒤에는 어떻게 될까요?',ARRAY['SC3-1-u4-X11','SC3-1-u4-X06']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C7","difficulty":3,"kind":"mc","stem":"배추흰나비 어른벌레가 알을 낳은 뒤에는 어떻게 될까요?","options":[{"t":"알에서 다시 애벌레가 나와 한살이가 이어져요","correct":true},{"t":"알은 돌처럼 그대로 있고 아무것도 나오지 않아요","mis":"SC3-1-u4-X11"},{"t":"알에서 바로 어른벌레가 나와요","mis":"SC3-1-u4-X06"},{"t":"알에서 번데기가 먼저 나와요","mis":"SC3-1-u4-X06"}],"explanation":["알 다음은?","애벌레예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#6','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C11',3,'ox','auto','배추흰나비 어른벌레는 다리가 세 쌍이고 날개가 두 쌍이에요.',ARRAY['SC3-1-u4-X07']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C11","difficulty":3,"kind":"ox","stem":"배추흰나비 어른벌레는 다리가 세 쌍이고 날개가 두 쌍이에요.","answer":"O","reason_options":[{"t":"어른벌레는 몸이 머리·가슴·배로 나뉘고 다리 세 쌍, 날개 두 쌍이 있기 때문에","correct":true},{"t":"어른벌레는 날개가 없고 다리가 여덟 개이기 때문에","mis":"SC3-1-u4-X07"}],"mis":"SC3-1-u4-X07","explanation":["어른벌레를 떠올려요.","다리와 날개를 세요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#7','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C12',3,'mc','auto','다음 가운데 곤충이 아닌 것은 무엇인가요?',ARRAY['SC3-1-u4-X09']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C12","difficulty":3,"kind":"mc","stem":"다음 가운데 곤충이 아닌 것은 무엇인가요?","options":[{"t":"거미","correct":true},{"t":"배추흰나비","mis":"SC3-1-u4-X09"},{"t":"개미","mis":"SC3-1-u4-X09"},{"t":"메뚜기","mis":"SC3-1-u4-X09"}],"explanation":["다리를 세어 봐요.","여덟 개는 곤충이 아니에요.","거미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#8','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C9',4,'mc','auto','친구가 「애벌레는 처음부터 지금처럼 컸어.」라고 했어요. 배추흰나비 관찰 기록장을 보고 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X02','SC3-1-u4-X07','SC3-1-u4-X10']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C9","difficulty":4,"kind":"mc","stem":"친구가 「애벌레는 처음부터 지금처럼 컸어.」라고 했어요. 배추흰나비 관찰 기록장을 보고 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「알에서 나온 작은 애벌레가 잎을 갉아 먹고 허물을 벗으며 점점 자랐어.」","correct":true},{"t":"「맞아, 애벌레는 자라지 않아.」","mis":"SC3-1-u4-X02"},{"t":"「애벌레는 번데기를 갉아 먹고 자라.」","mis":"SC3-1-u4-X07"},{"t":"「애벌레는 허물을 벗으며 색깔만 바꿔.」","mis":"SC3-1-u4-X10"}],"explanation":["애벌레 줄을 읽어요.","허물을 벗으며 자라요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["알 — 배춧잎 뒷면에 붙어 있음 · 노란색 · 줄무늬가 있음 · 아주 작음","애벌레 — 알껍데기와 잎을 갉아 먹음 · 초록색 · 허물을 벗으며 자람","번데기 — 한곳에 붙어 움직이지 않음 · 먹지 않음 · 주변과 색이 비슷함","어른벌레 — 날개 두 쌍 · 다리 세 쌍 · 꽃의 꿀을 빨아 먹음 · 알을 낳음"],"title":"배추흰나비 관찰 기록장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#9','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C8',4,'mc','auto','친구가 「배추흰나비 알은 어른벌레처럼 날개가 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X07','SC3-1-u4-X06']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C8","difficulty":4,"kind":"mc","stem":"친구가 「배추흰나비 알은 어른벌레처럼 날개가 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「알은 배춧잎 뒷면에 붙은 작은 노란색 알이야. 날개는 어른벌레가 되어야 생겨.」","correct":true},{"t":"「맞아, 알도 날개로 날아다녀.」","mis":"SC3-1-u4-X07"},{"t":"「알에서 바로 어른벌레가 나와.」","mis":"SC3-1-u4-X06"},{"t":"「알은 잎을 갉아 먹고 허물을 벗어.」","mis":"SC3-1-u4-X07"}],"explanation":["알을 떠올려요.","날개는 마지막이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L02_challenge#10','sci',3,1,'u4','L02','g3_1_sci_u4_L02_challenge','lesson_challenge','SC3-1-u4-C14',4,'essay','teacher','배추흰나비의 한살이를 관찰할 때 지킬 약속 두 가지를 쓰고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C14","difficulty":4,"kind":"essay","stem":"배추흰나비의 한살이를 관찰할 때 지킬 약속 두 가지를 쓰고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 애벌레와 번데기를 함부로 만지지 않는다. 관찰이 끝난 어른벌레는 자연으로 돌려보낸다. 배추흰나비도 소중한 생명이기 때문이다.","scoring_points":["약속 두 가지를 썼는가","생명을 조심히 다루는 약속인가","까닭을 썼는가"]},"explanation":["생명을 떠올려요.","조심히 다뤄요.","약속과 까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#1','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C17',1,'mc','auto','닭의 한살이 순서로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X14']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C17","difficulty":1,"kind":"mc","stem":"닭의 한살이 순서로 알맞은 것은 무엇인가요?","options":[{"t":"알 → 병아리 → 어린 닭 → 다 자란 닭","correct":true},{"t":"병아리 → 알 → 다 자란 닭 → 어린 닭","mis":"SC3-1-u4-X14"},{"t":"알 → 다 자란 닭 → 병아리 → 어린 닭","mis":"SC3-1-u4-X14"},{"t":"다 자란 닭 → 알 → 어린 닭 → 병아리","mis":"SC3-1-u4-X14"}],"explanation":["알에서 시작해요.","병아리가 깨어나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#2','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C16',1,'mc','auto','새끼를 낳는 동물의 새끼는 무엇을 먹고 자라나요?',ARRAY['SC3-1-u4-X15']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C16","difficulty":1,"kind":"mc","stem":"새끼를 낳는 동물의 새끼는 무엇을 먹고 자라나요?","options":[{"t":"어미젖","correct":true},{"t":"돌","mis":"SC3-1-u4-X15"},{"t":"알껍데기","mis":"SC3-1-u4-X15"},{"t":"아무것도 먹지 않아요","mis":"SC3-1-u4-X15"}],"explanation":["강아지를 떠올려요.","어미가 먹여요.","어미젖이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#3','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C15',1,'ox','auto','닭은 알을 낳는 동물이에요.',ARRAY['SC3-1-u4-X13']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C15","difficulty":1,"kind":"ox","stem":"닭은 알을 낳는 동물이에요.","answer":"O","reason_options":[{"t":"어미 닭이 단단한 껍데기에 싸인 알을 낳고 알에서 병아리가 깨어나기 때문에","correct":true},{"t":"닭은 어미젖을 먹여 새끼를 키우기 때문에","mis":"SC3-1-u4-X13"}],"mis":"SC3-1-u4-X13","explanation":["달걀을 떠올려요.","알에서 병아리가 나와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#4','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C18',1,'sa','auto','개는 어미가 새끼를 낳아요. 갓 태어난 개의 새끼를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u4-C18","difficulty":1,"kind":"sa","stem":"개는 어미가 새끼를 낳아요. 갓 태어난 개의 새끼를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["강아지"],"explanation":["개의 새끼예요.","세 글자예요.","「강아지」예요."],"mis":"SC3-1-u4-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#5','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C15',2,'match','auto','동물 조사 카드를 보고 동물과 태어나는 방법을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u4-C15","difficulty":2,"kind":"match","stem":"동물 조사 카드를 보고 동물과 태어나는 방법을 알맞게 이으세요.","pairs":[{"l":"닭","r":"알을 낳아 병아리가 깨어남"},{"l":"개","r":"새끼를 낳아 젖을 먹여 키움"},{"l":"개구리","r":"물속에 알을 낳아 올챙이가 나옴"}],"mis":"SC3-1-u4-X13","explanation":["카드를 한 줄씩 읽어요.","알인가요, 새끼인가요?","하나씩 이어요."],"asset":{"type":"passage","lines":["닭 — 알을 낳음 · 알 → 병아리 → 어린 닭 → 다 자란 닭","개 — 새끼를 낳음 · 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","개구리 — 물속에 알을 낳음 · 알 → 올챙이 → 개구리","소 — 새끼(송아지)를 낳음 · 송아지 → 다 자란 소","새끼를 낳는 동물은 새끼에게 어미젖을 먹여 키움"],"title":"동물 조사 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#6','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C16',2,'mc','auto','새끼를 낳는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X13']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C16","difficulty":2,"kind":"mc","stem":"새끼를 낳는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"개, 소, 고양이","correct":true},{"t":"닭, 참새, 개구리","mis":"SC3-1-u4-X13"},{"t":"개, 닭, 뱀","mis":"SC3-1-u4-X13"},{"t":"소, 개구리, 참새","mis":"SC3-1-u4-X13"}],"explanation":["젖을 먹여요.","알이 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#7','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C15',2,'mc','auto','알을 낳는 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X13']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C15","difficulty":2,"kind":"mc","stem":"알을 낳는 동물끼리 모은 것은 무엇인가요?","options":[{"t":"닭, 개구리, 뱀","correct":true},{"t":"개, 소, 고양이","mis":"SC3-1-u4-X13"},{"t":"닭, 개, 소","mis":"SC3-1-u4-X13"},{"t":"돌고래, 박쥐, 개구리","mis":"SC3-1-u4-X13"}],"explanation":["알에서 깨어나요.","젖을 먹이지 않아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#8','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C20',2,'ox','auto','모든 동물은 알을 낳아요.',ARRAY['SC3-1-u4-X12']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C20","difficulty":2,"kind":"ox","stem":"모든 동물은 알을 낳아요.","answer":"X","reason_options":[{"t":"닭처럼 알을 낳는 동물도 있지만 개처럼 새끼를 낳는 동물도 있기 때문에","correct":true},{"t":"동물은 하나같이 알에서 깨어나기 때문에","mis":"SC3-1-u4-X12"}],"mis":"SC3-1-u4-X12","explanation":["개를 떠올려요.","새끼를 낳아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#9','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C18',2,'mc','auto','동물 조사 카드에서 개의 한살이 순서로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X13','SC3-1-u4-X14']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C18","difficulty":2,"kind":"mc","stem":"동물 조사 카드에서 개의 한살이 순서로 알맞은 것은 무엇인가요?","options":[{"t":"갓 태어난 강아지 → 큰 강아지 → 다 자란 개","correct":true},{"t":"알 → 강아지 → 다 자란 개","mis":"SC3-1-u4-X13"},{"t":"큰 강아지 → 갓 태어난 강아지 → 다 자란 개","mis":"SC3-1-u4-X14"},{"t":"다 자란 개 → 큰 강아지 → 갓 태어난 강아지","mis":"SC3-1-u4-X14"}],"explanation":["개 줄을 읽어요.","갓 태어나요.","첫 번째예요."],"asset":{"type":"passage","lines":["닭 — 알을 낳음 · 알 → 병아리 → 어린 닭 → 다 자란 닭","개 — 새끼를 낳음 · 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","개구리 — 물속에 알을 낳음 · 알 → 올챙이 → 개구리","소 — 새끼(송아지)를 낳음 · 송아지 → 다 자란 소","새끼를 낳는 동물은 새끼에게 어미젖을 먹여 키움"],"title":"동물 조사 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_basic#10','sci',3,1,'u4','L03','g3_1_sci_u4_L03_basic','lesson_basic','SC3-1-u4-C21',3,'mc','auto','여러 동물의 한살이를 알아보는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X17','SC3-1-u4-X05']::text[],false,'{"seq":10,"concept":"SC3-1-u4-C21","difficulty":3,"kind":"mc","stem":"여러 동물의 한살이를 알아보는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"동물도감이나 믿을 만한 자료로 조사해요","correct":true},{"t":"조사하지 않고 마음대로 상상만 해요","mis":"SC3-1-u4-X17"},{"t":"그냥 지나가요","mis":"SC3-1-u4-X17"},{"t":"동물을 마구 잡아 와서 괴롭혀요","mis":"SC3-1-u4-X05"}],"explanation":["어떻게 알 수 있을까요?","자료를 찾아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#1','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C16',2,'blank','auto','「개, 소처럼 새끼를 낳는 동물은 새끼에게 (      ) 먹여 키워요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u4-X15']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C16","difficulty":2,"kind":"blank","stem":"「개, 소처럼 새끼를 낳는 동물은 새끼에게 (      ) 먹여 키워요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"어미젖을","correct":true},{"t":"알껍데기를","mis":"SC3-1-u4-X15"},{"t":"돌을","mis":"SC3-1-u4-X15"},{"t":"꽃의 꿀을","mis":"SC3-1-u4-X15"}],"explanation":["어미가 주어요.","젖이에요.","「어미젖을」이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#2','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C19',2,'mc','auto','새끼를 낳는 동물의 새끼에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X15','SC3-1-u4-X13']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C19","difficulty":2,"kind":"mc","stem":"새끼를 낳는 동물의 새끼에 대해 알맞은 것은 무엇인가요?","options":[{"t":"어미와 닮은 모습으로 태어나 어미젖을 먹고 자라요","correct":true},{"t":"알껍데기를 깨고 나와요","mis":"SC3-1-u4-X15"},{"t":"어미젖을 먹지 않아요","mis":"SC3-1-u4-X15"},{"t":"올챙이처럼 물속에서 헤엄치다 다리가 생겨요","mis":"SC3-1-u4-X13"}],"explanation":["강아지를 떠올려요.","어미를 닮았어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#3','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C20',3,'error','auto','친구들이 동물 조사 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u4-X12','SC3-1-u4-X13']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C20","difficulty":3,"kind":"error","stem":"친구들이 동물 조사 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「동물은 다 알을 낳아서 한살이가 똑같아.」","correct":true,"mis_target":"SC3-1-u4-X12"},{"t":"친구 나 — 「닭은 알을, 개는 새끼를 낳아.」","mis":"SC3-1-u4-X13"},{"t":"친구 다 — 「소는 새끼를 낳아 젖을 먹여 키워.」","mis":"SC3-1-u4-X13"}],"explanation":["개와 소를 봐요.","새끼를 낳아요.","친구 가예요."],"asset":{"type":"passage","lines":["닭 — 알을 낳음 · 알 → 병아리 → 어린 닭 → 다 자란 닭","개 — 새끼를 낳음 · 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","개구리 — 물속에 알을 낳음 · 알 → 올챙이 → 개구리","소 — 새끼(송아지)를 낳음 · 송아지 → 다 자란 소","새끼를 낳는 동물은 새끼에게 어미젖을 먹여 키움"],"title":"동물 조사 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#4','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C17',3,'mc','auto','병아리에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X15','SC3-1-u4-X14','SC3-1-u4-X02']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C17","difficulty":3,"kind":"mc","stem":"병아리에 대해 알맞은 것은 무엇인가요?","options":[{"t":"알에서 깨어나 어린 닭을 거쳐 다 자란 닭이 돼요","correct":true},{"t":"어미젖을 먹고 자라 개가 돼요","mis":"SC3-1-u4-X15"},{"t":"다 자란 닭이 된 뒤에 알에서 깨어나요","mis":"SC3-1-u4-X14"},{"t":"병아리는 자라지 않고 평생 그대로예요","mis":"SC3-1-u4-X02"}],"explanation":["알에서 나와요.","어린 닭을 거쳐요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#5','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C16',3,'mc','auto','돌고래와 박쥐의 같은 점으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X13']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C16","difficulty":3,"kind":"mc","stem":"돌고래와 박쥐의 같은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"둘 다 새끼를 낳아 어미젖을 먹여 키워요","correct":true},{"t":"둘 다 알을 낳아요","mis":"SC3-1-u4-X13"},{"t":"둘 다 물속에 알을 낳아 올챙이가 나와요","mis":"SC3-1-u4-X13"},{"t":"둘 다 알에서 병아리가 깨어나요","mis":"SC3-1-u4-X13"}],"explanation":["바다와 하늘에 살아도","젖을 먹여요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#6','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C20',3,'ox','auto','닭과 개의 한살이가 다른 까닭은 태어나는 방법이 다르기 때문이에요.',ARRAY['SC3-1-u4-X16']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C20","difficulty":3,"kind":"ox","stem":"닭과 개의 한살이가 다른 까닭은 태어나는 방법이 다르기 때문이에요.","answer":"O","reason_options":[{"t":"닭은 알에서, 개는 어미가 낳은 새끼로 태어나 자라기 때문에","correct":true},{"t":"닭과 개는 한살이가 똑같기 때문에","mis":"SC3-1-u4-X16"}],"mis":"SC3-1-u4-X16","explanation":["태어나는 방법을 견줘요.","알과 새끼예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#7','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C20',3,'mc','auto','닭과 개의 한살이에서 같은 점은 무엇인가요?',ARRAY['SC3-1-u4-X12','SC3-1-u4-X15','SC3-1-u4-X02']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C20","difficulty":3,"kind":"mc","stem":"닭과 개의 한살이에서 같은 점은 무엇인가요?","options":[{"t":"태어나 자라서 다 자란 어미가 되고, 다시 자손을 남겨요","correct":true},{"t":"둘 다 알에서 깨어나요","mis":"SC3-1-u4-X12"},{"t":"둘 다 어미젖을 먹고 자라요","mis":"SC3-1-u4-X15"},{"t":"둘 다 자라지 않고 평생 같은 모습이에요","mis":"SC3-1-u4-X02"}],"explanation":["끝을 견줘요.","자손을 남겨요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#8','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C21',4,'mc','auto','친구가 「동물 한살이는 책을 보지 않아도 그냥 상상하면 다 알 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X17','SC3-1-u4-X12','SC3-1-u4-X05']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C21","difficulty":4,"kind":"mc","stem":"친구가 「동물 한살이는 책을 보지 않아도 그냥 상상하면 다 알 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「상상한 것은 틀릴 수 있으니 동물도감이나 자료로 조사해서 알아보자.」","correct":true},{"t":"「맞아, 마음대로 상상하면 돼.」","mis":"SC3-1-u4-X17"},{"t":"「동물은 다 알을 낳으니 조사할 필요가 없어.」","mis":"SC3-1-u4-X12"},{"t":"「동물을 잡아 와서 마음대로 괴롭혀 보자.」","mis":"SC3-1-u4-X05"}],"explanation":["상상은 틀릴 수 있어요.","자료를 찾아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#9','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C15',4,'mc','auto','친구가 「개구리와 소는 둘 다 새끼를 낳아.」라고 했어요. 동물 조사 카드를 보고 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X13','SC3-1-u4-X15']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C15","difficulty":4,"kind":"mc","stem":"친구가 「개구리와 소는 둘 다 새끼를 낳아.」라고 했어요. 동물 조사 카드를 보고 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「소는 새끼를 낳지만, 개구리는 물속에 알을 낳아 올챙이가 나와.」","correct":true},{"t":"「맞아, 둘 다 새끼를 낳아.」","mis":"SC3-1-u4-X13"},{"t":"「둘 다 알을 낳아.」","mis":"SC3-1-u4-X13"},{"t":"「개구리는 어미젖을 먹고 자라.」","mis":"SC3-1-u4-X15"}],"explanation":["두 줄을 견줘요.","개구리는 알이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["닭 — 알을 낳음 · 알 → 병아리 → 어린 닭 → 다 자란 닭","개 — 새끼를 낳음 · 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","개구리 — 물속에 알을 낳음 · 알 → 올챙이 → 개구리","소 — 새끼(송아지)를 낳음 · 송아지 → 다 자란 소","새끼를 낳는 동물은 새끼에게 어미젖을 먹여 키움"],"title":"동물 조사 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L03_challenge#10','sci',3,1,'u4','L03','g3_1_sci_u4_L03_challenge','lesson_challenge','SC3-1-u4-C18',4,'essay','teacher','닭과 개의 한살이를 견주어 다른 점과 같은 점을 한 가지씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C18","difficulty":4,"kind":"essay","stem":"닭과 개의 한살이를 견주어 다른 점과 같은 점을 한 가지씩 쓰세요.","answer_guide":{"answer":"예: 다른 점 — 닭은 알을 낳고 알에서 병아리가 깨어나지만, 개는 새끼를 낳아 어미젖을 먹여 키운다. 같은 점 — 둘 다 자라서 다 자란 어미가 되고 다시 자손을 남긴다.","scoring_points":["태어나는 방법이 다르다고 썼는가","자라서 자손을 남기는 같은 점을 썼는가","닭과 개의 한살이가 바르게 들어갔는가"]},"explanation":["알과 새끼를 견줘요.","끝은 같아요.","두 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#1','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C22',1,'mc','auto','씨가 싹 트는 데 꼭 필요한 조건 두 가지는 무엇인가요?',ARRAY['SC3-1-u4-X20','SC3-1-u4-X23','SC3-1-u4-X19']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C22","difficulty":1,"kind":"mc","stem":"씨가 싹 트는 데 꼭 필요한 조건 두 가지는 무엇인가요?","options":[{"t":"물과 알맞은 온도","correct":true},{"t":"밝은 빛과 큰 소리","mis":"SC3-1-u4-X20"},{"t":"단단한 돌과 모래","mis":"SC3-1-u4-X23"},{"t":"아주 추운 온도와 바람","mis":"SC3-1-u4-X19"}],"explanation":["강낭콩 실험을 떠올려요.","물을 주고 따뜻하게 했어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#2','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C22',1,'ox','auto','물을 주지 않은 강낭콩은 싹이 트지 않았어요.',ARRAY['SC3-1-u4-X18']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C22","difficulty":1,"kind":"ox","stem":"물을 주지 않은 강낭콩은 싹이 트지 않았어요.","answer":"O","reason_options":[{"t":"씨가 싹 트려면 물이 필요하기 때문에","correct":true},{"t":"씨는 물이 없어도 싹이 트기 때문에","mis":"SC3-1-u4-X18"}],"mis":"SC3-1-u4-X18","explanation":["물을 주지 않았어요.","싹이 안 텄어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#3','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C25',1,'sa','auto','실험에서 알아보려는 조건 하나만 다르게 하고, 나머지는 모두 「○○」 해요. ○○에 알맞은 두 글자 말을 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC3-1-u4-C25","difficulty":1,"kind":"sa","stem":"실험에서 알아보려는 조건 하나만 다르게 하고, 나머지는 모두 「○○」 해요. ○○에 알맞은 두 글자 말을 쓰세요.","answer":["같게"],"explanation":["다르게의 반대예요.","두 글자예요.","「같게」예요."],"mis":"SC3-1-u4-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#4','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C23',1,'mc','auto','물을 주었는데도 추운 냉장고 안에 둔 강낭콩이 싹이 트지 않은 까닭은 무엇인가요?',ARRAY['SC3-1-u4-X18','SC3-1-u4-X20','SC3-1-u4-X23']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C23","difficulty":1,"kind":"mc","stem":"물을 주었는데도 추운 냉장고 안에 둔 강낭콩이 싹이 트지 않은 까닭은 무엇인가요?","options":[{"t":"온도가 너무 낮아서","correct":true},{"t":"물이 너무 많아서","mis":"SC3-1-u4-X18"},{"t":"빛이 너무 밝아서","mis":"SC3-1-u4-X20"},{"t":"강낭콩 색깔이 달라서","mis":"SC3-1-u4-X23"}],"explanation":["냉장고는 어때요?","아주 추워요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#5','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C27',2,'match','auto','씨앗 실험 기록을 보고 컵과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u4-C27","difficulty":2,"kind":"match","stem":"씨앗 실험 기록을 보고 컵과 결과를 알맞게 이으세요.","pairs":[{"l":"㉯","r":"물이 없어 싹이 트지 않음"},{"l":"㉰","r":"온도가 낮아 싹이 트지 않음"},{"l":"㉱","r":"어두워도 싹이 틈"}],"mis":"SC3-1-u4-X23","explanation":["컵마다 읽어요.","무엇이 달랐나요?","하나씩 이어요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#6','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C25',2,'mc','auto','물이 싹 트는 데 필요한지 알아보려면 씨앗 실험 기록의 어느 두 컵을 견주어야 할까요?',ARRAY['SC3-1-u4-X21']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C25","difficulty":2,"kind":"mc","stem":"물이 싹 트는 데 필요한지 알아보려면 씨앗 실험 기록의 어느 두 컵을 견주어야 할까요?","options":[{"t":"㉮와 ㉯","correct":true},{"t":"㉮와 ㉰","mis":"SC3-1-u4-X21"},{"t":"㉯와 ㉰","mis":"SC3-1-u4-X21"},{"t":"㉯와 ㉱","mis":"SC3-1-u4-X21"}],"explanation":["물만 달라야 해요.","나머지는 같아요.","㉮와 ㉯예요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#7','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C24',2,'ox','auto','씨앗 실험 기록의 ㉮와 ㉱를 견주면, 씨가 싹 트는 데 빛이 꼭 있어야 하는 것은 아니에요.',ARRAY['SC3-1-u4-X20']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C24","difficulty":2,"kind":"ox","stem":"씨앗 실험 기록의 ㉮와 ㉱를 견주면, 씨가 싹 트는 데 빛이 꼭 있어야 하는 것은 아니에요.","answer":"O","reason_options":[{"t":"밝은 곳의 ㉮도 어두운 곳의 ㉱도 모두 싹이 텄기 때문에","correct":true},{"t":"빛이 없으면 씨는 절대 싹이 트지 않기 때문에","mis":"SC3-1-u4-X20"}],"mis":"SC3-1-u4-X20","explanation":["㉮와 ㉱를 봐요.","둘 다 싹이 텄어요.","그래서 O예요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#8','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C26',2,'mc','auto','물이 싹 트는 데 필요한지 알아보는 실험에서 같게 해야 할 조건이 아닌 것은 무엇인가요?',ARRAY['SC3-1-u4-X22']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C26","difficulty":2,"kind":"mc","stem":"물이 싹 트는 데 필요한지 알아보는 실험에서 같게 해야 할 조건이 아닌 것은 무엇인가요?","options":[{"t":"컵에 주는 물","correct":true},{"t":"강낭콩의 종류","mis":"SC3-1-u4-X22"},{"t":"두는 곳의 온도","mis":"SC3-1-u4-X22"},{"t":"컵과 탈지면","mis":"SC3-1-u4-X22"}],"explanation":["알아보려는 것은?","물이에요.","물은 다르게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#9','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C23',2,'mc','auto','알맞은 온도가 싹 트는 데 필요한지 알아보려면 씨앗 실험 기록의 어느 두 컵을 견주어야 할까요?',ARRAY['SC3-1-u4-X21','SC3-1-u4-X23']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C23","difficulty":2,"kind":"mc","stem":"알맞은 온도가 싹 트는 데 필요한지 알아보려면 씨앗 실험 기록의 어느 두 컵을 견주어야 할까요?","options":[{"t":"㉰와 ㉱","correct":true},{"t":"㉮와 ㉰","mis":"SC3-1-u4-X21"},{"t":"㉯와 ㉰","mis":"SC3-1-u4-X21"},{"t":"㉮와 ㉯","mis":"SC3-1-u4-X23"}],"explanation":["온도만 달라야 해요.","둘 다 물을 주고 어두워요.","㉰와 ㉱예요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_basic#10','sci',3,1,'u4','L04','g3_1_sci_u4_L04_basic','lesson_basic','SC3-1-u4-C27',3,'mc','auto','씨앗 실험 기록의 ㉮와 ㉯를 견준 결과로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u4-X20','SC3-1-u4-X23','SC3-1-u4-X19']::text[],false,'{"seq":10,"concept":"SC3-1-u4-C27","difficulty":3,"kind":"mc","stem":"씨앗 실험 기록의 ㉮와 ㉯를 견준 결과로 알 수 있는 것은 무엇인가요?","options":[{"t":"씨가 싹 트려면 물이 필요해요","correct":true},{"t":"씨가 싹 트려면 빛이 꼭 있어야 해요","mis":"SC3-1-u4-X20"},{"t":"씨는 소리를 들어야 싹이 터요","mis":"SC3-1-u4-X23"},{"t":"씨는 차가울수록 싹이 잘 터요","mis":"SC3-1-u4-X19"}],"explanation":["다른 것은 물뿐이에요.","물 준 쪽만 텄어요.","첫 번째예요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#1','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C25',2,'blank','auto','「공정한 실험에서 다르게 할 조건은 딱 (      )만 정해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u4-X21']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C25","difficulty":2,"kind":"blank","stem":"「공정한 실험에서 다르게 할 조건은 딱 (      )만 정해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"하나","correct":true},{"t":"둘","mis":"SC3-1-u4-X21"},{"t":"셋","mis":"SC3-1-u4-X21"},{"t":"여러 개","mis":"SC3-1-u4-X21"}],"explanation":["무엇 때문인지 알려면","하나만 바꿔요.","「하나」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#2','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C26',2,'mc','auto','물 실험에서 두 컵을 같은 곳에 두는 까닭은 무엇인가요?',ARRAY['SC3-1-u4-X22','SC3-1-u4-X18']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C26","difficulty":2,"kind":"mc","stem":"물 실험에서 두 컵을 같은 곳에 두는 까닭은 무엇인가요?","options":[{"t":"온도까지 다르면 무엇 때문에 싹이 텄는지 알 수 없기 때문이에요","correct":true},{"t":"컵이 예쁘게 보이도록 하려고요","mis":"SC3-1-u4-X22"},{"t":"같은 곳에 두면 물을 안 줘도 되어서요","mis":"SC3-1-u4-X18"},{"t":"두 곳에 나누어 두기 귀찮아서요","mis":"SC3-1-u4-X22"}],"explanation":["같은 곳 = 같은 온도","하나만 달라야 해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#3','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C25',3,'error','auto','친구들이 물 실험을 계획했어요. 잘못 계획한 친구는 누구인가요?',ARRAY['SC3-1-u4-X21','SC3-1-u4-X22']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C25","difficulty":3,"kind":"error","stem":"친구들이 물 실험을 계획했어요. 잘못 계획한 친구는 누구인가요?","options":[{"t":"친구 다 — 「한 컵은 물을 주고 따뜻한 곳에, 다른 컵은 물을 안 주고 냉장고에 둘래.」","correct":true,"mis_target":"SC3-1-u4-X21"},{"t":"친구 가 — 「두 컵에 같은 강낭콩을 넣을래.」","mis":"SC3-1-u4-X22"},{"t":"친구 나 — 「한 컵만 물을 주고 나머지는 똑같이 할래.」","mis":"SC3-1-u4-X22"}],"explanation":["몇 가지를 바꿨나요?","물과 온도 둘이에요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#4','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C24',3,'mc','auto','친구가 「씨는 빛이 없으면 절대 싹이 트지 않아.」라고 했어요. 씨앗 실험 기록을 보고 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X20','SC3-1-u4-X18']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C24","difficulty":3,"kind":"mc","stem":"친구가 「씨는 빛이 없으면 절대 싹이 트지 않아.」라고 했어요. 씨앗 실험 기록을 보고 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「어두운 곳의 ㉱도 싹이 텄으니 싹 트는 데 빛이 꼭 필요한 것은 아니야.」","correct":true},{"t":"「맞아, ㉱는 어두워서 싹이 트지 않았어.」","mis":"SC3-1-u4-X20"},{"t":"「㉰가 싹이 트지 않은 것은 빛 때문만이야.」","mis":"SC3-1-u4-X20"},{"t":"「물을 주지 않은 ㉯도 싹이 텄어.」","mis":"SC3-1-u4-X18"}],"explanation":["㉱를 읽어요.","어두워도 텄어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#5','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C23',3,'ox','auto','물만 주면 아주 추운 곳에서도 씨는 싹이 잘 터요.',ARRAY['SC3-1-u4-X19']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C23","difficulty":3,"kind":"ox","stem":"물만 주면 아주 추운 곳에서도 씨는 싹이 잘 터요.","answer":"X","reason_options":[{"t":"물을 준 ㉰도 추운 냉장고 안에서는 싹이 트지 않았기 때문에","correct":true},{"t":"물만 있으면 온도와 관계없이 싹이 트기 때문에","mis":"SC3-1-u4-X19"}],"mis":"SC3-1-u4-X19","explanation":["㉰를 읽어요.","물은 주었어요.","그래서 X예요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#6','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C26',3,'mc','auto','온도 조건을 알아보는 실험에서 다르게 할 조건과 같게 할 조건을 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-1-u4-X22','SC3-1-u4-X21']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C26","difficulty":3,"kind":"mc","stem":"온도 조건을 알아보는 실험에서 다르게 할 조건과 같게 할 조건을 바르게 나눈 것은 무엇인가요?","options":[{"t":"다르게 — 온도 / 같게 — 물, 강낭콩, 컵","correct":true},{"t":"다르게 — 물 / 같게 — 온도, 강낭콩, 컵","mis":"SC3-1-u4-X22"},{"t":"다르게 — 온도, 물 / 같게 — 강낭콩, 컵","mis":"SC3-1-u4-X21"},{"t":"다르게 — 강낭콩, 컵 / 같게 — 온도","mis":"SC3-1-u4-X22"}],"explanation":["알아보려는 것은?","온도예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#7','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C27',3,'mc','auto','씨앗 실험 기록의 ㉰와 ㉱를 견준 결과로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u4-X20','SC3-1-u4-X18','SC3-1-u4-X19']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C27","difficulty":3,"kind":"mc","stem":"씨앗 실험 기록의 ㉰와 ㉱를 견준 결과로 알 수 있는 것은 무엇인가요?","options":[{"t":"씨가 싹 트려면 알맞은 온도가 필요해요","correct":true},{"t":"씨는 어두워야만 싹이 터요","mis":"SC3-1-u4-X20"},{"t":"씨는 물이 없어도 싹이 터요","mis":"SC3-1-u4-X18"},{"t":"씨는 추울수록 싹이 잘 터요","mis":"SC3-1-u4-X19"}],"explanation":["다른 것은 온도예요.","따뜻한 쪽만 텄어요.","첫 번째예요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#8','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C25',4,'mc','auto','친구가 「물과 온도를 한꺼번에 다르게 하면 더 빨리 알 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X21','SC3-1-u4-X22','SC3-1-u4-X20']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C25","difficulty":4,"kind":"mc","stem":"친구가 「물과 온도를 한꺼번에 다르게 하면 더 빨리 알 수 있어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「두 가지를 한꺼번에 다르게 하면 무엇 때문에 싹이 텄는지 알 수 없어. 하나만 다르게 하자.」","correct":true},{"t":"「맞아, 여러 개를 함께 바꾸면 좋아.」","mis":"SC3-1-u4-X21"},{"t":"「같게 할 조건은 하나도 없어도 돼.」","mis":"SC3-1-u4-X22"},{"t":"「싹 트는 데 빛만 있으면 되니 빛만 보자.」","mis":"SC3-1-u4-X20"}],"explanation":["두 가지를 바꾸면?","까닭을 몰라요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#9','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C22',4,'mc','auto','봄에 화단에 강낭콩을 심었어요. 싹이 잘 트게 하려면 어떻게 하는 것이 가장 알맞을까요?',ARRAY['SC3-1-u4-X18','SC3-1-u4-X19','SC3-1-u4-X20']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C22","difficulty":4,"kind":"mc","stem":"봄에 화단에 강낭콩을 심었어요. 싹이 잘 트게 하려면 어떻게 하는 것이 가장 알맞을까요?","options":[{"t":"물을 알맞게 주고, 너무 춥지 않은 때에 심어요","correct":true},{"t":"물을 주지 않고 그냥 두어요","mis":"SC3-1-u4-X18"},{"t":"추운 겨울 눈 속에 심어요","mis":"SC3-1-u4-X19"},{"t":"빛이 꼭 있어야 하니 밤새 불을 켜 둬요","mis":"SC3-1-u4-X20"}],"explanation":["두 가지 조건이에요.","물과 온도예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L04_challenge#10','sci',3,1,'u4','L04','g3_1_sci_u4_L04_challenge','lesson_challenge','SC3-1-u4-C27',4,'essay','teacher','씨앗 실험 기록의 ㉮~㉱를 보고, 씨가 싹 트는 데 필요한 조건과 꼭 필요하지는 않은 조건을 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C27","difficulty":4,"kind":"essay","stem":"씨앗 실험 기록의 ㉮~㉱를 보고, 씨가 싹 트는 데 필요한 조건과 꼭 필요하지는 않은 조건을 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 물을 준 ㉮는 싹이 트고 물을 주지 않은 ㉯는 트지 않아 물이 필요하다. 따뜻한 ㉱는 싹이 트고 추운 ㉰는 트지 않아 알맞은 온도가 필요하다. 밝은 ㉮와 어두운 ㉱가 모두 싹이 터서 빛은 꼭 필요하지 않다.","scoring_points":["물이 필요하다고 두 컵을 견주어 썼는가","알맞은 온도가 필요하다고 썼는가","빛은 꼭 필요하지 않다고 까닭과 함께 썼는가"]},"explanation":["두 컵씩 견줘요.","하나만 다른 짝이에요.","세 가지를 써요."],"asset":{"type":"passage","lines":["컵마다 탈지면을 깔고 같은 강낭콩을 넣었다.","㉮ 물을 줌 · 따뜻하고 밝은 곳 → 싹이 텄다","㉯ 물을 주지 않음 · 따뜻하고 밝은 곳 → 싹이 트지 않았다","㉰ 물을 줌 · 춥고 어두운 냉장고 안 → 싹이 트지 않았다","㉱ 물을 줌 · 따뜻하고 어두운 곳 → 싹이 텄다"],"title":"씨앗 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#1','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C28',1,'mc','auto','식물이 자라는 데 꼭 필요한 두 가지는 무엇인가요?',ARRAY['SC3-1-u4-X23','SC3-1-u4-X25','SC3-1-u4-X26']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C28","difficulty":1,"kind":"mc","stem":"식물이 자라는 데 꼭 필요한 두 가지는 무엇인가요?","options":[{"t":"물과 햇빛","correct":true},{"t":"소리와 바람","mis":"SC3-1-u4-X23"},{"t":"어둠과 돌","mis":"SC3-1-u4-X25"},{"t":"물 하나만 있으면 돼요","mis":"SC3-1-u4-X26"}],"explanation":["화분을 떠올려요.","물을 주고 창가에 둬요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#2','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C29',1,'ox','auto','햇빛을 받은 식물이 어두운 곳의 식물보다 잘 자랐어요.',ARRAY['SC3-1-u4-X25']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C29","difficulty":1,"kind":"ox","stem":"햇빛을 받은 식물이 어두운 곳의 식물보다 잘 자랐어요.","answer":"O","reason_options":[{"t":"식물이 자라려면 햇빛이 필요하기 때문에","correct":true},{"t":"식물은 어두울수록 잘 자라기 때문에","mis":"SC3-1-u4-X25"}],"mis":"SC3-1-u4-X25","explanation":["창가와 어두운 곳을 견줘요.","창가가 잘 자라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#3','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C29',1,'sa','auto','식물 자람 실험 기록에서 ㉰가 받지 못한 것은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC3-1-u4-C29","difficulty":1,"kind":"sa","stem":"식물 자람 실험 기록에서 ㉰가 받지 못한 것은 무엇인가요? 두 글자로 쓰세요.","answer":["햇빛","햇볕"],"explanation":["㉰는 상자 안이에요.","어두워요.","「햇빛」이에요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"},"mis":"SC3-1-u4-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#4','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C28',1,'mc','auto','식물 자람 실험 기록에서 물을 주지 않은 ㉯는 어떻게 되었나요?',ARRAY['SC3-1-u4-X24']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C28","difficulty":1,"kind":"mc","stem":"식물 자람 실험 기록에서 물을 주지 않은 ㉯는 어떻게 되었나요?","options":[{"t":"잘 자라지 못했어요","correct":true},{"t":"더 잘 자랐어요","mis":"SC3-1-u4-X24"},{"t":"꽃이 바로 피었어요","mis":"SC3-1-u4-X24"},{"t":"㉮와 아무 차이가 없었어요","mis":"SC3-1-u4-X24"}],"explanation":["㉯ 줄을 읽어요.","물이 없어요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#5','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C30',2,'match','auto','식물 자람 실험 기록을 보고 화분과 결과를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u4-C30","difficulty":2,"kind":"match","stem":"식물 자람 실험 기록을 보고 화분과 결과를 알맞게 이으세요.","pairs":[{"l":"㉮","r":"물과 햇빛이 모두 있어 잘 자람"},{"l":"㉯","r":"물이 없어 잘 자라지 못함"},{"l":"㉰","r":"햇빛이 없어 잘 자라지 못함"}],"mis":"SC3-1-u4-X26","explanation":["화분마다 읽어요.","무엇이 없었나요?","하나씩 이어요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#6','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C31',2,'mc','auto','햇빛이 식물이 자라는 데 필요한지 알아보려면 식물 자람 실험 기록의 어느 두 화분을 견주어야 할까요?',ARRAY['SC3-1-u4-X23','SC3-1-u4-X21']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C31","difficulty":2,"kind":"mc","stem":"햇빛이 식물이 자라는 데 필요한지 알아보려면 식물 자람 실험 기록의 어느 두 화분을 견주어야 할까요?","options":[{"t":"㉮와 ㉰","correct":true},{"t":"㉮와 ㉯","mis":"SC3-1-u4-X23"},{"t":"㉯와 ㉰","mis":"SC3-1-u4-X21"},{"t":"㉰ 하나만 보면 돼요","mis":"SC3-1-u4-X21"}],"explanation":["햇빛만 달라야 해요.","둘 다 물을 주었어요.","㉮와 ㉰예요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#7','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C30',2,'ox','auto','물이나 햇빛 가운데 하나만 있어도 식물은 잘 자라요.',ARRAY['SC3-1-u4-X26']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C30","difficulty":2,"kind":"ox","stem":"물이나 햇빛 가운데 하나만 있어도 식물은 잘 자라요.","answer":"X","reason_options":[{"t":"물이 없는 ㉯도, 햇빛이 없는 ㉰도 잘 자라지 못했기 때문에","correct":true},{"t":"둘 중 하나만 있으면 충분하기 때문에","mis":"SC3-1-u4-X26"}],"mis":"SC3-1-u4-X26","explanation":["㉯와 ㉰를 봐요.","하나씩 빠졌어요.","그래서 X예요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#8','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C31',2,'mc','auto','햇빛 실험에서 다르게 할 조건은 무엇인가요?',ARRAY['SC3-1-u4-X22']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C31","difficulty":2,"kind":"mc","stem":"햇빛 실험에서 다르게 할 조건은 무엇인가요?","options":[{"t":"햇빛","correct":true},{"t":"물","mis":"SC3-1-u4-X22"},{"t":"흙","mis":"SC3-1-u4-X22"},{"t":"식물의 크기","mis":"SC3-1-u4-X22"}],"explanation":["무엇을 알아보나요?","햇빛이에요.","햇빛만 다르게 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#9','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C32',2,'mc','auto','씨가 싹 틀 때와 식물이 자랄 때 필요한 것을 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u4-X27','SC3-1-u4-X24']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C32","difficulty":2,"kind":"mc","stem":"씨가 싹 틀 때와 식물이 자랄 때 필요한 것을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"싹 틀 때 — 물, 알맞은 온도 / 자랄 때 — 물, 햇빛","correct":true},{"t":"싹 틀 때 — 물, 햇빛 / 자랄 때 — 물, 알맞은 온도","mis":"SC3-1-u4-X27"},{"t":"싹 틀 때 — 빛만 / 자랄 때 — 소리만","mis":"SC3-1-u4-X27"},{"t":"싹 틀 때도 자랄 때도 물이 필요 없어요","mis":"SC3-1-u4-X24"}],"explanation":["지난 시간을 떠올려요.","자랄 때는 햇빛이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_basic#10','sci',3,1,'u4','L05','g3_1_sci_u4_L05_basic','lesson_basic','SC3-1-u4-C29',3,'mc','auto','식물 자람 실험 기록의 ㉮와 ㉰를 견준 결과로 알 수 있는 것은 무엇인가요?',ARRAY['SC3-1-u4-X25','SC3-1-u4-X23']::text[],false,'{"seq":10,"concept":"SC3-1-u4-C29","difficulty":3,"kind":"mc","stem":"식물 자람 실험 기록의 ㉮와 ㉰를 견준 결과로 알 수 있는 것은 무엇인가요?","options":[{"t":"식물이 자라려면 햇빛이 필요해요","correct":true},{"t":"식물은 햇빛 없이도 잘 자라요","mis":"SC3-1-u4-X25"},{"t":"식물이 자라려면 소리가 필요해요","mis":"SC3-1-u4-X23"},{"t":"식물은 어두울수록 잘 자라요","mis":"SC3-1-u4-X25"}],"explanation":["다른 것은 햇빛이에요.","받은 쪽만 잘 자랐어요.","첫 번째예요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#1','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C32',2,'blank','auto','「씨가 싹 틀 때는 빛이 없어도 되지만, 식물이 자랄 때는 (      ) 꼭 필요해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u4-X25','SC3-1-u4-X23','SC3-1-u4-X27']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C32","difficulty":2,"kind":"blank","stem":"「씨가 싹 틀 때는 빛이 없어도 되지만, 식물이 자랄 때는 (      ) 꼭 필요해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"햇빛이","correct":true},{"t":"어둠이","mis":"SC3-1-u4-X25"},{"t":"소리가","mis":"SC3-1-u4-X23"},{"t":"추위가","mis":"SC3-1-u4-X27"}],"explanation":["창가에 두는 까닭이에요.","밝은 빛이에요.","「햇빛이」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#2','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C31',2,'mc','auto','햇빛 실험에서 같게 해야 할 조건끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X22']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C31","difficulty":2,"kind":"mc","stem":"햇빛 실험에서 같게 해야 할 조건끼리 모은 것은 무엇인가요?","options":[{"t":"물, 흙, 식물의 크기","correct":true},{"t":"햇빛, 물, 흙","mis":"SC3-1-u4-X22"},{"t":"햇빛 하나","mis":"SC3-1-u4-X22"},{"t":"같게 할 것은 하나도 없어요","mis":"SC3-1-u4-X22"}],"explanation":["햇빛만 다르게 해요.","나머지는 같게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#3','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C30',3,'error','auto','친구들이 식물 자람 실험 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u4-X25','SC3-1-u4-X26','SC3-1-u4-X24']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C30","difficulty":3,"kind":"error","stem":"친구들이 식물 자람 실험 기록을 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「㉰는 물을 주었으니 잘 자랐어야 해. 햇빛은 상관없어.」","correct":true,"mis_target":"SC3-1-u4-X25"},{"t":"친구 가 — 「㉮는 물과 햇빛이 모두 있어 잘 자랐어.」","mis":"SC3-1-u4-X26"},{"t":"친구 다 — 「㉯는 물이 없어 잘 자라지 못했어.」","mis":"SC3-1-u4-X24"}],"explanation":["㉰를 읽어요.","어두웠어요.","친구 나예요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#4','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C28',3,'mc','auto','물이 식물이 자라는 데 필요한지 알아보려면 식물 자람 실험 기록의 어느 두 화분을 견주어야 할까요?',ARRAY['SC3-1-u4-X23','SC3-1-u4-X21']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C28","difficulty":3,"kind":"mc","stem":"물이 식물이 자라는 데 필요한지 알아보려면 식물 자람 실험 기록의 어느 두 화분을 견주어야 할까요?","options":[{"t":"㉮와 ㉯","correct":true},{"t":"㉮와 ㉰","mis":"SC3-1-u4-X23"},{"t":"㉯와 ㉰","mis":"SC3-1-u4-X21"},{"t":"㉯ 하나만 보면 돼요","mis":"SC3-1-u4-X21"}],"explanation":["물만 달라야 해요.","둘 다 햇빛을 받았어요.","㉮와 ㉯예요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#5','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C32',3,'ox','auto','씨가 싹 틀 때 필요한 조건과 식물이 자랄 때 필요한 조건은 서로 같아요.',ARRAY['SC3-1-u4-X27']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C32","difficulty":3,"kind":"ox","stem":"씨가 싹 틀 때 필요한 조건과 식물이 자랄 때 필요한 조건은 서로 같아요.","answer":"X","reason_options":[{"t":"싹 틀 때는 물과 알맞은 온도, 자랄 때는 물과 햇빛이 필요해 서로 다르기 때문에","correct":true},{"t":"싹 틀 때도 자랄 때도 빛이 꼭 있어야 하기 때문에","mis":"SC3-1-u4-X27"}],"mis":"SC3-1-u4-X27","explanation":["두 실험을 견줘요.","온도와 햇빛이 달라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#6','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C29',3,'mc','auto','창문이 없는 어두운 창고에 화분을 두었어요. 물을 잘 주어도 식물이 잘 자라지 못한 까닭은 무엇인가요?',ARRAY['SC3-1-u4-X24','SC3-1-u4-X23','SC3-1-u4-X25']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C29","difficulty":3,"kind":"mc","stem":"창문이 없는 어두운 창고에 화분을 두었어요. 물을 잘 주어도 식물이 잘 자라지 못한 까닭은 무엇인가요?","options":[{"t":"햇빛을 받지 못해서","correct":true},{"t":"물을 너무 잘 주어서","mis":"SC3-1-u4-X24"},{"t":"창고가 너무 조용해서","mis":"SC3-1-u4-X23"},{"t":"식물은 원래 어두운 곳을 좋아해서","mis":"SC3-1-u4-X25"}],"explanation":["창고는 어때요?","빛이 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#7','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C30',3,'mc','auto','교실 화분을 잘 키우는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X25','SC3-1-u4-X26','SC3-1-u4-X24']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C30","difficulty":3,"kind":"mc","stem":"교실 화분을 잘 키우는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"햇빛이 드는 창가에 두고 물을 알맞게 줘요","correct":true},{"t":"어두운 사물함 안에 넣고 물을 줘요","mis":"SC3-1-u4-X25"},{"t":"햇빛이 드는 창가에 두고 물은 주지 않아요","mis":"SC3-1-u4-X26"},{"t":"물도 햇빛도 주지 않고 그냥 둬요","mis":"SC3-1-u4-X24"}],"explanation":["두 가지가 필요해요.","물과 햇빛이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#8','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C32',4,'mc','auto','친구가 「씨가 싹 틀 때 빛이 필요 없었으니, 식물이 자랄 때도 햇빛은 필요 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X25','SC3-1-u4-X27','SC3-1-u4-X26']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C32","difficulty":4,"kind":"mc","stem":"친구가 「씨가 싹 틀 때 빛이 필요 없었으니, 식물이 자랄 때도 햇빛은 필요 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「싹 틀 때는 빛이 없어도 되지만, 자랄 때는 햇빛이 꼭 필요해. 어두운 ㉰가 잘 자라지 못했잖아.」","correct":true},{"t":"「맞아, 자랄 때도 어두워도 돼.」","mis":"SC3-1-u4-X25"},{"t":"「싹 틀 때도 자랄 때도 빛만 있으면 돼.」","mis":"SC3-1-u4-X27"},{"t":"「물만 주면 무엇이든 잘 자라.」","mis":"SC3-1-u4-X26"}],"explanation":["㉰를 읽어요.","어두워 못 자랐어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#9','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C31',4,'mc','auto','친구가 「햇빛 실험에서 한 화분은 햇빛을 주고 물도 주고, 다른 화분은 어둡게 하고 물도 주지 말자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X21','SC3-1-u4-X22']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C31","difficulty":4,"kind":"mc","stem":"친구가 「햇빛 실험에서 한 화분은 햇빛을 주고 물도 주고, 다른 화분은 어둡게 하고 물도 주지 말자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「햇빛과 물을 함께 다르게 하면 무엇 때문인지 알 수 없어. 햇빛만 다르게 하고 물은 같게 주자.」","correct":true},{"t":"「좋아, 많이 다르게 할수록 좋아.」","mis":"SC3-1-u4-X21"},{"t":"「흙도 다르게 하면 더 좋아.」","mis":"SC3-1-u4-X21"},{"t":"「같게 할 조건은 없어도 돼.」","mis":"SC3-1-u4-X22"}],"explanation":["몇 가지를 바꿨나요?","둘이에요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L05_challenge#10','sci',3,1,'u4','L05','g3_1_sci_u4_L05_challenge','lesson_challenge','SC3-1-u4-C30',4,'essay','teacher','식물 자람 실험 기록을 보고 식물이 잘 자라는 데 필요한 조건 두 가지를 쓰고, 그렇게 생각한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C30","difficulty":4,"kind":"essay","stem":"식물 자람 실험 기록을 보고 식물이 잘 자라는 데 필요한 조건 두 가지를 쓰고, 그렇게 생각한 까닭을 쓰세요.","answer_guide":{"answer":"예: 물과 햇빛이 필요하다. 물과 햇빛이 모두 있는 ㉮만 잘 자랐고, 물이 없는 ㉯와 햇빛이 없는 ㉰는 잘 자라지 못했기 때문이다.","scoring_points":["물과 햇빛 두 가지를 썼는가","화분을 견주어 까닭을 썼는가","하나라도 없으면 잘 자라지 못한다는 점을 썼는가"]},"explanation":["세 화분을 봐요.","㉮만 잘 자랐어요.","조건과 까닭을 써요."],"asset":{"type":"passage","lines":["같은 화분에 같은 흙을 담고 비슷한 크기의 어린 식물을 심었다.","㉮ 물을 줌 · 햇빛을 받음 → 잘 자랐다","㉯ 물을 주지 않음 · 햇빛을 받음 → 잘 자라지 못했다","㉰ 물을 줌 · 어두운 상자 안 → 잘 자라지 못했다"],"title":"식물 자람 실험 기록"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_basic#1','sci',3,1,'u4','L06','g3_1_sci_u4_L06_basic','lesson_basic','SC3-1-u4-C34',1,'mc','auto','벼처럼 한 해만 살고 한살이를 마치는 식물을 무엇이라고 하나요?',ARRAY['SC3-1-u4-X29','SC3-1-u4-X30','SC3-1-u4-X28']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C34","difficulty":1,"kind":"mc","stem":"벼처럼 한 해만 살고 한살이를 마치는 식물을 무엇이라고 하나요?","options":[{"t":"한해살이 식물","correct":true},{"t":"여러해살이 식물","mis":"SC3-1-u4-X29"},{"t":"나무","mis":"SC3-1-u4-X30"},{"t":"씨가 없는 식물","mis":"SC3-1-u4-X28"}],"explanation":["한 해만 살아요.","한해 + 살이예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_basic#2','sci',3,1,'u4','L06','g3_1_sci_u4_L06_basic','lesson_basic','SC3-1-u4-C33',1,'ox','auto','모든 식물은 씨에서 시작해 자라 꽃이 피고 열매를 맺어요.',ARRAY['SC3-1-u4-X28']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C33","difficulty":1,"kind":"ox","stem":"모든 식물은 씨에서 시작해 자라 꽃이 피고 열매를 맺어요.","answer":"O","reason_options":[{"t":"강낭콩도 감나무도 씨 → 싹 → 자람 → 꽃 → 열매의 과정을 거치기 때문에","correct":true},{"t":"식물마다 한살이의 흐름이 전혀 다르기 때문에","mis":"SC3-1-u4-X28"}],"mis":"SC3-1-u4-X28","explanation":["강낭콩과 감나무를 견줘요.","둘 다 씨에서 시작해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_basic#3','sci',3,1,'u4','L06','g3_1_sci_u4_L06_basic','lesson_basic','SC3-1-u4-C35',1,'sa','auto','여러 해 살면서 해마다 꽃이 피고 열매를 맺는 식물을 무엇이라고 하나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SC3-1-u4-C35","difficulty":1,"kind":"sa","stem":"여러 해 살면서 해마다 꽃이 피고 열매를 맺는 식물을 무엇이라고 하나요? 다섯 글자로 쓰세요.","answer":["여러해살이","여러해살이 식물","여러해살이식물"],"explanation":["여러 해 살아요.","다섯 글자예요.","「여러해살이」예요."],"mis":"SC3-1-u4-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_basic#4','sci',3,1,'u4','L06','g3_1_sci_u4_L06_basic','lesson_basic','SC3-1-u4-C35',1,'mc','auto','식물 조사표에서 해마다 감을 맺는 식물은 무엇인가요?',ARRAY['SC3-1-u4-X29']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C35","difficulty":1,"kind":"mc","stem":"식물 조사표에서 해마다 감을 맺는 식물은 무엇인가요?","options":[{"t":"감나무","correct":true},{"t":"강낭콩","mis":"SC3-1-u4-X29"},{"t":"벼","mis":"SC3-1-u4-X29"},{"t":"나팔꽃","mis":"SC3-1-u4-X29"}],"explanation":["감을 찾아요.","나무예요.","감나무예요."],"asset":{"type":"passage","lines":["강낭콩 — 한해살이 · 씨 → 싹 → 자람 → 꽃 → 열매 · 가을에 씨를 남기고 마침","벼 — 한해살이 · 봄에 심어 가을에 거두고 한 해로 마침","나팔꽃 — 한해살이 · 덩굴로 자라 꽃이 피고 씨를 남김","감나무 — 여러해살이 · 나무 · 해마다 꽃이 피고 감을 맺음","사과나무 — 여러해살이 · 나무 · 해마다 사과를 맺음","민들레 — 여러해살이 · 풀 · 뿌리가 겨울을 나고 봄에 다시 자람"],"title":"식물 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
