INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_challenge#3','sci',3,1,'u4','L06','g3_1_sci_u4_L06_challenge','lesson_challenge','SC3-1-u4-C36',3,'error','auto','친구들이 식물 조사표를 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u4-X30','SC3-1-u4-X29']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C36","difficulty":3,"kind":"error","stem":"친구들이 식물 조사표를 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「민들레는 풀이니까 한해살이야.」","correct":true,"mis_target":"SC3-1-u4-X30"},{"t":"친구 나 — 「벼는 한 해로 한살이를 마쳐.」","mis":"SC3-1-u4-X29"},{"t":"친구 다 — 「사과나무는 해마다 사과를 맺어.」","mis":"SC3-1-u4-X29"}],"explanation":["민들레 줄을 읽어요.","여러해살이예요.","친구 가예요."],"asset":{"type":"passage","lines":["강낭콩 — 한해살이 · 씨 → 싹 → 자람 → 꽃 → 열매 · 가을에 씨를 남기고 마침","벼 — 한해살이 · 봄에 심어 가을에 거두고 한 해로 마침","나팔꽃 — 한해살이 · 덩굴로 자라 꽃이 피고 씨를 남김","감나무 — 여러해살이 · 나무 · 해마다 꽃이 피고 감을 맺음","사과나무 — 여러해살이 · 나무 · 해마다 사과를 맺음","민들레 — 여러해살이 · 풀 · 뿌리가 겨울을 나고 봄에 다시 자람"],"title":"식물 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
