INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_challenge#5','sci',3,1,'u4','L06','g3_1_sci_u4_L06_challenge','lesson_challenge','SC3-1-u4-C37',3,'ox','auto','기준을 「한 해만 사는가?」에서 「나무인가?」로 바꾸면 식물의 무리가 달라질 수 있어요.',ARRAY['SC3-1-u4-X31']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C37","difficulty":3,"kind":"ox","stem":"기준을 「한 해만 사는가?」에서 「나무인가?」로 바꾸면 식물의 무리가 달라질 수 있어요.","answer":"O","reason_options":[{"t":"민들레는 여러해살이라 감나무와 같은 무리였지만 풀이라서 나무 무리에서는 빠지기 때문에","correct":true},{"t":"한 식물은 어떤 기준으로 나누어도 늘 같은 무리에 들기 때문에","mis":"SC3-1-u4-X31"}],"mis":"SC3-1-u4-X31","explanation":["민들레를 따라가 봐요.","무리가 바뀌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_challenge#6','sci',3,1,'u4','L06','g3_1_sci_u4_L06_challenge','lesson_challenge','SC3-1-u4-C33',3,'mc','auto','나팔꽃과 사과나무의 한살이를 바르게 견준 것은 무엇인가요?',ARRAY['SC3-1-u4-X29','SC3-1-u4-X28']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C33","difficulty":3,"kind":"mc","stem":"나팔꽃과 사과나무의 한살이를 바르게 견준 것은 무엇인가요?","options":[{"t":"둘 다 씨에서 시작하지만, 나팔꽃은 한 해로 마치고 사과나무는 여러 해 살아요","correct":true},{"t":"둘 다 한 해로 한살이를 마쳐요","mis":"SC3-1-u4-X29"},{"t":"나팔꽃은 여러 해, 사과나무는 한 해만 살아요","mis":"SC3-1-u4-X29"},{"t":"둘의 한살이는 처음과 끝이 전혀 달라요","mis":"SC3-1-u4-X28"}],"explanation":["같은 점과 다른 점이에요.","사는 기간이 달라요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_challenge#7','sci',3,1,'u4','L06','g3_1_sci_u4_L06_challenge','lesson_challenge','SC3-1-u4-C34',3,'mc','auto','봄에 심은 벼를 가을에 거두었어요. 이듬해 봄에 다시 벼를 기르려면 어떻게 해야 할까요?',ARRAY['SC3-1-u4-X29','SC3-1-u4-X30','SC3-1-u4-X28']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C34","difficulty":3,"kind":"mc","stem":"봄에 심은 벼를 가을에 거두었어요. 이듬해 봄에 다시 벼를 기르려면 어떻게 해야 할까요?","options":[{"t":"남겨 둔 벼의 씨를 다시 심어요","correct":true},{"t":"지난해 벼가 저절로 다시 자라길 기다려요","mis":"SC3-1-u4-X29"},{"t":"벼 뿌리에 물만 계속 줘요","mis":"SC3-1-u4-X30"},{"t":"씨 없이도 벼는 저절로 생겨요","mis":"SC3-1-u4-X28"}],"explanation":["벼는 한해살이예요.","씨를 남겼어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_challenge#8','sci',3,1,'u4','L06','g3_1_sci_u4_L06_challenge','lesson_challenge','SC3-1-u4-C36',4,'mc','auto','친구가 「풀은 다 한해살이이고, 나무만 여러해살이야.」라고 했어요. 식물 조사표를 보고 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X30','SC3-1-u4-X29','SC3-1-u4-X28']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C36","difficulty":4,"kind":"mc","stem":"친구가 「풀은 다 한해살이이고, 나무만 여러해살이야.」라고 했어요. 식물 조사표를 보고 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「민들레처럼 여러 해 사는 풀도 있어. 나무인지 풀인지가 아니라 사는 기간으로 나눠.」","correct":true},{"t":"「맞아, 풀은 다 한해살이야.」","mis":"SC3-1-u4-X30"},{"t":"「감나무는 한 해만 살아.」","mis":"SC3-1-u4-X29"},{"t":"「여러해살이 식물은 꽃이 피지 않아.」","mis":"SC3-1-u4-X28"}],"explanation":["민들레를 봐요.","여러해살이 풀이에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["강낭콩 — 한해살이 · 씨 → 싹 → 자람 → 꽃 → 열매 · 가을에 씨를 남기고 마침","벼 — 한해살이 · 봄에 심어 가을에 거두고 한 해로 마침","나팔꽃 — 한해살이 · 덩굴로 자라 꽃이 피고 씨를 남김","감나무 — 여러해살이 · 나무 · 해마다 꽃이 피고 감을 맺음","사과나무 — 여러해살이 · 나무 · 해마다 사과를 맺음","민들레 — 여러해살이 · 풀 · 뿌리가 겨울을 나고 봄에 다시 자람"],"title":"식물 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_challenge#9','sci',3,1,'u4','L06','g3_1_sci_u4_L06_challenge','lesson_challenge','SC3-1-u4-C33',4,'mc','auto','친구가 「한해살이와 여러해살이는 한살이가 완전히 달라서 같은 점이 하나도 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X28','SC3-1-u4-X29']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C33","difficulty":4,"kind":"mc","stem":"친구가 「한해살이와 여러해살이는 한살이가 완전히 달라서 같은 점이 하나도 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「둘 다 씨 → 싹 → 자람 → 꽃 → 열매의 과정을 거쳐. 다른 점은 사는 기간이야.」","correct":true},{"t":"「맞아, 같은 점은 하나도 없어.」","mis":"SC3-1-u4-X28"},{"t":"「한해살이는 씨에서 시작하지 않아.」","mis":"SC3-1-u4-X28"},{"t":"「여러해살이는 한 해로 한살이를 마쳐.」","mis":"SC3-1-u4-X29"}],"explanation":["흐름을 견줘요.","씨에서 열매까지 같아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L06_challenge#10','sci',3,1,'u4','L06','g3_1_sci_u4_L06_challenge','lesson_challenge','SC3-1-u4-C35',4,'essay','teacher','식물 조사표에서 한해살이 식물 하나와 여러해살이 식물 하나를 골라 같은 점과 다른 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C35","difficulty":4,"kind":"essay","stem":"식물 조사표에서 한해살이 식물 하나와 여러해살이 식물 하나를 골라 같은 점과 다른 점을 쓰세요.","answer_guide":{"answer":"예: 강낭콩과 감나무를 골랐다. 같은 점 — 둘 다 씨에서 시작해 자라 꽃이 피고 열매를 맺는다. 다른 점 — 강낭콩은 한 해로 한살이를 마치지만 감나무는 여러 해 살며 해마다 감을 맺는다.","scoring_points":["한해살이·여러해살이 식물을 하나씩 바르게 골랐는가","씨에서 열매까지의 같은 점을 썼는가","사는 기간의 다른 점을 썼는가"]},"explanation":["조사표를 읽어요.","하나씩 골라요.","같은 점과 다른 점을 써요."],"asset":{"type":"passage","lines":["강낭콩 — 한해살이 · 씨 → 싹 → 자람 → 꽃 → 열매 · 가을에 씨를 남기고 마침","벼 — 한해살이 · 봄에 심어 가을에 거두고 한 해로 마침","나팔꽃 — 한해살이 · 덩굴로 자라 꽃이 피고 씨를 남김","감나무 — 여러해살이 · 나무 · 해마다 꽃이 피고 감을 맺음","사과나무 — 여러해살이 · 나무 · 해마다 사과를 맺음","민들레 — 여러해살이 · 풀 · 뿌리가 겨울을 나고 봄에 다시 자람"],"title":"식물 조사표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#1','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C41',1,'mc','auto','한살이 소개 자료에 꼭 담아야 할 것은 무엇인가요?',ARRAY['SC3-1-u4-X34']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C41","difficulty":1,"kind":"mc","stem":"한살이 소개 자료에 꼭 담아야 할 것은 무엇인가요?","options":[{"t":"한살이 순서","correct":true},{"t":"좋아하는 색깔","mis":"SC3-1-u4-X34"},{"t":"반짝이 스티커","mis":"SC3-1-u4-X34"},{"t":"내 별명","mis":"SC3-1-u4-X34"}],"explanation":["한살이를 소개해요.","차례가 중요해요.","한살이 순서예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#2','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C38',1,'ox','auto','돌과 자동차에도 한살이가 있어요.',ARRAY['SC3-1-u4-X32']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C38","difficulty":1,"kind":"ox","stem":"돌과 자동차에도 한살이가 있어요.","answer":"X","reason_options":[{"t":"돌과 자동차는 생물이 아니라 나고 자라 자손을 남기지 않기 때문에","correct":true},{"t":"물건도 하나같이 자라서 자손을 남기기 때문에","mis":"SC3-1-u4-X32"}],"mis":"SC3-1-u4-X32","explanation":["돌이 자라나요?","자손을 남기나요?","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#3','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C39',1,'mc','auto','강낭콩의 한살이는 무엇으로 시작하나요?',ARRAY['SC3-1-u4-X33']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C39","difficulty":1,"kind":"mc","stem":"강낭콩의 한살이는 무엇으로 시작하나요?","options":[{"t":"씨","correct":true},{"t":"알","mis":"SC3-1-u4-X33"},{"t":"새끼","mis":"SC3-1-u4-X33"},{"t":"애벌레","mis":"SC3-1-u4-X33"}],"explanation":["강낭콩은 식물이에요.","심어요.","씨예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#4','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C39',1,'sa','auto','동물은 알이나 새끼로, 식물은 ○로 한살이를 시작해요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u4-C39","difficulty":1,"kind":"sa","stem":"동물은 알이나 새끼로, 식물은 ○로 한살이를 시작해요. ○에 알맞은 한 글자를 쓰세요.","answer":["씨"],"explanation":["강낭콩을 떠올려요.","심는 것이에요.","「씨」예요."],"mis":"SC3-1-u4-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#5','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C39',2,'match','auto','생물과 한살이의 시작을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u4-C39","difficulty":2,"kind":"match","stem":"생물과 한살이의 시작을 알맞게 이으세요.","pairs":[{"l":"닭","r":"알로 시작"},{"l":"강낭콩","r":"씨로 시작"},{"l":"개","r":"새끼로 시작"}],"mis":"SC3-1-u4-X33","explanation":["동물인가요, 식물인가요?","알·새끼·씨예요.","하나씩 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#6','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C38',2,'mc','auto','한살이를 소개할 수 있는 것끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X32']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C38","difficulty":2,"kind":"mc","stem":"한살이를 소개할 수 있는 것끼리 모은 것은 무엇인가요?","options":[{"t":"배추흰나비, 닭, 강낭콩","correct":true},{"t":"돌, 자동차, 강낭콩","mis":"SC3-1-u4-X32"},{"t":"자동차, 닭, 연필","mis":"SC3-1-u4-X32"},{"t":"돌, 배추흰나비, 의자","mis":"SC3-1-u4-X32"}],"explanation":["생물만 골라요.","돌·자동차는 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#7','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C42',2,'mc','auto','개를 소개하는 카드에 알맞은 한살이는 무엇인가요?',ARRAY['SC3-1-u4-X35']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C42","difficulty":2,"kind":"mc","stem":"개를 소개하는 카드에 알맞은 한살이는 무엇인가요?","options":[{"t":"갓 태어난 강아지 → 큰 강아지 → 다 자란 개","correct":true},{"t":"알 → 강아지 → 다 자란 개","mis":"SC3-1-u4-X35"},{"t":"씨 → 싹 → 꽃 → 열매","mis":"SC3-1-u4-X35"},{"t":"알 → 애벌레 → 번데기 → 어른벌레","mis":"SC3-1-u4-X35"}],"explanation":["개는 새끼를 낳아요.","강아지부터예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#8','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C41',2,'ox','auto','소개 자료는 한살이 순서보다 그림을 예쁘게 꾸미는 것이 더 중요해요.',ARRAY['SC3-1-u4-X34']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C41","difficulty":2,"kind":"ox","stem":"소개 자료는 한살이 순서보다 그림을 예쁘게 꾸미는 것이 더 중요해요.","answer":"X","reason_options":[{"t":"보는 사람이 한살이를 바르게 알려면 순서를 바르게 담는 것이 가장 중요하기 때문에","correct":true},{"t":"꾸미기만 잘하면 순서가 틀려도 괜찮기 때문에","mis":"SC3-1-u4-X34"}],"mis":"SC3-1-u4-X34","explanation":["무엇을 알려 주나요?","한살이예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_basic#9','sci',3,1,'u4','L07','g3_1_sci_u4_L07_basic','lesson_basic','SC3-1-u4-C40',2,'mc','auto','모둠 소개 카드 계획에서 생물의 특징을 담은 칸은 어느 것인가요?',ARRAY['SC3-1-u4-X34','SC3-1-u4-X40']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C40","difficulty":2,"kind":"mc","stem":"모둠 소개 카드 계획에서 생물의 특징을 담은 칸은 어느 것인가요?","options":[{"t":"③ 칸","correct":true},{"t":"① 칸","mis":"SC3-1-u4-X34"},{"t":"② 칸","mis":"SC3-1-u4-X40"},{"t":"④ 칸","mis":"SC3-1-u4-X34"}],"explanation":["「특징」을 찾아요.","번데기 이야기예요.","③ 칸이에요."],"asset":{"type":"passage","lines":["① 생물 이름 — 배추흰나비","② 한살이 순서 — 알 → 애벌레 → 번데기 → 어른벌레","③ 특징 — 번데기 때는 움직이지 않고 먹지 않음","④ 꾸미기 — 테두리를 반짝이 스티커로 꾸밈"],"title":"모둠 소개 카드 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
