INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#3','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C42',3,'error','auto','친구들이 소개 카드에 한살이를 적었어요. 잘못 적은 친구는 누구인가요?',ARRAY['SC3-1-u4-X35']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C42","difficulty":3,"kind":"error","stem":"친구들이 소개 카드에 한살이를 적었어요. 잘못 적은 친구는 누구인가요?","options":[{"t":"친구 다 — 「강낭콩: 알 → 애벌레 → 번데기 → 어른벌레」","correct":true,"mis_target":"SC3-1-u4-X35"},{"t":"친구 가 — 「배추흰나비: 알 → 애벌레 → 번데기 → 어른벌레」","mis":"SC3-1-u4-X35"},{"t":"친구 나 — 「닭: 알 → 병아리 → 어린 닭 → 다 자란 닭」","mis":"SC3-1-u4-X35"}],"explanation":["강낭콩은 식물이에요.","씨로 시작해요.","친구 다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#4','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C38',3,'mc','auto','한살이가 있는 것과 없는 것을 바르게 나눈 것은 무엇인가요?',ARRAY['SC3-1-u4-X32']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C38","difficulty":3,"kind":"mc","stem":"한살이가 있는 것과 없는 것을 바르게 나눈 것은 무엇인가요?","options":[{"t":"있음 — 개, 강낭콩 / 없음 — 돌, 자동차","correct":true},{"t":"있음 — 돌, 개 / 없음 — 강낭콩, 자동차","mis":"SC3-1-u4-X32"},{"t":"있음 — 자동차, 강낭콩 / 없음 — 돌, 개","mis":"SC3-1-u4-X32"},{"t":"넷 다 한살이가 있어요","mis":"SC3-1-u4-X32"}],"explanation":["생물인가요?","돌·자동차는 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#5','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C42',3,'ox','auto','배추흰나비를 소개하면서 「알 → 번데기 → 애벌레 → 어른벌레」로 적어도 괜찮아요.',ARRAY['SC3-1-u4-X40']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C42","difficulty":3,"kind":"ox","stem":"배추흰나비를 소개하면서 「알 → 번데기 → 애벌레 → 어른벌레」로 적어도 괜찮아요.","answer":"X","reason_options":[{"t":"애벌레가 번데기보다 먼저이므로 순서가 뒤바뀌면 바른 소개가 아니기 때문에","correct":true},{"t":"단계 이름만 다 들어가면 순서는 상관없기 때문에","mis":"SC3-1-u4-X40"}],"mis":"SC3-1-u4-X40","explanation":["순서를 확인해요.","애벌레가 먼저예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#6','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C41',3,'mc','auto','가장 좋은 소개 자료는 어떤 것일까요?',ARRAY['SC3-1-u4-X34','SC3-1-u4-X40']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C41","difficulty":3,"kind":"mc","stem":"가장 좋은 소개 자료는 어떤 것일까요?","options":[{"t":"한살이 순서를 바르게 담고 이름과 특징도 넣은 자료","correct":true},{"t":"색깔만 화려한 자료","mis":"SC3-1-u4-X34"},{"t":"한살이 순서가 뒤바뀐 자료","mis":"SC3-1-u4-X40"},{"t":"글씨만 빽빽하게 가득한 자료","mis":"SC3-1-u4-X34"}],"explanation":["보는 사람을 생각해요.","순서가 가장 중요해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#7','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C39',3,'mc','auto','닭과 강낭콩의 한살이 시작을 바르게 견준 것은 무엇인가요?',ARRAY['SC3-1-u4-X33']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C39","difficulty":3,"kind":"mc","stem":"닭과 강낭콩의 한살이 시작을 바르게 견준 것은 무엇인가요?","options":[{"t":"닭은 알로, 강낭콩은 씨로 시작해요","correct":true},{"t":"닭은 씨로, 강낭콩은 알로 시작해요","mis":"SC3-1-u4-X33"},{"t":"둘 다 새끼로 시작해요","mis":"SC3-1-u4-X33"},{"t":"둘 다 알로 시작해요","mis":"SC3-1-u4-X33"}],"explanation":["동물과 식물이에요.","알과 씨예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#8','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C41',4,'mc','auto','모둠 소개 카드 계획을 본 친구가 「④ 꾸미기에 시간을 다 쓰고 ②는 대충 적자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X34','SC3-1-u4-X40']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C41","difficulty":4,"kind":"mc","stem":"모둠 소개 카드 계획을 본 친구가 「④ 꾸미기에 시간을 다 쓰고 ②는 대충 적자.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「한살이 순서가 가장 중요하니 ②를 먼저 바르게 적고, 꾸미기는 그다음에 하자.」","correct":true},{"t":"「좋아, 꾸미기만 잘하면 돼.」","mis":"SC3-1-u4-X34"},{"t":"「②는 순서를 섞어 적어도 괜찮아.」","mis":"SC3-1-u4-X40"},{"t":"「①과 ③도 빼고 그림만 그리자.」","mis":"SC3-1-u4-X34"}],"explanation":["무엇이 먼저일까요?","②예요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["① 생물 이름 — 배추흰나비","② 한살이 순서 — 알 → 애벌레 → 번데기 → 어른벌레","③ 특징 — 번데기 때는 움직이지 않고 먹지 않음","④ 꾸미기 — 테두리를 반짝이 스티커로 꾸밈"],"title":"모둠 소개 카드 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#9','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C42',4,'mc','auto','친구가 「개도 닭처럼 알에서 깨어나니까 카드에 ‘알 → 강아지 → 개’라고 적을래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X13','SC3-1-u4-X33','SC3-1-u4-X40']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C42","difficulty":4,"kind":"mc","stem":"친구가 「개도 닭처럼 알에서 깨어나니까 카드에 ‘알 → 강아지 → 개’라고 적을래.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「개는 새끼를 낳는 동물이야. ‘갓 태어난 강아지 → 큰 강아지 → 다 자란 개’로 적자.」","correct":true},{"t":"「맞아, 개도 알에서 깨어나.」","mis":"SC3-1-u4-X13"},{"t":"「개는 씨에서 시작해.」","mis":"SC3-1-u4-X33"},{"t":"「순서는 아무렇게나 적어도 돼.」","mis":"SC3-1-u4-X40"}],"explanation":["개를 떠올려요.","새끼를 낳아요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L07_challenge#10','sci',3,1,'u4','L07','g3_1_sci_u4_L07_challenge','lesson_challenge','SC3-1-u4-C40',4,'essay','teacher','내가 소개하고 싶은 생물 하나를 골라 소개 카드에 담을 이름, 한살이 순서, 특징을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C40","difficulty":4,"kind":"essay","stem":"내가 소개하고 싶은 생물 하나를 골라 소개 카드에 담을 이름, 한살이 순서, 특징을 쓰세요.","answer_guide":{"answer":"예: 이름 — 닭. 한살이 순서 — 알 → 병아리 → 어린 닭 → 다 자란 닭. 특징 — 어미 닭이 단단한 껍데기에 싸인 알을 낳고, 알에서 병아리가 깨어난다.","scoring_points":["생물 이름을 썼는가","한살이 순서를 바르게 썼는가","그 생물의 특징을 썼는가"]},"explanation":["생물을 골라요.","순서가 핵심이에요.","세 가지를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_basic#1','sci',3,1,'u4','L08','g3_1_sci_u4_L08_basic','lesson_basic','SC3-1-u4-C45',1,'mc','auto','잠자리의 한살이에 없는 단계는 무엇인가요?',ARRAY['SC3-1-u4-X36','SC3-1-u4-X38']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C45","difficulty":1,"kind":"mc","stem":"잠자리의 한살이에 없는 단계는 무엇인가요?","options":[{"t":"번데기","correct":true},{"t":"알","mis":"SC3-1-u4-X36"},{"t":"애벌레","mis":"SC3-1-u4-X38"},{"t":"어른벌레","mis":"SC3-1-u4-X38"}],"explanation":["잠자리를 떠올려요.","애벌레에서 바로 어른벌레예요.","번데기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_basic#2','sci',3,1,'u4','L08','g3_1_sci_u4_L08_basic','lesson_basic','SC3-1-u4-C43',1,'ox','auto','모든 곤충은 알에서 한살이를 시작해요.',ARRAY['SC3-1-u4-X36']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C43","difficulty":1,"kind":"ox","stem":"모든 곤충은 알에서 한살이를 시작해요.","answer":"O","reason_options":[{"t":"배추흰나비도 잠자리도 알에서 시작하기 때문에","correct":true},{"t":"어떤 곤충은 어미젖을 먹는 새끼로 태어나기 때문에","mis":"SC3-1-u4-X36"}],"mis":"SC3-1-u4-X36","explanation":["곤충의 처음을 봐요.","알이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_basic#3','sci',3,1,'u4','L08','g3_1_sci_u4_L08_basic','lesson_basic','SC3-1-u4-C44',1,'mc','auto','배추흰나비 한살이에서 애벌레 다음 단계는 무엇인가요?',ARRAY['SC3-1-u4-X06','SC3-1-u4-X38','SC3-1-u4-X33']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C44","difficulty":1,"kind":"mc","stem":"배추흰나비 한살이에서 애벌레 다음 단계는 무엇인가요?","options":[{"t":"번데기","correct":true},{"t":"알","mis":"SC3-1-u4-X06"},{"t":"어른벌레","mis":"SC3-1-u4-X38"},{"t":"씨","mis":"SC3-1-u4-X33"}],"explanation":["배추흰나비를 떠올려요.","번데기가 있어요.","번데기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_basic#4','sci',3,1,'u4','L08','g3_1_sci_u4_L08_basic','lesson_basic','SC3-1-u4-C46',1,'sa','auto','곤충 한살이 카드를 보고, 잠자리 애벌레가 사는 곳을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SC3-1-u4-C46","difficulty":1,"kind":"sa","stem":"곤충 한살이 카드를 보고, 잠자리 애벌레가 사는 곳을 두 글자로 쓰세요.","answer":["물속","물"],"explanation":["잠자리 줄을 읽어요.","연못이에요.","「물속」이에요."],"asset":{"type":"passage","lines":["배추흰나비 — 알 → 애벌레 → 번데기 → 어른벌레","무당벌레 — 알 → 애벌레 → 번데기 → 어른벌레","사슴벌레 — 번데기 단계 있음 · 애벌레가 나무 속에서 자람","잠자리 — 알 → 애벌레 → 어른벌레 · 애벌레가 물속에서 삶","메뚜기 — 번데기 단계 없음 · 애벌레가 어른벌레와 닮음","매미 — 번데기 단계 없음 · 애벌레가 땅속에서 오래 삶"],"title":"곤충 한살이 카드"},"mis":"SC3-1-u4-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_basic#5','sci',3,1,'u4','L08','g3_1_sci_u4_L08_basic','lesson_basic','SC3-1-u4-C44',2,'match','auto','곤충 한살이 카드를 보고 곤충과 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SC3-1-u4-C44","difficulty":2,"kind":"match","stem":"곤충 한살이 카드를 보고 곤충과 특징을 알맞게 이으세요.","pairs":[{"l":"무당벌레","r":"번데기 단계가 있음"},{"l":"잠자리","r":"애벌레가 물속에서 삶"},{"l":"매미","r":"애벌레가 땅속에서 오래 삶"}],"mis":"SC3-1-u4-X38","explanation":["카드를 한 줄씩 읽어요.","특징을 찾아요.","하나씩 이어요."],"asset":{"type":"passage","lines":["배추흰나비 — 알 → 애벌레 → 번데기 → 어른벌레","무당벌레 — 알 → 애벌레 → 번데기 → 어른벌레","사슴벌레 — 번데기 단계 있음 · 애벌레가 나무 속에서 자람","잠자리 — 알 → 애벌레 → 어른벌레 · 애벌레가 물속에서 삶","메뚜기 — 번데기 단계 없음 · 애벌레가 어른벌레와 닮음","매미 — 번데기 단계 없음 · 애벌레가 땅속에서 오래 삶"],"title":"곤충 한살이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
