INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#1','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C45',2,'blank','auto','「잠자리, 메뚜기, 매미는 (      ) 단계 없이 어른벌레가 돼요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SC3-1-u4-X36','SC3-1-u4-X38']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C45","difficulty":2,"kind":"blank","stem":"「잠자리, 메뚜기, 매미는 (      ) 단계 없이 어른벌레가 돼요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"번데기","correct":true},{"t":"알","mis":"SC3-1-u4-X36"},{"t":"애벌레","mis":"SC3-1-u4-X38"},{"t":"어른벌레","mis":"SC3-1-u4-X38"}],"explanation":["배추흰나비에게는 있어요.","움직이지 않는 단계예요.","「번데기」예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#2','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C43',2,'mc','auto','여러 곤충의 한살이에서 닮은 점은 무엇인가요?',ARRAY['SC3-1-u4-X37','SC3-1-u4-X39','SC3-1-u4-X36']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C43","difficulty":2,"kind":"mc","stem":"여러 곤충의 한살이에서 닮은 점은 무엇인가요?","options":[{"t":"모두 알에서 시작해요","correct":true},{"t":"번데기를 하나같이 거쳐요","mis":"SC3-1-u4-X37"},{"t":"애벌레가 하나같이 물속에서 살아요","mis":"SC3-1-u4-X39"},{"t":"곤충은 새끼를 낳아요","mis":"SC3-1-u4-X36"}],"explanation":["처음을 견줘요.","알이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#3','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C45',3,'error','auto','친구들이 곤충 한살이 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SC3-1-u4-X38','SC3-1-u4-X39']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C45","difficulty":3,"kind":"error","stem":"친구들이 곤충 한살이 카드를 보고 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「메뚜기도 배추흰나비처럼 번데기를 거쳐.」","correct":true,"mis_target":"SC3-1-u4-X38"},{"t":"친구 가 — 「무당벌레는 번데기 단계가 있어.」","mis":"SC3-1-u4-X38"},{"t":"친구 다 — 「잠자리 애벌레는 물속에서 살아.」","mis":"SC3-1-u4-X39"}],"explanation":["메뚜기 줄을 읽어요.","번데기가 없어요.","친구 나예요."],"asset":{"type":"passage","lines":["배추흰나비 — 알 → 애벌레 → 번데기 → 어른벌레","무당벌레 — 알 → 애벌레 → 번데기 → 어른벌레","사슴벌레 — 번데기 단계 있음 · 애벌레가 나무 속에서 자람","잠자리 — 알 → 애벌레 → 어른벌레 · 애벌레가 물속에서 삶","메뚜기 — 번데기 단계 없음 · 애벌레가 어른벌레와 닮음","매미 — 번데기 단계 없음 · 애벌레가 땅속에서 오래 삶"],"title":"곤충 한살이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#4','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C44',3,'mc','auto','잠자리와 배추흰나비 한살이의 다른 점은 무엇인가요?',ARRAY['SC3-1-u4-X36','SC3-1-u4-X38','SC3-1-u4-X37']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C44","difficulty":3,"kind":"mc","stem":"잠자리와 배추흰나비 한살이의 다른 점은 무엇인가요?","options":[{"t":"잠자리는 번데기 단계가 없어요","correct":true},{"t":"잠자리는 알을 낳지 않아요","mis":"SC3-1-u4-X36"},{"t":"배추흰나비는 애벌레가 없어요","mis":"SC3-1-u4-X38"},{"t":"둘의 한살이는 하나도 다르지 않아요","mis":"SC3-1-u4-X37"}],"explanation":["번데기를 봐요.","잠자리에게는 없어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#5','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C47',3,'ox','auto','「번데기 단계가 있는가?」와 「애벌레가 물에서 사는가?」로 나누면 잠자리와 함께 묶이는 곤충이 달라져요.',ARRAY['SC3-1-u4-X31']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C47","difficulty":3,"kind":"ox","stem":"「번데기 단계가 있는가?」와 「애벌레가 물에서 사는가?」로 나누면 잠자리와 함께 묶이는 곤충이 달라져요.","answer":"O","reason_options":[{"t":"번데기 기준에서는 메뚜기·매미와 같은 무리지만 물 기준에서는 잠자리 혼자 「그렇다」 무리이기 때문에","correct":true},{"t":"한 곤충은 어떤 기준으로 나누어도 늘 같은 친구들과 묶이기 때문에","mis":"SC3-1-u4-X31"}],"mis":"SC3-1-u4-X31","explanation":["잠자리를 따라가 봐요.","함께 묶이는 곤충이 바뀌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["배추흰나비 — 알 → 애벌레 → 번데기 → 어른벌레","무당벌레 — 알 → 애벌레 → 번데기 → 어른벌레","사슴벌레 — 번데기 단계 있음 · 애벌레가 나무 속에서 자람","잠자리 — 알 → 애벌레 → 어른벌레 · 애벌레가 물속에서 삶","메뚜기 — 번데기 단계 없음 · 애벌레가 어른벌레와 닮음","매미 — 번데기 단계 없음 · 애벌레가 땅속에서 오래 삶"],"title":"곤충 한살이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#6','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C46',3,'mc','auto','잠자리 애벌레가 사는 곳과 어른벌레가 사는 곳을 바르게 견준 것은 무엇인가요?',ARRAY['SC3-1-u4-X39']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C46","difficulty":3,"kind":"mc","stem":"잠자리 애벌레가 사는 곳과 어른벌레가 사는 곳을 바르게 견준 것은 무엇인가요?","options":[{"t":"애벌레는 물속에서, 어른벌레는 물 밖으로 나와 하늘을 날며 살아요","correct":true},{"t":"둘 다 물속에서만 살아요","mis":"SC3-1-u4-X39"},{"t":"애벌레는 하늘을, 어른벌레는 물속을 다녀요","mis":"SC3-1-u4-X39"},{"t":"둘 다 땅속에서 오래 살아요","mis":"SC3-1-u4-X39"}],"explanation":["애벌레는 물속이에요.","어른은 날아요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#7','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C43',3,'mc','auto','곤충 한살이 카드의 여섯 곤충에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X37','SC3-1-u4-X38','SC3-1-u4-X36']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C43","difficulty":3,"kind":"mc","stem":"곤충 한살이 카드의 여섯 곤충에 대해 알맞은 것은 무엇인가요?","options":[{"t":"모두 알에서 시작하지만 번데기 단계는 있기도 하고 없기도 해요","correct":true},{"t":"여섯 곤충 모두 번데기 단계가 있어요","mis":"SC3-1-u4-X37"},{"t":"여섯 곤충 모두 번데기 단계가 없어요","mis":"SC3-1-u4-X38"},{"t":"어떤 곤충은 새끼로 태어나요","mis":"SC3-1-u4-X36"}],"explanation":["처음은 같아요.","번데기는 달라요.","첫 번째예요."],"asset":{"type":"passage","lines":["배추흰나비 — 알 → 애벌레 → 번데기 → 어른벌레","무당벌레 — 알 → 애벌레 → 번데기 → 어른벌레","사슴벌레 — 번데기 단계 있음 · 애벌레가 나무 속에서 자람","잠자리 — 알 → 애벌레 → 어른벌레 · 애벌레가 물속에서 삶","메뚜기 — 번데기 단계 없음 · 애벌레가 어른벌레와 닮음","매미 — 번데기 단계 없음 · 애벌레가 땅속에서 오래 삶"],"title":"곤충 한살이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#8','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C45',4,'mc','auto','친구가 「매미는 번데기를 거치지 않으니 한살이가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X37','SC3-1-u4-X36','SC3-1-u4-X39']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C45","difficulty":4,"kind":"mc","stem":"친구가 「매미는 번데기를 거치지 않으니 한살이가 없어.」라고 했어요. 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「매미도 알 → 애벌레 → 어른벌레로 자라 자손을 남기니 한살이가 있어. 번데기 단계만 없을 뿐이야.」","correct":true},{"t":"「맞아, 번데기가 없으면 한살이가 없어.」","mis":"SC3-1-u4-X37"},{"t":"「매미는 새끼를 낳아 젖을 먹여.」","mis":"SC3-1-u4-X36"},{"t":"「매미 애벌레는 하늘을 날아다녀.」","mis":"SC3-1-u4-X39"}],"explanation":["매미도 자라요.","번데기만 없어요.","첫 번째가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#9','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C46',4,'mc','auto','연못에서 잠자리 애벌레를 보았어요. 가장 알맞은 행동은 무엇인가요?',ARRAY['SC3-1-u4-X39','SC3-1-u4-X05','SC3-1-u4-X37']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C46","difficulty":4,"kind":"mc","stem":"연못에서 잠자리 애벌레를 보았어요. 가장 알맞은 행동은 무엇인가요?","options":[{"t":"함부로 잡지 않고 물속에서 사는 모습을 조심히 살펴본 뒤 그대로 둬요","correct":true},{"t":"물 밖으로 꺼내 땅 위에 놓아 둬요","mis":"SC3-1-u4-X39"},{"t":"신기해서 통에 담아 집으로 가져가 가둬 둬요","mis":"SC3-1-u4-X05"},{"t":"번데기가 될 때까지 손으로 만져 봐요","mis":"SC3-1-u4-X37"}],"explanation":["애벌레는 물속에서 살아요.","생명을 아껴요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_L08_challenge#10','sci',3,1,'u4','L08','g3_1_sci_u4_L08_challenge','lesson_challenge','SC3-1-u4-C44',4,'essay','teacher','곤충 한살이 카드에서 번데기 단계가 있는 곤충과 없는 곤충을 하나씩 골라 한살이를 견주어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SC3-1-u4-C44","difficulty":4,"kind":"essay","stem":"곤충 한살이 카드에서 번데기 단계가 있는 곤충과 없는 곤충을 하나씩 골라 한살이를 견주어 쓰세요.","answer_guide":{"answer":"예: 배추흰나비는 알 → 애벌레 → 번데기 → 어른벌레로 자라고, 잠자리는 알 → 애벌레 → 어른벌레로 자란다. 둘 다 알에서 시작하지만 잠자리는 번데기 단계가 없고, 애벌레가 물속에서 산다.","scoring_points":["번데기가 있는 곤충과 없는 곤충을 바르게 골랐는가","두 곤충의 한살이 순서를 썼는가","알에서 시작하는 같은 점과 번데기의 다른 점을 썼는가"]},"explanation":["카드를 읽어요.","하나씩 골라요.","견주어 써요."],"asset":{"type":"passage","lines":["배추흰나비 — 알 → 애벌레 → 번데기 → 어른벌레","무당벌레 — 알 → 애벌레 → 번데기 → 어른벌레","사슴벌레 — 번데기 단계 있음 · 애벌레가 나무 속에서 자람","잠자리 — 알 → 애벌레 → 어른벌레 · 애벌레가 물속에서 삶","메뚜기 — 번데기 단계 없음 · 애벌레가 어른벌레와 닮음","매미 — 번데기 단계 없음 · 애벌레가 땅속에서 오래 삶"],"title":"곤충 한살이 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#1','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C1',1,'mc','auto','들꽃반 일지 ①에서 올챙이를 본 곳은 어디인가요?',ARRAY['SC3-1-u4-X01']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C1","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ①에서 올챙이를 본 곳은 어디인가요?","options":[{"t":"연못가","correct":true},{"t":"화단","mis":"SC3-1-u4-X01"},{"t":"닭장","mis":"SC3-1-u4-X01"},{"t":"교실 책상 위","mis":"SC3-1-u4-X01"}],"explanation":["둘째 줄을 읽어요.","물가예요.","연못가예요."],"asset":{"type":"passage","lines":["학교 둘레에서 생물을 찾았다.","화단에서 봉숭아를, 연못가에서 올챙이를 보았다.","닭장에서는 어미 닭과 병아리를 보았다.","친구 가 — 「병아리는 처음부터 어미 닭이랑 똑같이 생겼어.」"],"title":"들꽃반 일지 ① 주변의 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#2','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C8',1,'mc','auto','들꽃반 일지 ②에서 알을 찾은 곳은 어디인가요?',ARRAY['SC3-1-u4-X07']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C8","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ②에서 알을 찾은 곳은 어디인가요?","options":[{"t":"배춧잎 뒷면","correct":true},{"t":"꽃잎 위","mis":"SC3-1-u4-X07"},{"t":"연못 속","mis":"SC3-1-u4-X07"},{"t":"흙 속","mis":"SC3-1-u4-X07"}],"explanation":["첫째 줄을 읽어요.","배춧잎이에요.","배춧잎 뒷면이에요."],"asset":{"type":"passage","lines":["배춧잎 뒷면에서 노란 알을 찾았다.","얼마 뒤 초록색 애벌레가 잎을 갉아 먹으며 허물을 벗었다.","애벌레는 한곳에 붙어 움직이지 않는 번데기가 되었다.","번데기에서 날개 두 쌍, 다리 세 쌍인 어른벌레가 나왔다.","친구 나 — 「번데기는 꼼짝 안 하니 죽은 거야. 버리자.」"],"title":"들꽃반 일지 ② 배추흰나비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#3','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C17',1,'mc','auto','들꽃반 일지 ③에서 알에서 깨어난 것은 무엇인가요?',ARRAY['SC3-1-u4-X13','SC3-1-u4-X14']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C17","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ③에서 알에서 깨어난 것은 무엇인가요?","options":[{"t":"병아리","correct":true},{"t":"강아지","mis":"SC3-1-u4-X13"},{"t":"송아지","mis":"SC3-1-u4-X13"},{"t":"어미 닭","mis":"SC3-1-u4-X14"}],"explanation":["둘째 줄을 읽어요.","닭의 새끼예요.","병아리예요."],"asset":{"type":"passage","lines":["동물 농장에 갔다.","닭은 알을 낳았고, 알에서 병아리가 깨어났다.","개는 강아지를 낳아 어미젖을 먹였다.","소는 송아지를 낳았다.","친구 다 — 「동물은 다 알에서 깨어나.」"],"title":"들꽃반 일지 ③ 동물 농장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#4','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C25',1,'mc','auto','들꽃반 일지 ④에서 두 컵을 다르게 한 조건은 무엇인가요?',ARRAY['SC3-1-u4-X21','SC3-1-u4-X22']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C25","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ④에서 두 컵을 다르게 한 조건은 무엇인가요?","options":[{"t":"물","correct":true},{"t":"온도","mis":"SC3-1-u4-X21"},{"t":"강낭콩","mis":"SC3-1-u4-X22"},{"t":"탈지면","mis":"SC3-1-u4-X22"}],"explanation":["둘째 줄을 읽어요.","한 컵에만 주었어요.","물이에요."],"asset":{"type":"passage","lines":["컵 두 개에 탈지면을 깔고 같은 강낭콩을 넣었다.","두 컵 모두 따뜻한 곳에 두고, ㉮ 컵에만 물을 주었다.","얼마 뒤 ㉮ 컵의 강낭콩만 싹이 텄다.","친구 가 — 「싹 트는 데는 빛이 꼭 있어야 해.」"],"title":"들꽃반 일지 ④ 씨앗 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#5','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C31',1,'mc','auto','들꽃반 일지 ⑤에서 두 화분을 다르게 한 조건은 무엇인가요?',ARRAY['SC3-1-u4-X22']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C31","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑤에서 두 화분을 다르게 한 조건은 무엇인가요?","options":[{"t":"햇빛","correct":true},{"t":"물","mis":"SC3-1-u4-X22"},{"t":"흙","mis":"SC3-1-u4-X22"},{"t":"화분 크기","mis":"SC3-1-u4-X22"}],"explanation":["둘째 줄을 읽어요.","창가와 상자예요.","햇빛이에요."],"asset":{"type":"passage","lines":["어린 식물 두 화분에 물을 같게 주었다.","㉮ 화분은 창가에, ㉯ 화분은 어두운 상자 안에 두었다.","얼마 뒤 ㉮ 화분만 잘 자랐다.","친구 나 — 「식물은 물만 있으면 잘 자라.」"],"title":"들꽃반 일지 ⑤ 화분 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#6','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C34',1,'mc','auto','들꽃반 일지 ⑥에서 한 해로 한살이를 마친 식물은 무엇인가요?',ARRAY['SC3-1-u4-X29','SC3-1-u4-X30']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C34","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑥에서 한 해로 한살이를 마친 식물은 무엇인가요?","options":[{"t":"강낭콩","correct":true},{"t":"감나무","mis":"SC3-1-u4-X29"},{"t":"민들레","mis":"SC3-1-u4-X30"},{"t":"세 식물 모두","mis":"SC3-1-u4-X29"}],"explanation":["첫째 줄을 읽어요.","씨를 남기고 시들었어요.","강낭콩이에요."],"asset":{"type":"passage","lines":["학교 텃밭의 강낭콩은 가을에 씨를 남기고 시들었다.","운동장 감나무는 올해도 감이 열렸다.","화단 민들레는 겨울을 나고 봄에 다시 자랐다.","친구 다 — 「민들레는 풀이니까 한해살이야.」"],"title":"들꽃반 일지 ⑥ 식물의 한살이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#7','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C38',1,'ox','auto','들꽃반 일지 ⑦의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u4-X32']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C38","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ⑦의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"돌은 생물이 아니라 나고 자라 자손을 남기지 않기 때문에","correct":true},{"t":"돌도 작은 돌이 자라 큰 돌이 되기 때문에","mis":"SC3-1-u4-X32"}],"mis":"SC3-1-u4-X32","explanation":["돌을 떠올려요.","생물이 아니에요.","그래서 X예요."],"asset":{"type":"passage","lines":["모둠마다 생물의 한살이 소개 카드를 만들었다.","모둠 1 — 개: 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","모둠 2 — 강낭콩: 씨 → 싹 → 자람 → 꽃 → 열매","모둠 3 — 돌: 작은 돌 → 큰 돌","친구 가 — 「모둠 3처럼 돌도 한살이가 있어.」"],"title":"들꽃반 일지 ⑦ 소개 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#8','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C46',1,'mc','auto','들꽃반 일지 ⑧에서 물속에서 살고 있던 것은 무엇인가요?',ARRAY['SC3-1-u4-X39']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C46","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑧에서 물속에서 살고 있던 것은 무엇인가요?","options":[{"t":"잠자리 애벌레","correct":true},{"t":"메뚜기","mis":"SC3-1-u4-X39"},{"t":"무당벌레","mis":"SC3-1-u4-X39"},{"t":"배추흰나비 번데기","mis":"SC3-1-u4-X39"}],"explanation":["첫째 줄을 읽어요.","연못이에요.","잠자리 애벌레예요."],"asset":{"type":"passage","lines":["연못에서 잠자리 애벌레를 보았다. 물속에서 살고 있었다.","풀밭에서 메뚜기와 무당벌레를 보았다.","무당벌레는 번데기를 거치고, 메뚜기는 번데기 없이 자란다고 한다.","친구 나 — 「곤충은 다 번데기를 거쳐.」"],"title":"들꽃반 일지 ⑧ 곤충"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#9','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C5',2,'mc','auto','다음 가운데 한살이에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X04','SC3-1-u4-X02']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C5","difficulty":2,"kind":"mc","stem":"다음 가운데 한살이에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"동물도 식물도 한살이가 있어요","correct":true},{"t":"한살이는 동물에게만 있어요","mis":"SC3-1-u4-X04"},{"t":"생물은 자라지 않아요","mis":"SC3-1-u4-X02"},{"t":"다 자란 생물은 자손을 남기지 않아요","mis":"SC3-1-u4-X04"}],"explanation":["강낭콩도 생물이에요.","둘 다 있어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
