INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#20','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C41',3,'mc','auto','친구 소개 카드의 「알 → 어른벌레 → 애벌레 → 번데기」를 보고 고쳐야 할 점은 무엇인가요?',ARRAY['SC3-1-u4-X34','SC3-1-u4-X40','SC3-1-u4-X35']::text[],false,'{"seq":20,"concept":"SC3-1-u4-C41","difficulty":3,"kind":"mc","stem":"친구 소개 카드의 「알 → 어른벌레 → 애벌레 → 번데기」를 보고 고쳐야 할 점은 무엇인가요?","options":[{"t":"애벌레와 번데기를 거쳐 어른벌레가 되도록 순서를 바로잡아요","correct":true},{"t":"색을 더 화려하게 칠해요","mis":"SC3-1-u4-X34"},{"t":"순서는 그대로 두고 글씨만 크게 써요","mis":"SC3-1-u4-X40"},{"t":"어른벌레를 빼요","mis":"SC3-1-u4-X35"}],"explanation":["순서를 확인해요.","어른벌레가 마지막이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#21','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C47',3,'mc','auto','「번데기 단계가 있는가?」로 나누었을 때 잠자리와 같은 무리에 드는 곤충은 무엇인가요?',ARRAY['SC3-1-u4-X38']::text[],false,'{"seq":21,"concept":"SC3-1-u4-C47","difficulty":3,"kind":"mc","stem":"「번데기 단계가 있는가?」로 나누었을 때 잠자리와 같은 무리에 드는 곤충은 무엇인가요?","options":[{"t":"메뚜기","correct":true},{"t":"배추흰나비","mis":"SC3-1-u4-X38"},{"t":"무당벌레","mis":"SC3-1-u4-X38"},{"t":"사슴벌레","mis":"SC3-1-u4-X38"}],"explanation":["잠자리는 번데기가 없어요.","같은 곤충을 찾아요.","메뚜기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#22','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C24',3,'mc','auto','「씨는 빛이 없으면 싹이 트지 않을 거야.」라는 생각을 확인하려면 어떤 실험을 해야 할까요?',ARRAY['SC3-1-u4-X21','SC3-1-u4-X22']::text[],false,'{"seq":22,"concept":"SC3-1-u4-C24","difficulty":3,"kind":"mc","stem":"「씨는 빛이 없으면 싹이 트지 않을 거야.」라는 생각을 확인하려면 어떤 실험을 해야 할까요?","options":[{"t":"물과 온도는 같게 하고, 한 컵은 밝은 곳에, 다른 컵은 어두운 곳에 둬요","correct":true},{"t":"한 컵은 밝은 곳에 물을 주고, 다른 컵은 어두운 곳에 물을 주지 않아요","mis":"SC3-1-u4-X21"},{"t":"두 컵 모두 밝은 곳에 두고 물도 같게 줘요","mis":"SC3-1-u4-X22"},{"t":"씨는 한 컵에만 넣고 다른 컵은 비워 둬요","mis":"SC3-1-u4-X22"}],"explanation":["빛만 달라야 해요.","나머지는 같게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#23','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C2',4,'mc','auto','들꽃반 일지 ①의 친구 가에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X02','SC3-1-u4-X03','SC3-1-u4-X33']::text[],false,'{"seq":23,"concept":"SC3-1-u4-C2","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ①의 친구 가에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「병아리는 작게 깨어나 자라면서 점점 어미 닭의 모습이 돼. 생물은 자라며 모습이 변해.」","correct":true},{"t":"「맞아, 병아리와 어미 닭은 똑같아.」","mis":"SC3-1-u4-X02"},{"t":"「병아리는 자라서 개구리가 돼.」","mis":"SC3-1-u4-X03"},{"t":"「병아리는 씨에서 싹이 터서 생겨.」","mis":"SC3-1-u4-X33"}],"explanation":["병아리를 떠올려요.","자라며 변해요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["학교 둘레에서 생물을 찾았다.","화단에서 봉숭아를, 연못가에서 올챙이를 보았다.","닭장에서는 어미 닭과 병아리를 보았다.","친구 가 — 「병아리는 처음부터 어미 닭이랑 똑같이 생겼어.」"],"title":"들꽃반 일지 ① 주변의 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#24','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C30',4,'mc','auto','들꽃반 일지 ⑤의 친구 나에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X26','SC3-1-u4-X25','SC3-1-u4-X24']::text[],false,'{"seq":24,"concept":"SC3-1-u4-C30","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ⑤의 친구 나에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「물을 같게 주었는데 어두운 곳의 ㉯는 잘 자라지 못했어. 식물이 자라려면 물과 햇빛이 모두 필요해.」","correct":true},{"t":"「맞아, 물 하나면 충분해.」","mis":"SC3-1-u4-X26"},{"t":"「식물은 어두울수록 잘 자라.」","mis":"SC3-1-u4-X25"},{"t":"「㉮가 잘 자란 것은 물을 주지 않아서야.」","mis":"SC3-1-u4-X24"}],"explanation":["㉯를 봐요.","어두웠어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["어린 식물 두 화분에 물을 같게 주었다.","㉮ 화분은 창가에, ㉯ 화분은 어두운 상자 안에 두었다.","얼마 뒤 ㉮ 화분만 잘 자랐다.","친구 나 — 「식물은 물만 있으면 잘 자라.」"],"title":"들꽃반 일지 ⑤ 화분 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_a#25','sci',3,1,'u4','','g3_1_sci_u4_review_a','unit_review','SC3-1-u4-C7',4,'essay','teacher','들꽃반 일지 ②를 보고 배추흰나비의 한살이를 순서대로 쓰고, 단계마다 특징을 하나씩 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u4-C7","difficulty":4,"kind":"essay","stem":"들꽃반 일지 ②를 보고 배추흰나비의 한살이를 순서대로 쓰고, 단계마다 특징을 하나씩 쓰세요.","answer_guide":{"answer":"예: 알 → 애벌레 → 번데기 → 어른벌레. 알은 배춧잎 뒷면에 붙은 노란색이고, 애벌레는 잎을 갉아 먹으며 허물을 벗고, 번데기는 움직이지 않고 먹지 않으며, 어른벌레는 날개 두 쌍과 다리 세 쌍이 있다.","scoring_points":["한살이 순서를 바르게 썼는가","네 단계의 특징을 하나씩 썼는가","일지 내용과 맞게 썼는가"]},"explanation":["일지를 읽어요.","네 단계예요.","순서와 특징을 써요."],"asset":{"type":"passage","lines":["배춧잎 뒷면에서 노란 알을 찾았다.","얼마 뒤 초록색 애벌레가 잎을 갉아 먹으며 허물을 벗었다.","애벌레는 한곳에 붙어 움직이지 않는 번데기가 되었다.","번데기에서 날개 두 쌍, 다리 세 쌍인 어른벌레가 나왔다.","친구 나 — 「번데기는 꼼짝 안 하니 죽은 거야. 버리자.」"],"title":"들꽃반 일지 ② 배추흰나비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#1','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C1',1,'mc','auto','들꽃반 일지 ①에서 화단에서 본 식물은 무엇인가요?',ARRAY['SC3-1-u4-X41']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C1","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ①에서 화단에서 본 식물은 무엇인가요?","options":[{"t":"봉숭아","correct":true},{"t":"올챙이","mis":"SC3-1-u4-X41"},{"t":"병아리","mis":"SC3-1-u4-X41"},{"t":"어미 닭","mis":"SC3-1-u4-X41"}],"explanation":["둘째 줄을 읽어요.","식물이에요.","봉숭아예요."],"asset":{"type":"passage","lines":["학교 둘레에서 생물을 찾았다.","화단에서 봉숭아를, 연못가에서 올챙이를 보았다.","닭장에서는 어미 닭과 병아리를 보았다.","친구 가 — 「병아리는 처음부터 어미 닭이랑 똑같이 생겼어.」"],"title":"들꽃반 일지 ① 주변의 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#2','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C10',1,'ox','auto','들꽃반 일지 ②의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u4-X08']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C10","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ②의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"번데기는 움직이지 않고 먹지 않을 뿐 살아 있고, 곧 어른벌레가 나오기 때문에","correct":true},{"t":"움직이지 않는 번데기는 죽은 것이기 때문에","mis":"SC3-1-u4-X08"}],"mis":"SC3-1-u4-X08","explanation":["번데기 다음을 읽어요.","어른벌레가 나왔어요.","그래서 X예요."],"asset":{"type":"passage","lines":["배춧잎 뒷면에서 노란 알을 찾았다.","얼마 뒤 초록색 애벌레가 잎을 갉아 먹으며 허물을 벗었다.","애벌레는 한곳에 붙어 움직이지 않는 번데기가 되었다.","번데기에서 날개 두 쌍, 다리 세 쌍인 어른벌레가 나왔다.","친구 나 — 「번데기는 꼼짝 안 하니 죽은 거야. 버리자.」"],"title":"들꽃반 일지 ② 배추흰나비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#3','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C16',1,'mc','auto','들꽃반 일지 ③에서 새끼를 낳은 동물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X13']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C16","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ③에서 새끼를 낳은 동물끼리 모은 것은 무엇인가요?","options":[{"t":"개, 소","correct":true},{"t":"닭, 개","mis":"SC3-1-u4-X13"},{"t":"닭, 소","mis":"SC3-1-u4-X13"},{"t":"닭","mis":"SC3-1-u4-X13"}],"explanation":["「낳아」를 찾아요.","강아지·송아지예요.","개, 소예요."],"asset":{"type":"passage","lines":["동물 농장에 갔다.","닭은 알을 낳았고, 알에서 병아리가 깨어났다.","개는 강아지를 낳아 어미젖을 먹였다.","소는 송아지를 낳았다.","친구 다 — 「동물은 다 알에서 깨어나.」"],"title":"들꽃반 일지 ③ 동물 농장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#4','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C27',1,'mc','auto','들꽃반 일지 ④에서 싹이 튼 컵은 어느 것인가요?',ARRAY['SC3-1-u4-X18','SC3-1-u4-X23']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C27","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ④에서 싹이 튼 컵은 어느 것인가요?","options":[{"t":"㉮ 컵","correct":true},{"t":"물을 주지 않은 컵","mis":"SC3-1-u4-X18"},{"t":"두 컵 모두","mis":"SC3-1-u4-X18"},{"t":"두 컵 모두 싹이 트지 않았어요","mis":"SC3-1-u4-X23"}],"explanation":["셋째 줄을 읽어요.","물을 준 컵이에요.","㉮ 컵이에요."],"asset":{"type":"passage","lines":["컵 두 개에 탈지면을 깔고 같은 강낭콩을 넣었다.","두 컵 모두 따뜻한 곳에 두고, ㉮ 컵에만 물을 주었다.","얼마 뒤 ㉮ 컵의 강낭콩만 싹이 텄다.","친구 가 — 「싹 트는 데는 빛이 꼭 있어야 해.」"],"title":"들꽃반 일지 ④ 씨앗 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#5','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C29',1,'mc','auto','들꽃반 일지 ⑤에서 잘 자란 화분은 어느 것인가요?',ARRAY['SC3-1-u4-X25','SC3-1-u4-X24']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C29","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑤에서 잘 자란 화분은 어느 것인가요?","options":[{"t":"창가에 둔 ㉮ 화분","correct":true},{"t":"상자 안에 둔 ㉯ 화분","mis":"SC3-1-u4-X25"},{"t":"두 화분 모두","mis":"SC3-1-u4-X25"},{"t":"두 화분 모두 자라지 못했어요","mis":"SC3-1-u4-X24"}],"explanation":["셋째 줄을 읽어요.","창가예요.","㉮ 화분이에요."],"asset":{"type":"passage","lines":["어린 식물 두 화분에 물을 같게 주었다.","㉮ 화분은 창가에, ㉯ 화분은 어두운 상자 안에 두었다.","얼마 뒤 ㉮ 화분만 잘 자랐다.","친구 나 — 「식물은 물만 있으면 잘 자라.」"],"title":"들꽃반 일지 ⑤ 화분 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#6','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C35',1,'mc','auto','들꽃반 일지 ⑥에서 해마다 열매를 맺는 나무는 무엇인가요?',ARRAY['SC3-1-u4-X29']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C35","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑥에서 해마다 열매를 맺는 나무는 무엇인가요?","options":[{"t":"감나무","correct":true},{"t":"강낭콩","mis":"SC3-1-u4-X29"},{"t":"민들레","mis":"SC3-1-u4-X29"},{"t":"봉숭아","mis":"SC3-1-u4-X29"}],"explanation":["둘째 줄을 읽어요.","올해도 열렸어요.","감나무예요."],"asset":{"type":"passage","lines":["학교 텃밭의 강낭콩은 가을에 씨를 남기고 시들었다.","운동장 감나무는 올해도 감이 열렸다.","화단 민들레는 겨울을 나고 봄에 다시 자랐다.","친구 다 — 「민들레는 풀이니까 한해살이야.」"],"title":"들꽃반 일지 ⑥ 식물의 한살이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#7','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C39',1,'mc','auto','들꽃반 일지 ⑦에서 씨로 한살이를 시작하는 생물은 무엇인가요?',ARRAY['SC3-1-u4-X33','SC3-1-u4-X32']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C39","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑦에서 씨로 한살이를 시작하는 생물은 무엇인가요?","options":[{"t":"강낭콩","correct":true},{"t":"개","mis":"SC3-1-u4-X33"},{"t":"돌","mis":"SC3-1-u4-X32"},{"t":"강아지","mis":"SC3-1-u4-X33"}],"explanation":["모둠 2를 읽어요.","씨로 시작해요.","강낭콩이에요."],"asset":{"type":"passage","lines":["모둠마다 생물의 한살이 소개 카드를 만들었다.","모둠 1 — 개: 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","모둠 2 — 강낭콩: 씨 → 싹 → 자람 → 꽃 → 열매","모둠 3 — 돌: 작은 돌 → 큰 돌","친구 가 — 「모둠 3처럼 돌도 한살이가 있어.」"],"title":"들꽃반 일지 ⑦ 소개 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#8','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C45',1,'ox','auto','들꽃반 일지 ⑧의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u4-X37']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C45","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ⑧의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"메뚜기는 번데기 없이 자라기 때문에","correct":true},{"t":"곤충이라면 누구나 번데기를 거치기 때문에","mis":"SC3-1-u4-X37"}],"mis":"SC3-1-u4-X37","explanation":["셋째 줄을 읽어요.","메뚜기는 없어요.","그래서 X예요."],"asset":{"type":"passage","lines":["연못에서 잠자리 애벌레를 보았다. 물속에서 살고 있었다.","풀밭에서 메뚜기와 무당벌레를 보았다.","무당벌레는 번데기를 거치고, 메뚜기는 번데기 없이 자란다고 한다.","친구 나 — 「곤충은 다 번데기를 거쳐.」"],"title":"들꽃반 일지 ⑧ 곤충"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#9','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C3',2,'mc','auto','알 → 올챙이 → 개구리로 자라는 생물은 알을 어디에 낳나요?',ARRAY['SC3-1-u4-X03']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C3","difficulty":2,"kind":"mc","stem":"알 → 올챙이 → 개구리로 자라는 생물은 알을 어디에 낳나요?","options":[{"t":"물속","correct":true},{"t":"배춧잎 뒷면","mis":"SC3-1-u4-X03"},{"t":"나무 속","mis":"SC3-1-u4-X03"},{"t":"흙 속 씨앗 옆","mis":"SC3-1-u4-X03"}],"explanation":["올챙이는 헤엄쳐요.","물이에요.","물속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#10','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C10',2,'mc','auto','배추흰나비 한살이에서 먹지도 움직이지도 않는 단계는 무엇인가요?',ARRAY['SC3-1-u4-X08','SC3-1-u4-X07']::text[],false,'{"seq":10,"concept":"SC3-1-u4-C10","difficulty":2,"kind":"mc","stem":"배추흰나비 한살이에서 먹지도 움직이지도 않는 단계는 무엇인가요?","options":[{"t":"번데기","correct":true},{"t":"애벌레","mis":"SC3-1-u4-X08"},{"t":"알을 갓 깨고 나온 애벌레","mis":"SC3-1-u4-X07"},{"t":"어른벌레","mis":"SC3-1-u4-X07"}],"explanation":["가만히 있어요.","어른벌레 바로 앞이에요.","번데기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#11','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C19',2,'mc','auto','송아지와 다 자란 소를 견주었을 때 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X15','SC3-1-u4-X13','SC3-1-u4-X02']::text[],false,'{"seq":11,"concept":"SC3-1-u4-C19","difficulty":2,"kind":"mc","stem":"송아지와 다 자란 소를 견주었을 때 알맞은 것은 무엇인가요?","options":[{"t":"송아지는 다 자란 소와 생김새가 닮았어요","correct":true},{"t":"송아지는 알에서 깨어나요","mis":"SC3-1-u4-X15"},{"t":"송아지는 물속에서 헤엄치다 다리가 생겨요","mis":"SC3-1-u4-X13"},{"t":"송아지는 자라지 않아요","mis":"SC3-1-u4-X02"}],"explanation":["송아지를 떠올려요.","어미를 닮았어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#12','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C25',2,'ox','auto','공정한 실험을 하려면 다르게 할 조건을 하나만 정해요.',ARRAY['SC3-1-u4-X21']::text[],false,'{"seq":12,"concept":"SC3-1-u4-C25","difficulty":2,"kind":"ox","stem":"공정한 실험을 하려면 다르게 할 조건을 하나만 정해요.","answer":"O","reason_options":[{"t":"두 가지 이상을 다르게 하면 무엇 때문에 결과가 달라졌는지 알 수 없기 때문에","correct":true},{"t":"다르게 할 조건은 많을수록 좋기 때문에","mis":"SC3-1-u4-X21"}],"mis":"SC3-1-u4-X21","explanation":["무엇 때문인지 알려면","하나만 바꿔요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#13','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C28',2,'ox','auto','식물이 자라려면 물이 필요해요.',ARRAY['SC3-1-u4-X24']::text[],false,'{"seq":13,"concept":"SC3-1-u4-C28","difficulty":2,"kind":"ox","stem":"식물이 자라려면 물이 필요해요.","answer":"O","reason_options":[{"t":"물을 주지 않은 식물은 잘 자라지 못했기 때문에","correct":true},{"t":"식물은 물 없이도 잘 자라기 때문에","mis":"SC3-1-u4-X24"}],"mis":"SC3-1-u4-X24","explanation":["물을 주지 않은 화분을 떠올려요.","잘 못 자랐어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#14','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C35',2,'ox','auto','사과나무는 한 해만 살고 한살이를 마쳐요.',ARRAY['SC3-1-u4-X29']::text[],false,'{"seq":14,"concept":"SC3-1-u4-C35","difficulty":2,"kind":"ox","stem":"사과나무는 한 해만 살고 한살이를 마쳐요.","answer":"X","reason_options":[{"t":"사과나무는 여러 해 살면서 해마다 사과를 맺기 때문에","correct":true},{"t":"식물은 하나같이 한 해만 살기 때문에","mis":"SC3-1-u4-X29"}],"mis":"SC3-1-u4-X29","explanation":["사과나무를 떠올려요.","해마다 열려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#15','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C39',2,'mc','auto','알로 한살이를 시작하는 생물끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X33']::text[],false,'{"seq":15,"concept":"SC3-1-u4-C39","difficulty":2,"kind":"mc","stem":"알로 한살이를 시작하는 생물끼리 모은 것은 무엇인가요?","options":[{"t":"배추흰나비, 닭","correct":true},{"t":"강낭콩, 나팔꽃","mis":"SC3-1-u4-X33"},{"t":"개, 소","mis":"SC3-1-u4-X33"},{"t":"닭, 강낭콩","mis":"SC3-1-u4-X33"}],"explanation":["알을 찾아요.","나비와 닭이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#16','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C43',2,'ox','auto','번데기가 없는 곤충도 알에서 한살이를 시작해요.',ARRAY['SC3-1-u4-X36']::text[],false,'{"seq":16,"concept":"SC3-1-u4-C43","difficulty":2,"kind":"ox","stem":"번데기가 없는 곤충도 알에서 한살이를 시작해요.","answer":"O","reason_options":[{"t":"곤충은 모두 알에서 시작하고 번데기 단계만 있기도 없기도 하기 때문에","correct":true},{"t":"번데기가 없는 곤충은 새끼로 태어나기 때문에","mis":"SC3-1-u4-X36"}],"mis":"SC3-1-u4-X36","explanation":["잠자리를 떠올려요.","알에서 시작해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#17','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C7',3,'mc','auto','배추흰나비 한살이에서 알 바로 다음 단계와 어른벌레 바로 앞 단계를 차례대로 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u4-X06']::text[],false,'{"seq":17,"concept":"SC3-1-u4-C7","difficulty":3,"kind":"mc","stem":"배추흰나비 한살이에서 알 바로 다음 단계와 어른벌레 바로 앞 단계를 차례대로 짝 지은 것은 무엇인가요?","options":[{"t":"애벌레, 번데기","correct":true},{"t":"번데기, 애벌레","mis":"SC3-1-u4-X06"},{"t":"어른벌레, 알","mis":"SC3-1-u4-X06"},{"t":"번데기, 알","mis":"SC3-1-u4-X06"}],"explanation":["순서를 떠올려요.","알 → 애벌레 → 번데기 → 어른벌레","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#18','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C25',3,'mc','auto','알맞은 온도가 싹 트는 데 필요한지 알아보는 실험으로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X21','SC3-1-u4-X23','SC3-1-u4-X22']::text[],false,'{"seq":18,"concept":"SC3-1-u4-C25","difficulty":3,"kind":"mc","stem":"알맞은 온도가 싹 트는 데 필요한지 알아보는 실험으로 알맞은 것은 무엇인가요?","options":[{"t":"두 컵 모두 물을 주고, 한 컵은 따뜻한 곳에, 다른 컵은 차가운 곳에 둬요","correct":true},{"t":"한 컵은 물을 주고 따뜻한 곳에, 다른 컵은 물을 주지 않고 차가운 곳에 둬요","mis":"SC3-1-u4-X21"},{"t":"두 컵 모두 따뜻한 곳에 두고 물만 다르게 해요","mis":"SC3-1-u4-X23"},{"t":"두 컵을 같은 곳에 두고 물도 같게 줘요","mis":"SC3-1-u4-X22"}],"explanation":["온도만 달라야 해요.","물은 같게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#19','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C33',3,'ox','auto','여러해살이 식물도 씨에서 한살이를 시작해요.',ARRAY['SC3-1-u4-X28']::text[],false,'{"seq":19,"concept":"SC3-1-u4-C33","difficulty":3,"kind":"ox","stem":"여러해살이 식물도 씨에서 한살이를 시작해요.","answer":"O","reason_options":[{"t":"감나무도 사과나무도 씨에서 싹이 터서 자라기 때문에","correct":true},{"t":"여러해살이 식물은 씨 없이 처음부터 나무로 생기기 때문에","mis":"SC3-1-u4-X28"}],"mis":"SC3-1-u4-X28","explanation":["감나무를 떠올려요.","씨에서 시작해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#20','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C39',3,'mc','auto','닭, 개, 강낭콩의 한살이 시작을 바르게 짝 지은 것은 무엇인가요?',ARRAY['SC3-1-u4-X33','SC3-1-u4-X12']::text[],false,'{"seq":20,"concept":"SC3-1-u4-C39","difficulty":3,"kind":"mc","stem":"닭, 개, 강낭콩의 한살이 시작을 바르게 짝 지은 것은 무엇인가요?","options":[{"t":"닭 — 알, 개 — 새끼, 강낭콩 — 씨","correct":true},{"t":"닭 — 새끼, 개 — 알, 강낭콩 — 씨","mis":"SC3-1-u4-X33"},{"t":"닭 — 알, 개 — 알, 강낭콩 — 알","mis":"SC3-1-u4-X12"},{"t":"닭 — 씨, 개 — 새끼, 강낭콩 — 알","mis":"SC3-1-u4-X33"}],"explanation":["하나씩 떠올려요.","알·새끼·씨예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#21','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C46',3,'mc','auto','잠자리 애벌레와 배추흰나비 애벌레의 다른 점은 무엇인가요?',ARRAY['SC3-1-u4-X39']::text[],false,'{"seq":21,"concept":"SC3-1-u4-C46","difficulty":3,"kind":"mc","stem":"잠자리 애벌레와 배추흰나비 애벌레의 다른 점은 무엇인가요?","options":[{"t":"잠자리 애벌레는 물속에서 살아요","correct":true},{"t":"잠자리 애벌레는 하늘을 날아요","mis":"SC3-1-u4-X39"},{"t":"배추흰나비 애벌레는 물속에서 살아요","mis":"SC3-1-u4-X39"},{"t":"둘은 사는 곳이 같아요","mis":"SC3-1-u4-X39"}],"explanation":["사는 곳을 견줘요.","물속이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#22','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C40',3,'mc','auto','생물 한살이 소개 카드에 넣지 않아도 되는 것은 무엇인가요?',ARRAY['SC3-1-u4-X34','SC3-1-u4-X40']::text[],false,'{"seq":22,"concept":"SC3-1-u4-C40","difficulty":3,"kind":"mc","stem":"생물 한살이 소개 카드에 넣지 않아도 되는 것은 무엇인가요?","options":[{"t":"내가 좋아하는 색깔","correct":true},{"t":"생물의 이름","mis":"SC3-1-u4-X34"},{"t":"한살이 순서","mis":"SC3-1-u4-X40"},{"t":"생물의 특징","mis":"SC3-1-u4-X34"}],"explanation":["생물을 알려 줘요.","내 취향은 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#23','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C10',4,'mc','auto','들꽃반 일지 ②의 친구 나에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X08','SC3-1-u4-X05']::text[],false,'{"seq":23,"concept":"SC3-1-u4-C10","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ②의 친구 나에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「번데기는 움직이지 않을 뿐 살아 있어. 버리지 말고 어른벌레가 나올 때까지 지켜보자.」","correct":true},{"t":"「맞아, 움직이지 않으니 버리자.」","mis":"SC3-1-u4-X08"},{"t":"「번데기를 흔들어서 깨워 보자.」","mis":"SC3-1-u4-X05"},{"t":"「번데기는 잎을 먹어야 하니 잎을 넣어 주자.」","mis":"SC3-1-u4-X08"}],"explanation":["넷째 줄을 읽어요.","어른벌레가 나왔어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["배춧잎 뒷면에서 노란 알을 찾았다.","얼마 뒤 초록색 애벌레가 잎을 갉아 먹으며 허물을 벗었다.","애벌레는 한곳에 붙어 움직이지 않는 번데기가 되었다.","번데기에서 날개 두 쌍, 다리 세 쌍인 어른벌레가 나왔다.","친구 나 — 「번데기는 꼼짝 안 하니 죽은 거야. 버리자.」"],"title":"들꽃반 일지 ② 배추흰나비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#24','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C36',4,'mc','auto','들꽃반 일지 ⑥의 친구 다에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X30','SC3-1-u4-X29']::text[],false,'{"seq":24,"concept":"SC3-1-u4-C36","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ⑥의 친구 다에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「민들레는 풀이지만 겨울을 나고 봄에 다시 자라. 사는 기간으로 보면 여러해살이야.」","correct":true},{"t":"「맞아, 풀은 다 한해살이야.」","mis":"SC3-1-u4-X30"},{"t":"「민들레는 나무라서 여러해살이야.」","mis":"SC3-1-u4-X30"},{"t":"「감나무도 한 해만 살아.」","mis":"SC3-1-u4-X29"}],"explanation":["민들레를 봐요.","봄에 다시 자랐어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["학교 텃밭의 강낭콩은 가을에 씨를 남기고 시들었다.","운동장 감나무는 올해도 감이 열렸다.","화단 민들레는 겨울을 나고 봄에 다시 자랐다.","친구 다 — 「민들레는 풀이니까 한해살이야.」"],"title":"들꽃반 일지 ⑥ 식물의 한살이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_b#25','sci',3,1,'u4','','g3_1_sci_u4_review_b','unit_review','SC3-1-u4-C16',4,'essay','teacher','들꽃반 일지 ③을 보고 알을 낳는 동물과 새끼를 낳는 동물을 하나씩 골라 한살이를 견주어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u4-C16","difficulty":4,"kind":"essay","stem":"들꽃반 일지 ③을 보고 알을 낳는 동물과 새끼를 낳는 동물을 하나씩 골라 한살이를 견주어 쓰세요.","answer_guide":{"answer":"예: 닭은 알을 낳고, 알에서 병아리가 깨어나 어린 닭을 거쳐 다 자란 닭이 된다. 개는 새끼를 낳아 어미젖을 먹여 키우고, 강아지가 자라 다 자란 개가 된다.","scoring_points":["알을 낳는 동물과 새끼를 낳는 동물을 바르게 골랐는가","두 동물의 한살이를 썼는가","태어나는 방법이 다르다는 점이 드러나는가"]},"explanation":["일지를 읽어요.","닭과 개예요.","견주어 써요."],"asset":{"type":"passage","lines":["동물 농장에 갔다.","닭은 알을 낳았고, 알에서 병아리가 깨어났다.","개는 강아지를 낳아 어미젖을 먹였다.","소는 송아지를 낳았다.","친구 다 — 「동물은 다 알에서 깨어나.」"],"title":"들꽃반 일지 ③ 동물 농장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#1','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C2',1,'ox','auto','들꽃반 일지 ①의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u4-X02']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C2","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ①의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"병아리는 작은 모습으로 깨어나 자라면서 점점 어미 닭의 모습이 되기 때문에","correct":true},{"t":"생물은 평생 똑같이 생겼기 때문에","mis":"SC3-1-u4-X02"}],"mis":"SC3-1-u4-X02","explanation":["병아리와 어미 닭을 견줘요.","자라며 변해요.","그래서 X예요."],"asset":{"type":"passage","lines":["학교 둘레에서 생물을 찾았다.","화단에서 봉숭아를, 연못가에서 올챙이를 보았다.","닭장에서는 어미 닭과 병아리를 보았다.","친구 가 — 「병아리는 처음부터 어미 닭이랑 똑같이 생겼어.」"],"title":"들꽃반 일지 ① 주변의 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#2','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C9',1,'mc','auto','들꽃반 일지 ②에서 허물을 벗은 단계는 무엇인가요?',ARRAY['SC3-1-u4-X07','SC3-1-u4-X08']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C9","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ②에서 허물을 벗은 단계는 무엇인가요?","options":[{"t":"애벌레","correct":true},{"t":"알","mis":"SC3-1-u4-X07"},{"t":"번데기","mis":"SC3-1-u4-X08"},{"t":"어른벌레","mis":"SC3-1-u4-X07"}],"explanation":["둘째 줄을 읽어요.","초록색이에요.","애벌레예요."],"asset":{"type":"passage","lines":["배춧잎 뒷면에서 노란 알을 찾았다.","얼마 뒤 초록색 애벌레가 잎을 갉아 먹으며 허물을 벗었다.","애벌레는 한곳에 붙어 움직이지 않는 번데기가 되었다.","번데기에서 날개 두 쌍, 다리 세 쌍인 어른벌레가 나왔다.","친구 나 — 「번데기는 꼼짝 안 하니 죽은 거야. 버리자.」"],"title":"들꽃반 일지 ② 배추흰나비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#3','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C20',1,'ox','auto','들꽃반 일지 ③의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u4-X12']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C20","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ③의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"닭은 알을 낳지만 개와 소는 새끼를 낳기 때문에","correct":true},{"t":"동물은 하나같이 알에서 깨어나기 때문에","mis":"SC3-1-u4-X12"}],"mis":"SC3-1-u4-X12","explanation":["개와 소를 봐요.","새끼를 낳았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["동물 농장에 갔다.","닭은 알을 낳았고, 알에서 병아리가 깨어났다.","개는 강아지를 낳아 어미젖을 먹였다.","소는 송아지를 낳았다.","친구 다 — 「동물은 다 알에서 깨어나.」"],"title":"들꽃반 일지 ③ 동물 농장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#4','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C24',1,'ox','auto','들꽃반 일지 ④의 친구 가의 말은 알맞아요.',ARRAY['SC3-1-u4-X20']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C24","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ④의 친구 가의 말은 알맞아요.","answer":"X","reason_options":[{"t":"씨가 싹 트는 데 필요한 것은 물과 알맞은 온도이고, 빛은 꼭 필요한 것이 아니기 때문에","correct":true},{"t":"빛이 없으면 씨는 절대 싹이 트지 않기 때문에","mis":"SC3-1-u4-X20"}],"mis":"SC3-1-u4-X20","explanation":["싹 트는 조건을 떠올려요.","물과 온도예요.","그래서 X예요."],"asset":{"type":"passage","lines":["컵 두 개에 탈지면을 깔고 같은 강낭콩을 넣었다.","두 컵 모두 따뜻한 곳에 두고, ㉮ 컵에만 물을 주었다.","얼마 뒤 ㉮ 컵의 강낭콩만 싹이 텄다.","친구 가 — 「싹 트는 데는 빛이 꼭 있어야 해.」"],"title":"들꽃반 일지 ④ 씨앗 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#5','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C30',1,'ox','auto','들꽃반 일지 ⑤의 친구 나의 말은 알맞아요.',ARRAY['SC3-1-u4-X26']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C30","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ⑤의 친구 나의 말은 알맞아요.","answer":"X","reason_options":[{"t":"물을 같게 주었어도 햇빛을 받지 못한 ㉯는 잘 자라지 못했기 때문에","correct":true},{"t":"물만 주면 햇빛이 없어도 잘 자라기 때문에","mis":"SC3-1-u4-X26"}],"mis":"SC3-1-u4-X26","explanation":["㉯를 봐요.","물은 받았어요.","그래서 X예요."],"asset":{"type":"passage","lines":["어린 식물 두 화분에 물을 같게 주었다.","㉮ 화분은 창가에, ㉯ 화분은 어두운 상자 안에 두었다.","얼마 뒤 ㉮ 화분만 잘 자랐다.","친구 나 — 「식물은 물만 있으면 잘 자라.」"],"title":"들꽃반 일지 ⑤ 화분 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#6','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C36',1,'ox','auto','들꽃반 일지 ⑥의 친구 다의 말은 알맞아요.',ARRAY['SC3-1-u4-X30']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C36","difficulty":1,"kind":"ox","stem":"들꽃반 일지 ⑥의 친구 다의 말은 알맞아요.","answer":"X","reason_options":[{"t":"민들레는 풀이지만 겨울을 나고 봄에 다시 자라는 여러해살이이기 때문에","correct":true},{"t":"풀은 하나같이 한 해만 살기 때문에","mis":"SC3-1-u4-X30"}],"mis":"SC3-1-u4-X30","explanation":["셋째 줄을 읽어요.","봄에 다시 자랐어요.","그래서 X예요."],"asset":{"type":"passage","lines":["학교 텃밭의 강낭콩은 가을에 씨를 남기고 시들었다.","운동장 감나무는 올해도 감이 열렸다.","화단 민들레는 겨울을 나고 봄에 다시 자랐다.","친구 다 — 「민들레는 풀이니까 한해살이야.」"],"title":"들꽃반 일지 ⑥ 식물의 한살이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#7','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C42',1,'mc','auto','들꽃반 일지 ⑦에서 개의 한살이를 바르게 적은 모둠은 어느 것인가요?',ARRAY['SC3-1-u4-X35','SC3-1-u4-X32']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C42","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑦에서 개의 한살이를 바르게 적은 모둠은 어느 것인가요?","options":[{"t":"모둠 1","correct":true},{"t":"모둠 2","mis":"SC3-1-u4-X35"},{"t":"모둠 3","mis":"SC3-1-u4-X32"},{"t":"바르게 적은 모둠이 없어요","mis":"SC3-1-u4-X35"}],"explanation":["개를 찾아요.","강아지부터예요.","모둠 1이에요."],"asset":{"type":"passage","lines":["모둠마다 생물의 한살이 소개 카드를 만들었다.","모둠 1 — 개: 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","모둠 2 — 강낭콩: 씨 → 싹 → 자람 → 꽃 → 열매","모둠 3 — 돌: 작은 돌 → 큰 돌","친구 가 — 「모둠 3처럼 돌도 한살이가 있어.」"],"title":"들꽃반 일지 ⑦ 소개 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#8','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C44',1,'mc','auto','들꽃반 일지 ⑧에서 번데기를 거치는 곤충은 무엇인가요?',ARRAY['SC3-1-u4-X38','SC3-1-u4-X37']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C44","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑧에서 번데기를 거치는 곤충은 무엇인가요?","options":[{"t":"무당벌레","correct":true},{"t":"메뚜기","mis":"SC3-1-u4-X38"},{"t":"잠자리","mis":"SC3-1-u4-X38"},{"t":"세 곤충 모두","mis":"SC3-1-u4-X37"}],"explanation":["셋째 줄을 읽어요.","번데기를 거쳐요.","무당벌레예요."],"asset":{"type":"passage","lines":["연못에서 잠자리 애벌레를 보았다. 물속에서 살고 있었다.","풀밭에서 메뚜기와 무당벌레를 보았다.","무당벌레는 번데기를 거치고, 메뚜기는 번데기 없이 자란다고 한다.","친구 나 — 「곤충은 다 번데기를 거쳐.」"],"title":"들꽃반 일지 ⑧ 곤충"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#9','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C6',2,'ox','auto','생물의 한살이는 한 번 보기만 해도 다 알 수 있어요.',ARRAY['SC3-1-u4-X05']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C6","difficulty":2,"kind":"ox","stem":"생물의 한살이는 한 번 보기만 해도 다 알 수 있어요.","answer":"X","reason_options":[{"t":"생물은 시간이 지나며 조금씩 모습이 변하므로 꾸준히 관찰해야 알 수 있기 때문에","correct":true},{"t":"생물은 하루 만에 다 자라기 때문에","mis":"SC3-1-u4-X05"}],"mis":"SC3-1-u4-X05","explanation":["생물은 천천히 변해요.","꾸준히 봐요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#10','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C13',2,'ox','auto','애벌레는 허물을 벗으며 몸이 커져요.',ARRAY['SC3-1-u4-X10']::text[],false,'{"seq":10,"concept":"SC3-1-u4-C13","difficulty":2,"kind":"ox","stem":"애벌레는 허물을 벗으며 몸이 커져요.","answer":"O","reason_options":[{"t":"허물을 벗어야 더 크게 자랄 수 있기 때문에","correct":true},{"t":"허물을 벗으면 몸이 작아지기 때문에","mis":"SC3-1-u4-X10"}],"mis":"SC3-1-u4-X10","explanation":["허물을 떠올려요.","벗고 커져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#11','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C16',2,'ox','auto','돌고래는 바다에 살지만 새끼를 낳아 어미젖을 먹여 키워요.',ARRAY['SC3-1-u4-X13']::text[],false,'{"seq":11,"concept":"SC3-1-u4-C16","difficulty":2,"kind":"ox","stem":"돌고래는 바다에 살지만 새끼를 낳아 어미젖을 먹여 키워요.","answer":"O","reason_options":[{"t":"돌고래는 새끼를 낳는 동물이기 때문에","correct":true},{"t":"물에 사는 동물은 하나같이 알을 낳기 때문에","mis":"SC3-1-u4-X13"}],"mis":"SC3-1-u4-X13","explanation":["돌고래를 떠올려요.","새끼를 낳아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#12','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C23',2,'mc','auto','씨가 싹 트기에 알맞은 곳은 어디인가요?',ARRAY['SC3-1-u4-X18','SC3-1-u4-X19','SC3-1-u4-X20']::text[],false,'{"seq":12,"concept":"SC3-1-u4-C23","difficulty":2,"kind":"mc","stem":"씨가 싹 트기에 알맞은 곳은 어디인가요?","options":[{"t":"물기가 있고 알맞게 따뜻한 곳","correct":true},{"t":"물기가 없는 마른 곳","mis":"SC3-1-u4-X18"},{"t":"얼음처럼 차가운 냉동실 안","mis":"SC3-1-u4-X19"},{"t":"밤에도 불을 환하게 켠 곳만","mis":"SC3-1-u4-X20"}],"explanation":["두 조건이에요.","물과 온도예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#13','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C32',2,'mc','auto','씨가 싹 틀 때는 꼭 필요하지 않았지만 식물이 자랄 때는 필요한 것은 무엇인가요?',ARRAY['SC3-1-u4-X27','SC3-1-u4-X23','SC3-1-u4-X25']::text[],false,'{"seq":13,"concept":"SC3-1-u4-C32","difficulty":2,"kind":"mc","stem":"씨가 싹 틀 때는 꼭 필요하지 않았지만 식물이 자랄 때는 필요한 것은 무엇인가요?","options":[{"t":"햇빛","correct":true},{"t":"물","mis":"SC3-1-u4-X27"},{"t":"소리","mis":"SC3-1-u4-X23"},{"t":"어둠","mis":"SC3-1-u4-X25"}],"explanation":["어두워도 싹은 텄어요.","자랄 때는 달라요.","햇빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#14','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C33',2,'mc','auto','모든 식물의 한살이에 들어 있는 차례로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X28','SC3-1-u4-X33']::text[],false,'{"seq":14,"concept":"SC3-1-u4-C33","difficulty":2,"kind":"mc","stem":"모든 식물의 한살이에 들어 있는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"씨 → 싹 → 자람 → 꽃 → 열매","correct":true},{"t":"꽃 → 씨 → 열매 → 싹 → 자람","mis":"SC3-1-u4-X28"},{"t":"열매 → 꽃 → 싹 → 씨 → 자람","mis":"SC3-1-u4-X28"},{"t":"알 → 애벌레 → 번데기 → 어른벌레","mis":"SC3-1-u4-X33"}],"explanation":["씨에서 시작해요.","열매로 끝나요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#15','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C40',2,'ox','auto','소개 자료에 생물의 이름과 특징을 함께 넣으면 더 좋아요.',ARRAY['SC3-1-u4-X34']::text[],false,'{"seq":15,"concept":"SC3-1-u4-C40","difficulty":2,"kind":"ox","stem":"소개 자료에 생물의 이름과 특징을 함께 넣으면 더 좋아요.","answer":"O","reason_options":[{"t":"보는 사람이 어떤 생물인지, 어떤 점이 특별한지 함께 알 수 있기 때문에","correct":true},{"t":"소개 자료에는 그림 꾸미기만 있으면 되기 때문에","mis":"SC3-1-u4-X34"}],"mis":"SC3-1-u4-X34","explanation":["보는 사람을 생각해요.","이름과 특징이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#16','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C45',2,'mc','auto','메뚜기의 한살이로 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X37','SC3-1-u4-X36','SC3-1-u4-X33']::text[],false,'{"seq":16,"concept":"SC3-1-u4-C45","difficulty":2,"kind":"mc","stem":"메뚜기의 한살이로 알맞은 것은 무엇인가요?","options":[{"t":"알 → 애벌레 → 어른벌레","correct":true},{"t":"알 → 애벌레 → 번데기 → 어른벌레","mis":"SC3-1-u4-X37"},{"t":"새끼 → 어른벌레","mis":"SC3-1-u4-X36"},{"t":"씨 → 싹 → 꽃 → 열매","mis":"SC3-1-u4-X33"}],"explanation":["메뚜기는 번데기가 없어요.","세 단계예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#17','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C18',3,'ox','auto','강아지는 어미젖을 먹고 자라 다 자란 개가 돼요.',ARRAY['SC3-1-u4-X15']::text[],false,'{"seq":17,"concept":"SC3-1-u4-C18","difficulty":3,"kind":"ox","stem":"강아지는 어미젖을 먹고 자라 다 자란 개가 돼요.","answer":"O","reason_options":[{"t":"개는 새끼를 낳아 어미젖을 먹여 키우는 동물이기 때문에","correct":true},{"t":"강아지는 알에서 깨어나 혼자 먹이를 찾기 때문에","mis":"SC3-1-u4-X15"}],"mis":"SC3-1-u4-X15","explanation":["강아지를 떠올려요.","젖을 먹어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#18','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C24',3,'ox','auto','어두운 곳에 둔 씨도 물과 알맞은 온도가 있으면 싹이 틀 수 있어요.',ARRAY['SC3-1-u4-X20']::text[],false,'{"seq":18,"concept":"SC3-1-u4-C24","difficulty":3,"kind":"ox","stem":"어두운 곳에 둔 씨도 물과 알맞은 온도가 있으면 싹이 틀 수 있어요.","answer":"O","reason_options":[{"t":"씨가 싹 트는 데는 빛이 꼭 필요하지 않기 때문에","correct":true},{"t":"빛이 없으면 씨는 싹이 트지 않기 때문에","mis":"SC3-1-u4-X20"}],"mis":"SC3-1-u4-X20","explanation":["어두운 컵을 떠올려요.","싹이 텄어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#19','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C34',3,'mc','auto','봄에 심은 나팔꽃이 가을에 씨를 남기고 시들었어요. 나팔꽃은 어떤 식물인가요?',ARRAY['SC3-1-u4-X29','SC3-1-u4-X30','SC3-1-u4-X32']::text[],false,'{"seq":19,"concept":"SC3-1-u4-C34","difficulty":3,"kind":"mc","stem":"봄에 심은 나팔꽃이 가을에 씨를 남기고 시들었어요. 나팔꽃은 어떤 식물인가요?","options":[{"t":"한해살이 식물","correct":true},{"t":"여러해살이 식물","mis":"SC3-1-u4-X29"},{"t":"나무","mis":"SC3-1-u4-X30"},{"t":"한살이가 없는 식물","mis":"SC3-1-u4-X32"}],"explanation":["한 해로 마쳤어요.","씨를 남겼어요.","한해살이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#20','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C38',3,'ox','auto','생물만 나고 자라 자손을 남기는 한살이가 있어요.',ARRAY['SC3-1-u4-X32']::text[],false,'{"seq":20,"concept":"SC3-1-u4-C38","difficulty":3,"kind":"ox","stem":"생물만 나고 자라 자손을 남기는 한살이가 있어요.","answer":"O","reason_options":[{"t":"돌이나 자동차 같은 물건은 자라거나 자손을 남기지 않기 때문에","correct":true},{"t":"물건도 오래 쓰면 자라서 자손을 남기기 때문에","mis":"SC3-1-u4-X32"}],"mis":"SC3-1-u4-X32","explanation":["물건을 떠올려요.","자라지 않아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#21','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C44',3,'ox','auto','무당벌레와 배추흰나비는 둘 다 번데기 단계를 거쳐요.',ARRAY['SC3-1-u4-X36']::text[],false,'{"seq":21,"concept":"SC3-1-u4-C44","difficulty":3,"kind":"ox","stem":"무당벌레와 배추흰나비는 둘 다 번데기 단계를 거쳐요.","answer":"O","reason_options":[{"t":"둘 다 알 → 애벌레 → 번데기 → 어른벌레로 자라기 때문에","correct":true},{"t":"무당벌레는 새끼로 태어나기 때문에","mis":"SC3-1-u4-X36"}],"mis":"SC3-1-u4-X36","explanation":["두 곤충을 떠올려요.","번데기가 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#22','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C29',3,'ox','auto','씨가 싹 틀 때 빛이 필요 없었으니, 싹이 튼 뒤에도 어두운 곳에 두면 잘 자라요.',ARRAY['SC3-1-u4-X27']::text[],false,'{"seq":22,"concept":"SC3-1-u4-C29","difficulty":3,"kind":"ox","stem":"씨가 싹 틀 때 빛이 필요 없었으니, 싹이 튼 뒤에도 어두운 곳에 두면 잘 자라요.","answer":"X","reason_options":[{"t":"식물이 자랄 때는 햇빛이 꼭 필요하기 때문에","correct":true},{"t":"빛은 싹 틀 때도 자랄 때도 필요 없기 때문에","mis":"SC3-1-u4-X27"}],"mis":"SC3-1-u4-X27","explanation":["자랄 때를 떠올려요.","햇빛이 필요해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#23','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C20',4,'mc','auto','들꽃반 일지 ③의 친구 다에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X12','SC3-1-u4-X13','SC3-1-u4-X33']::text[],false,'{"seq":23,"concept":"SC3-1-u4-C20","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ③의 친구 다에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「닭은 알을 낳지만 개와 소는 새끼를 낳아. 동물마다 태어나는 방법이 달라.」","correct":true},{"t":"「맞아, 강아지도 알에서 깨어났어.」","mis":"SC3-1-u4-X12"},{"t":"「소는 알을 낳고 닭은 새끼를 낳아.」","mis":"SC3-1-u4-X13"},{"t":"「동물은 하나같이 씨에서 시작해.」","mis":"SC3-1-u4-X33"}],"explanation":["개와 소를 봐요.","새끼를 낳았어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["동물 농장에 갔다.","닭은 알을 낳았고, 알에서 병아리가 깨어났다.","개는 강아지를 낳아 어미젖을 먹였다.","소는 송아지를 낳았다.","친구 다 — 「동물은 다 알에서 깨어나.」"],"title":"들꽃반 일지 ③ 동물 농장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#24','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C38',4,'mc','auto','들꽃반 일지 ⑦의 친구 가에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X32','SC3-1-u4-X34','SC3-1-u4-X13']::text[],false,'{"seq":24,"concept":"SC3-1-u4-C38","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ⑦의 친구 가에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「돌은 생물이 아니라서 나고 자라 자손을 남기지 않아. 모둠 3은 생물을 골라 다시 만들자.」","correct":true},{"t":"「맞아, 돌도 자라서 큰 돌이 돼.」","mis":"SC3-1-u4-X32"},{"t":"「모둠 3은 색만 화려하게 칠하면 돼.」","mis":"SC3-1-u4-X34"},{"t":"「모둠 1의 개는 알로 시작해야 해.」","mis":"SC3-1-u4-X13"}],"explanation":["돌을 떠올려요.","생물이 아니에요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["모둠마다 생물의 한살이 소개 카드를 만들었다.","모둠 1 — 개: 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","모둠 2 — 강낭콩: 씨 → 싹 → 자람 → 꽃 → 열매","모둠 3 — 돌: 작은 돌 → 큰 돌","친구 가 — 「모둠 3처럼 돌도 한살이가 있어.」"],"title":"들꽃반 일지 ⑦ 소개 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_c#25','sci',3,1,'u4','','g3_1_sci_u4_review_c','unit_review','SC3-1-u4-C32',4,'essay','teacher','씨가 싹 틀 때와 식물이 자랄 때 필요한 조건을 견주어 쓰고, 들꽃반 일지 ⑤의 친구 나의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u4-C32","difficulty":4,"kind":"essay","stem":"씨가 싹 틀 때와 식물이 자랄 때 필요한 조건을 견주어 쓰고, 들꽃반 일지 ⑤의 친구 나의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 씨가 싹 틀 때는 물과 알맞은 온도가 필요하고, 식물이 자랄 때는 물과 햇빛이 필요하다. 식물은 물만 있다고 잘 자라는 것이 아니라 햇빛도 받아야 잘 자란다.","scoring_points":["싹 틀 때의 조건(물·알맞은 온도)을 썼는가","자랄 때의 조건(물·햇빛)을 썼는가","햇빛도 필요하다고 친구 나의 말을 고쳤는가"]},"explanation":["두 실험을 떠올려요.","온도와 햇빛이 달라요.","견주고 고쳐 써요."],"asset":{"type":"passage","lines":["어린 식물 두 화분에 물을 같게 주었다.","㉮ 화분은 창가에, ㉯ 화분은 어두운 상자 안에 두었다.","얼마 뒤 ㉮ 화분만 잘 자랐다.","친구 나 — 「식물은 물만 있으면 잘 자라.」"],"title":"들꽃반 일지 ⑤ 화분 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#1','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C4',1,'mc','auto','들꽃반 일지 ①의 올챙이가 다 자라면 무엇이 되나요?',ARRAY['SC3-1-u4-X03']::text[],false,'{"seq":1,"concept":"SC3-1-u4-C4","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ①의 올챙이가 다 자라면 무엇이 되나요?","options":[{"t":"개구리","correct":true},{"t":"닭","mis":"SC3-1-u4-X03"},{"t":"나비","mis":"SC3-1-u4-X03"},{"t":"봉숭아","mis":"SC3-1-u4-X03"}],"explanation":["올챙이를 떠올려요.","다리가 생겨요.","개구리예요."],"asset":{"type":"passage","lines":["학교 둘레에서 생물을 찾았다.","화단에서 봉숭아를, 연못가에서 올챙이를 보았다.","닭장에서는 어미 닭과 병아리를 보았다.","친구 가 — 「병아리는 처음부터 어미 닭이랑 똑같이 생겼어.」"],"title":"들꽃반 일지 ① 주변의 생물"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#2','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C11',1,'mc','auto','들꽃반 일지 ②에서 날개 두 쌍, 다리 세 쌍인 단계는 무엇인가요?',ARRAY['SC3-1-u4-X07','SC3-1-u4-X08']::text[],false,'{"seq":2,"concept":"SC3-1-u4-C11","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ②에서 날개 두 쌍, 다리 세 쌍인 단계는 무엇인가요?","options":[{"t":"어른벌레","correct":true},{"t":"알","mis":"SC3-1-u4-X07"},{"t":"애벌레","mis":"SC3-1-u4-X07"},{"t":"번데기","mis":"SC3-1-u4-X08"}],"explanation":["넷째 줄을 읽어요.","날개가 있어요.","어른벌레예요."],"asset":{"type":"passage","lines":["배춧잎 뒷면에서 노란 알을 찾았다.","얼마 뒤 초록색 애벌레가 잎을 갉아 먹으며 허물을 벗었다.","애벌레는 한곳에 붙어 움직이지 않는 번데기가 되었다.","번데기에서 날개 두 쌍, 다리 세 쌍인 어른벌레가 나왔다.","친구 나 — 「번데기는 꼼짝 안 하니 죽은 거야. 버리자.」"],"title":"들꽃반 일지 ② 배추흰나비"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#3','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C18',1,'mc','auto','들꽃반 일지 ③에서 개가 강아지에게 먹인 것은 무엇인가요?',ARRAY['SC3-1-u4-X15']::text[],false,'{"seq":3,"concept":"SC3-1-u4-C18","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ③에서 개가 강아지에게 먹인 것은 무엇인가요?","options":[{"t":"어미젖","correct":true},{"t":"알껍데기","mis":"SC3-1-u4-X15"},{"t":"꽃의 꿀","mis":"SC3-1-u4-X15"},{"t":"흙","mis":"SC3-1-u4-X15"}],"explanation":["셋째 줄을 읽어요.","젖이에요.","어미젖이에요."],"asset":{"type":"passage","lines":["동물 농장에 갔다.","닭은 알을 낳았고, 알에서 병아리가 깨어났다.","개는 강아지를 낳아 어미젖을 먹였다.","소는 송아지를 낳았다.","친구 다 — 「동물은 다 알에서 깨어나.」"],"title":"들꽃반 일지 ③ 동물 농장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#4','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C26',1,'mc','auto','들꽃반 일지 ④에서 두 컵을 같게 한 조건이 아닌 것은 무엇인가요?',ARRAY['SC3-1-u4-X22']::text[],false,'{"seq":4,"concept":"SC3-1-u4-C26","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ④에서 두 컵을 같게 한 조건이 아닌 것은 무엇인가요?","options":[{"t":"물 주기","correct":true},{"t":"강낭콩","mis":"SC3-1-u4-X22"},{"t":"두는 곳의 온도","mis":"SC3-1-u4-X22"},{"t":"탈지면","mis":"SC3-1-u4-X22"}],"explanation":["같게 한 것을 찾아요.","물만 달랐어요.","물 주기예요."],"asset":{"type":"passage","lines":["컵 두 개에 탈지면을 깔고 같은 강낭콩을 넣었다.","두 컵 모두 따뜻한 곳에 두고, ㉮ 컵에만 물을 주었다.","얼마 뒤 ㉮ 컵의 강낭콩만 싹이 텄다.","친구 가 — 「싹 트는 데는 빛이 꼭 있어야 해.」"],"title":"들꽃반 일지 ④ 씨앗 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#5','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C28',1,'mc','auto','들꽃반 일지 ⑤에서 두 화분에 같게 해 준 것은 무엇인가요?',ARRAY['SC3-1-u4-X22']::text[],false,'{"seq":5,"concept":"SC3-1-u4-C28","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑤에서 두 화분에 같게 해 준 것은 무엇인가요?","options":[{"t":"물 주기","correct":true},{"t":"햇빛 비추기","mis":"SC3-1-u4-X22"},{"t":"어두운 상자에 넣기","mis":"SC3-1-u4-X22"},{"t":"같게 한 것이 하나도 없어요","mis":"SC3-1-u4-X22"}],"explanation":["첫째 줄을 읽어요.","물이에요.","물 주기예요."],"asset":{"type":"passage","lines":["어린 식물 두 화분에 물을 같게 주었다.","㉮ 화분은 창가에, ㉯ 화분은 어두운 상자 안에 두었다.","얼마 뒤 ㉮ 화분만 잘 자랐다.","친구 나 — 「식물은 물만 있으면 잘 자라.」"],"title":"들꽃반 일지 ⑤ 화분 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#6','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C33',1,'mc','auto','들꽃반 일지 ⑥의 세 식물에 함께 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X29','SC3-1-u4-X30','SC3-1-u4-X28']::text[],false,'{"seq":6,"concept":"SC3-1-u4-C33","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑥의 세 식물에 함께 알맞은 것은 무엇인가요?","options":[{"t":"씨에서 시작해 꽃이 피고 열매를 맺어요","correct":true},{"t":"셋 다 한 해만 살아요","mis":"SC3-1-u4-X29"},{"t":"셋 다 나무예요","mis":"SC3-1-u4-X30"},{"t":"셋 다 씨 없이 자라요","mis":"SC3-1-u4-X28"}],"explanation":["같은 점을 찾아요.","씨에서 열매까지예요.","첫 번째예요."],"asset":{"type":"passage","lines":["학교 텃밭의 강낭콩은 가을에 씨를 남기고 시들었다.","운동장 감나무는 올해도 감이 열렸다.","화단 민들레는 겨울을 나고 봄에 다시 자랐다.","친구 다 — 「민들레는 풀이니까 한해살이야.」"],"title":"들꽃반 일지 ⑥ 식물의 한살이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#7','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C41',1,'mc','auto','들꽃반 일지 ⑦의 소개 카드에서 가장 중요한 것은 무엇인가요?',ARRAY['SC3-1-u4-X34']::text[],false,'{"seq":7,"concept":"SC3-1-u4-C41","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑦의 소개 카드에서 가장 중요한 것은 무엇인가요?","options":[{"t":"한살이 순서를 바르게 적기","correct":true},{"t":"카드를 화려하게 꾸미기","mis":"SC3-1-u4-X34"},{"t":"글씨를 크게만 쓰기","mis":"SC3-1-u4-X34"},{"t":"좋아하는 색으로 칠하기","mis":"SC3-1-u4-X34"}],"explanation":["한살이를 소개해요.","순서가 핵심이에요.","첫 번째예요."],"asset":{"type":"passage","lines":["모둠마다 생물의 한살이 소개 카드를 만들었다.","모둠 1 — 개: 갓 태어난 강아지 → 큰 강아지 → 다 자란 개","모둠 2 — 강낭콩: 씨 → 싹 → 자람 → 꽃 → 열매","모둠 3 — 돌: 작은 돌 → 큰 돌","친구 가 — 「모둠 3처럼 돌도 한살이가 있어.」"],"title":"들꽃반 일지 ⑦ 소개 카드"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#8','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C43',1,'mc','auto','들꽃반 일지 ⑧의 곤충들은 무엇으로 한살이를 시작하나요?',ARRAY['SC3-1-u4-X36','SC3-1-u4-X33','SC3-1-u4-X38']::text[],false,'{"seq":8,"concept":"SC3-1-u4-C43","difficulty":1,"kind":"mc","stem":"들꽃반 일지 ⑧의 곤충들은 무엇으로 한살이를 시작하나요?","options":[{"t":"알","correct":true},{"t":"새끼","mis":"SC3-1-u4-X36"},{"t":"씨","mis":"SC3-1-u4-X33"},{"t":"번데기","mis":"SC3-1-u4-X38"}],"explanation":["곤충의 처음이에요.","모두 같아요.","알이에요."],"asset":{"type":"passage","lines":["연못에서 잠자리 애벌레를 보았다. 물속에서 살고 있었다.","풀밭에서 메뚜기와 무당벌레를 보았다.","무당벌레는 번데기를 거치고, 메뚜기는 번데기 없이 자란다고 한다.","친구 나 — 「곤충은 다 번데기를 거쳐.」"],"title":"들꽃반 일지 ⑧ 곤충"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#9','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C4',2,'mc','auto','씨에서 갓 싹이 튼 강낭콩이 자라면 어떻게 될까요?',ARRAY['SC3-1-u4-X03','SC3-1-u4-X02']::text[],false,'{"seq":9,"concept":"SC3-1-u4-C4","difficulty":2,"kind":"mc","stem":"씨에서 갓 싹이 튼 강낭콩이 자라면 어떻게 될까요?","options":[{"t":"자라서 꽃이 피고 다시 씨를 맺어요","correct":true},{"t":"자라서 병아리가 돼요","mis":"SC3-1-u4-X03"},{"t":"싹 모습 그대로 자라지 않아요","mis":"SC3-1-u4-X02"},{"t":"자라서 나비가 돼요","mis":"SC3-1-u4-X03"}],"explanation":["강낭콩은 식물이에요.","꽃과 씨예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
