INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#11','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C17',2,'mc','auto','닭의 한살이에서 병아리 다음 모습은 무엇인가요?',ARRAY['SC3-1-u4-X14','SC3-1-u4-X13','SC3-1-u4-X03']::text[],false,'{"seq":11,"concept":"SC3-1-u4-C17","difficulty":2,"kind":"mc","stem":"닭의 한살이에서 병아리 다음 모습은 무엇인가요?","options":[{"t":"어린 닭","correct":true},{"t":"알","mis":"SC3-1-u4-X14"},{"t":"큰 강아지","mis":"SC3-1-u4-X13"},{"t":"올챙이","mis":"SC3-1-u4-X03"}],"explanation":["병아리가 자라요.","아직 다 자라지 않았어요.","어린 닭이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#12','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C26',2,'mc','auto','물 실험에서 두 컵에 같은 강낭콩을 쓰는 까닭은 무엇인가요?',ARRAY['SC3-1-u4-X22','SC3-1-u4-X21']::text[],false,'{"seq":12,"concept":"SC3-1-u4-C26","difficulty":2,"kind":"mc","stem":"물 실험에서 두 컵에 같은 강낭콩을 쓰는 까닭은 무엇인가요?","options":[{"t":"씨가 다르면 공정한 실험이 되지 않기 때문이에요","correct":true},{"t":"강낭콩이 가장 예뻐서요","mis":"SC3-1-u4-X22"},{"t":"한 컵에만 물을 주기 싫어서요","mis":"SC3-1-u4-X22"},{"t":"씨가 다를수록 결과를 잘 알 수 있어서요","mis":"SC3-1-u4-X21"}],"explanation":["물만 달라야 해요.","씨는 같게요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#13','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C31',2,'mc','auto','물이 식물이 자라는 데 필요한지 알아보는 실험에서 같게 할 조건은 무엇인가요?',ARRAY['SC3-1-u4-X22','SC3-1-u4-X21']::text[],false,'{"seq":13,"concept":"SC3-1-u4-C31","difficulty":2,"kind":"mc","stem":"물이 식물이 자라는 데 필요한지 알아보는 실험에서 같게 할 조건은 무엇인가요?","options":[{"t":"햇빛","correct":true},{"t":"물","mis":"SC3-1-u4-X22"},{"t":"물과 햇빛 모두 다르게 해요","mis":"SC3-1-u4-X21"},{"t":"같게 할 조건은 없어요","mis":"SC3-1-u4-X22"}],"explanation":["물을 알아봐요.","나머지는 같게요.","햇빛이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#14','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C37',2,'mc','auto','식물을 「한 해만 사는가?」로 나누었다가 「나무인가?」로 바꾸어 나누면 어떻게 될까요?',ARRAY['SC3-1-u4-X31']::text[],false,'{"seq":14,"concept":"SC3-1-u4-C37","difficulty":2,"kind":"mc","stem":"식물을 「한 해만 사는가?」로 나누었다가 「나무인가?」로 바꾸어 나누면 어떻게 될까요?","options":[{"t":"무리가 달라질 수 있어요","correct":true},{"t":"무리는 언제나 그대로예요","mis":"SC3-1-u4-X31"},{"t":"식물이 모두 사라져요","mis":"SC3-1-u4-X31"},{"t":"나무가 풀로 변해요","mis":"SC3-1-u4-X31"}],"explanation":["민들레를 떠올려요.","무리가 바뀌어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#15','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C42',2,'mc','auto','강낭콩 소개 카드에 알맞은 한살이는 무엇인가요?',ARRAY['SC3-1-u4-X35']::text[],false,'{"seq":15,"concept":"SC3-1-u4-C42","difficulty":2,"kind":"mc","stem":"강낭콩 소개 카드에 알맞은 한살이는 무엇인가요?","options":[{"t":"씨 → 싹 → 자람 → 꽃 → 열매","correct":true},{"t":"알 → 애벌레 → 번데기 → 어른벌레","mis":"SC3-1-u4-X35"},{"t":"갓 태어난 강아지 → 다 자란 개","mis":"SC3-1-u4-X35"},{"t":"알 → 병아리 → 다 자란 닭","mis":"SC3-1-u4-X35"}],"explanation":["강낭콩은 식물이에요.","씨로 시작해요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#16','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C46',2,'mc','auto','다음 곤충 가운데 애벌레가 물속에서 사는 것은 무엇인가요?',ARRAY['SC3-1-u4-X39']::text[],false,'{"seq":16,"concept":"SC3-1-u4-C46","difficulty":2,"kind":"mc","stem":"다음 곤충 가운데 애벌레가 물속에서 사는 것은 무엇인가요?","options":[{"t":"잠자리","correct":true},{"t":"매미","mis":"SC3-1-u4-X39"},{"t":"사슴벌레","mis":"SC3-1-u4-X39"},{"t":"배추흰나비","mis":"SC3-1-u4-X39"}],"explanation":["연못을 떠올려요.","물속 애벌레예요.","잠자리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#17','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C12',3,'mc','auto','다음 가운데 곤충끼리 모은 것은 무엇인가요?',ARRAY['SC3-1-u4-X09']::text[],false,'{"seq":17,"concept":"SC3-1-u4-C12","difficulty":3,"kind":"mc","stem":"다음 가운데 곤충끼리 모은 것은 무엇인가요?","options":[{"t":"개미, 배추흰나비, 메뚜기","correct":true},{"t":"거미, 개미, 메뚜기","mis":"SC3-1-u4-X09"},{"t":"배추흰나비, 참새, 개미","mis":"SC3-1-u4-X09"},{"t":"거미, 참새, 개구리","mis":"SC3-1-u4-X09"}],"explanation":["다리 세 쌍이에요.","거미·참새는 아니에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#18','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C30',3,'mc','auto','싹이 튼 강낭콩을 잘 자라게 하려면 어떻게 해야 할까요?',ARRAY['SC3-1-u4-X25','SC3-1-u4-X24','SC3-1-u4-X19']::text[],false,'{"seq":18,"concept":"SC3-1-u4-C30","difficulty":3,"kind":"mc","stem":"싹이 튼 강낭콩을 잘 자라게 하려면 어떻게 해야 할까요?","options":[{"t":"햇빛이 드는 곳에 두고 물을 알맞게 줘요","correct":true},{"t":"싹이 텄으니 어두운 곳에 두어도 돼요","mis":"SC3-1-u4-X25"},{"t":"물은 이제 주지 않아도 돼요","mis":"SC3-1-u4-X24"},{"t":"냉장고에 넣어 시원하게 둬요","mis":"SC3-1-u4-X19"}],"explanation":["자라는 조건이에요.","물과 햇빛이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#19','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C35',3,'mc','auto','겨울에 잎이 다 떨어진 감나무는 이듬해 어떻게 될까요?',ARRAY['SC3-1-u4-X29','SC3-1-u4-X30','SC3-1-u4-X28']::text[],false,'{"seq":19,"concept":"SC3-1-u4-C35","difficulty":3,"kind":"mc","stem":"겨울에 잎이 다 떨어진 감나무는 이듬해 어떻게 될까요?","options":[{"t":"다시 꽃이 피고 감을 맺어요","correct":true},{"t":"한살이를 마치고 시들어 없어져요","mis":"SC3-1-u4-X29"},{"t":"씨를 남기고 풀로 바뀌어요","mis":"SC3-1-u4-X30"},{"t":"다시는 꽃이 피지 않아요","mis":"SC3-1-u4-X28"}],"explanation":["감나무는 여러해살이예요.","해마다 열려요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#20','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C42',3,'mc','auto','배추흰나비 소개 카드에 특징으로 넣기에 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X35','SC3-1-u4-X34']::text[],false,'{"seq":20,"concept":"SC3-1-u4-C42","difficulty":3,"kind":"mc","stem":"배추흰나비 소개 카드에 특징으로 넣기에 알맞은 것은 무엇인가요?","options":[{"t":"번데기 때는 움직이지 않고 먹지 않아요","correct":true},{"t":"씨에서 싹이 터요","mis":"SC3-1-u4-X35"},{"t":"어미젖을 먹고 자라요","mis":"SC3-1-u4-X35"},{"t":"무지개색 날개가 가장 예뻐요","mis":"SC3-1-u4-X34"}],"explanation":["배추흰나비를 떠올려요.","번데기 이야기예요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#21','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C45',3,'mc','auto','매미의 한살이에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X37','SC3-1-u4-X39','SC3-1-u4-X36']::text[],false,'{"seq":21,"concept":"SC3-1-u4-C45","difficulty":3,"kind":"mc","stem":"매미의 한살이에 대해 알맞은 것은 무엇인가요?","options":[{"t":"번데기 없이, 땅속에서 오래 산 애벌레가 어른벌레가 돼요","correct":true},{"t":"번데기를 거쳐 어른벌레가 돼요","mis":"SC3-1-u4-X37"},{"t":"애벌레가 물속에서 살아요","mis":"SC3-1-u4-X39"},{"t":"새끼로 태어나요","mis":"SC3-1-u4-X36"}],"explanation":["매미는 번데기가 없어요.","애벌레는 땅속이에요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#22','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C16',3,'mc','auto','고양이가 새끼를 낳았어요. 새끼 고양이에 대해 알맞은 것은 무엇인가요?',ARRAY['SC3-1-u4-X13','SC3-1-u4-X37']::text[],false,'{"seq":22,"concept":"SC3-1-u4-C16","difficulty":3,"kind":"mc","stem":"고양이가 새끼를 낳았어요. 새끼 고양이에 대해 알맞은 것은 무엇인가요?","options":[{"t":"어미젖을 먹고 자라며 어미와 닮았어요","correct":true},{"t":"알을 깨고 나왔어요","mis":"SC3-1-u4-X13"},{"t":"번데기를 거쳐 자라요","mis":"SC3-1-u4-X37"},{"t":"물속에서 올챙이처럼 살아요","mis":"SC3-1-u4-X13"}],"explanation":["고양이는 새끼를 낳아요.","젖을 먹어요.","첫 번째예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#23','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C24',4,'mc','auto','들꽃반 일지 ④의 친구 가에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X20','SC3-1-u4-X23','SC3-1-u4-X18']::text[],false,'{"seq":23,"concept":"SC3-1-u4-C24","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ④의 친구 가에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「싹 트는 데는 물과 알맞은 온도가 필요해. 빛은 밝은 곳과 어두운 곳만 다르게 해서 확인해 보자.」","correct":true},{"t":"「맞아, 빛이 없으면 절대 싹이 트지 않아.」","mis":"SC3-1-u4-X20"},{"t":"「㉮ 컵이 싹 튼 것은 물이 아니라 빛 때문이야.」","mis":"SC3-1-u4-X23"},{"t":"「물을 주지 않아도 빛만 있으면 싹이 터.」","mis":"SC3-1-u4-X18"}],"explanation":["무엇을 다르게 했나요?","물이었어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["컵 두 개에 탈지면을 깔고 같은 강낭콩을 넣었다.","두 컵 모두 따뜻한 곳에 두고, ㉮ 컵에만 물을 주었다.","얼마 뒤 ㉮ 컵의 강낭콩만 싹이 텄다.","친구 가 — 「싹 트는 데는 빛이 꼭 있어야 해.」"],"title":"들꽃반 일지 ④ 씨앗 실험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#24','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C45',4,'mc','auto','들꽃반 일지 ⑧의 친구 나에게 가장 알맞게 답한 것은 무엇인가요?',ARRAY['SC3-1-u4-X37','SC3-1-u4-X39','SC3-1-u4-X36']::text[],false,'{"seq":24,"concept":"SC3-1-u4-C45","difficulty":4,"kind":"mc","stem":"들꽃반 일지 ⑧의 친구 나에게 가장 알맞게 답한 것은 무엇인가요?","options":[{"t":"「무당벌레는 번데기를 거치지만 메뚜기와 잠자리는 번데기 없이 자라. 곤충마다 한살이가 달라.」","correct":true},{"t":"「맞아, 메뚜기도 번데기를 거쳐.」","mis":"SC3-1-u4-X37"},{"t":"「잠자리 애벌레는 하늘을 날아.」","mis":"SC3-1-u4-X39"},{"t":"「곤충은 새끼로 태어나기도 해.」","mis":"SC3-1-u4-X36"}],"explanation":["셋째 줄을 읽어요.","메뚜기는 없어요.","첫 번째가 알맞아요."],"asset":{"type":"passage","lines":["연못에서 잠자리 애벌레를 보았다. 물속에서 살고 있었다.","풀밭에서 메뚜기와 무당벌레를 보았다.","무당벌레는 번데기를 거치고, 메뚜기는 번데기 없이 자란다고 한다.","친구 나 — 「곤충은 다 번데기를 거쳐.」"],"title":"들꽃반 일지 ⑧ 곤충"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g3_1_sci_u4_review_d#25','sci',3,1,'u4','','g3_1_sci_u4_review_d','unit_review','SC3-1-u4-C36',4,'essay','teacher','들꽃반 일지 ⑥을 보고 한해살이 식물과 여러해살이 식물을 하나씩 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC3-1-u4-C36","difficulty":4,"kind":"essay","stem":"들꽃반 일지 ⑥을 보고 한해살이 식물과 여러해살이 식물을 하나씩 쓰고, 친구 다의 말을 바르게 고쳐 쓰세요.","answer_guide":{"answer":"예: 강낭콩은 한해살이 식물이고 감나무는 여러해살이 식물이다. 민들레는 풀이지만 겨울을 나고 봄에 다시 자라므로 여러해살이 식물이다. 풀인지 나무인지가 아니라 사는 기간으로 나눈다.","scoring_points":["한해살이·여러해살이 식물을 하나씩 바르게 썼는가","민들레가 여러해살이라고 고쳤는가","사는 기간으로 나눈다는 까닭을 썼는가"]},"explanation":["일지를 읽어요.","민들레를 봐요.","고쳐 써요."],"asset":{"type":"passage","lines":["학교 텃밭의 강낭콩은 가을에 씨를 남기고 시들었다.","운동장 감나무는 올해도 감이 열렸다.","화단 민들레는 겨울을 나고 봄에 다시 자랐다.","친구 다 — 「민들레는 풀이니까 한해살이야.」"],"title":"들꽃반 일지 ⑥ 식물의 한살이"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
